WordHunterWoW_QuestEN[24897] = { title = "Get Back to Town", description = "We were wrong. It wasn't the naga that were preparing to attack... it was the nearby Oomlot tribe.\n\n{name}, you need to get back to the Town-In-A-Box. The pygmies are already attacking!\n\nHere, take this. We bought it off of a pygmy who said it used to belong to some great leader of theirs. Someone whose name translates as Dark Tan Helmet.\n\nIt should fool them so that they don't attack you.", objectives = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "<name>? We're saved!\n\nWho am I kidding? We're all going to die!!!" }
WordHunterWoW_QuestEN[24898] = { title = "Going, Going, Guano!", description = "There be more in the Razorfen than just pigs, <bruddah/sistah>. There be bats as well...and if you're goin in there and rilin' up the quilboar anyway, I want ya to bring me back some guano.\n\nYah, guano. The droppin's. Don't give me that look. It be foul, but powerful, primal stuff for rituals...rituals to keep the earth 'round here strong enough to keep from rippin' apart under all the damn fools warrin' round here.\n\nJust bring Zan'do one pile of guano, yah?Upon completion of this quest you will gain:", objectives = "Bring 1 pile of Kraul Guano to Zan'do at Firestone Point." }
WordHunterWoW_QuestEN[24899] = { title = "Going, Going, Guano!", description = "As you can see, <name>, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a <class>. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...Upon completion of this quest you will gain:", objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity." }
WordHunterWoW_QuestEN[24900] = { title = "Blueleaf Tubers", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.You will receive:", objectives = "In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers to Mebok Mizzyrix in Ratchet." }
WordHunterWoW_QuestEN[24901] = { title = "Town-In-A-Box: Under Attack", description = "{name}, you have to defend us!\n\nI had the eggheads deploy the town's cannon defenses, but it seems like there's an unlimited supply of these Oomlot warriors!\n\nGet your behind into one of those B.C. Eliminators and eliminate the pygmy threat to the town!", objectives = "Use a B.C. Eliminator to defeat 30 Oomlot Warriors.", progress = "That's not enough, hon. Can you take care of more of them?", completion = "Okay, I think that's good enough for now, but they took a bunch of the townsfolk captive.\n\nWe're going to have to take the fight to them!" }
WordHunterWoW_QuestEN[24902] = { title = "The Hunt For Sylvanas", description = "It's true then?  Gilneas has lost her favorite son.\n\nWe will mourn when this is all over but not a day sooner.\n\nWe will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air.\n\nMy father's men are ready to strike while we still have the Banshee Queen's trail.  Just say the word if you're ready.  Liam deserves swift vengeance.", objectives = "Follow Tobias Mistmantle in the Hunt for Sylvanas.\n\nIf you lose Tobias, return to Lorna Crowley and speak with her to call again for his aid.", progress = "Did you find her, <name>?", completion = "The Plague?  Something so heinous that not even the orcs condone its use?  I'd say this warrants notifying King Greymane." }
WordHunterWoW_QuestEN[24903] = { title = "Vengeance or Survival", description = "Tell Greymane that we have trackers on Sylvanas and tell him about the Plague.\n\nThe decision will be his.  Launch an all out attack against the leader of the Forsaken or try to evacuate our survivors.", objectives = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", completion = "You present me with the most difficult choice of my life, <name>." }
WordHunterWoW_QuestEN[24904] = { title = "The Battle for Gilneas City", description = "The time has come, {name}.  We've rallied and armed every available Gilnean.\n\nIt is time to meet the enemy head on.  Time to settle the score with Sylvanas and her Forsaken dogs once and for all.\n\nLiam is heading the assault from this gate.  King Greymane and my father are leading the assault on the other districts.\n\nYou have a crucial role to play in this as well.  Take this rapier.  Use it to inspire our men and women in combat.  Speak to Krennan Aranas to take part in the battle for Gilneas City.", objectives = "Achieve victory in the Battle for Gilneas City.", progress = "No...", completion = "We've driven the Forsaken back.  We hold three out of the four districts.\n\nBut at what cost..." }
WordHunterWoW_QuestEN[24905] = { title = "Returning a Favor", description = "You know, while you were out doin' your thing, Megs stopped by here. I hadn't seen her in months, but she barely gave me the time of day, just wanted me to tell you she had more business lined up.\n\nShe said she was headed over to the Dunemaul Compound to set up shop, something about ogres. Since you're done here, might as well head over...I wouldn't keep a goblin like her waiting.", objectives = "Find Megs Dreadshredder at the Dunemaul Camp.", completion = "I've got a great one for you this time, <name>. We're gonna initiate these ogres into the Horde...working directly under us." }
WordHunterWoW_QuestEN[24906] = { title = "Seaside Salvage", description = "We've got to get goods moving in this market ASAP if we want to be competitive. I've got an angle for us.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nHead down there and start salvaging; there's crates full of pure profit just floating around down there.", objectives = "Collect 7 Steamwheedle Supplies.", progress = "Let's see what you've got.", completion = "Hmm, mostly usable. This is good stuff. I've already got buyers lined up, of course.\n\nHere's your advance for the rest of the work you're gonna do for me and the Bilgewater Cartel...partner." }
WordHunterWoW_QuestEN[24907] = { title = "Puddle Stomping", description = "Here's the situation. If we want to establish the Bilgewater Cartel's market presence in Gadgetzan, we'll need to start providing services to the community.\n\nThe new coast has been great for business here, but the sea also brought sea giants with it. They're large, foul, and drive real estate values down.\n\nHead to the shallows just south of town and kill as many as you can, and I'll cut you in on some of the deals I'm brokering here.", objectives = "Kill 8 Tidal Striders.", completion = "Property values have already gone up since you left. People like seafront views that don't include briny, gnarled giants stomping around.\n\nHere's your cut, <name>." }
WordHunterWoW_QuestEN[24910] = { title = "Rocket Rescue", description = "Alright, {name}. We've done enough small jobs around here; it's time to seal the deal.\n\nThe ruins of Steamwheedle Port are still full of hapless Steamwheedle goblins, waiting to be rescued. Every single one of them is a potential future customer. They're firing on every boat that leaves port...so I say we take to the skies!\n\nThere's a hot air balloon just outside of town near the docks, we can use that. Go ahead and hop in, I'll catch up with you.", objectives = "Deliver Life-Rockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southshore Blockaders.", progress = "What's with the premature bail-out? We gotta get back out there.", completion = "Isn't it nice when you can do a good deed, and see enormous future financial gains from it? It warms my little goblin heart. And my big goblin wallet.\n\nYou did great, kid. Gadgetzan's gonna be ours soon. Here's a little token of my appreciation." }
WordHunterWoW_QuestEN[24911] = { title = "Tropical Paradise Beckons", description = "Hey, you look like a discriminating adventurer.  Are you looking for something different?  Something exotic?  Something... profitable?\n\nWell shake the sand out of your boots, because I've got a proposition for you.  Williden Marshal is looking for competent sellswords such as yourself.  He's set up camp at Marshal's Stand, just southeast of the volcano in the center of lush Un'Goro Crater.\n\nThen again, paradise isn't for everyone, {race}.  It's up to you.  Your tropical oasis awaits.", objectives = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", completion = "Hey Hol'anyee, look at the getup on this one!\n\n<Williden turns to face you.>\n\nAhem.  Our recruiter sent you?  Good.  Let's start out with a bit of honesty: Un'Goro isn't the perfect nirvana that you may have been promised.  You've probably figured that out on the way over here, though.\n\nShall we get to work?" }
WordHunterWoW_QuestEN[24912] = { title = "Empowerment", description = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", objectives = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", progress = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", completion = "Stand Clear, <class>, and steady yourself." }
WordHunterWoW_QuestEN[24913] = { title = "Remember the Light", description = "Magtoor grows weaker by the second, {name}. My remedy is prepared... it must work. It must!\n\nYou have done so much for the both of us. I would be honored if you stayed for what may be Magtoor's final moments.", objectives = "Help Anchorite Avuun say farewell to Magtoor.", completion = "I am moved, <name>. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.\n\nAnd yet, he came here, in person, to comfort a single dying soul.\n\nI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me." }
WordHunterWoW_QuestEN[24914] = { title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", objectives = "Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.\n\nProvided item:", completion = "<After tracing a complex pattern of runes on each of the box's surfaces, the outline of a lid appears and a click echoes through the chamber.>\n\nHere you are, <race>." }
WordHunterWoW_QuestEN[24915] = { title = "Mograine's Reunion", description = "What is that you hold, {class}?\n\nIt calls out to me, stirring feelings I thought to be long dead.", objectives = "What is that you hold, <class>?\n\nIt calls out to me, stirring feelings I thought to be long dead.", progress = "What is that you hold, <class>?\n\nIt calls out to me, stirring feelings I thought to be long dead.", completion = "Impossible...\n\nFather, is it you?!\n\nYou have done me a great service, hero. I offer you the reins of my faithful steed. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
WordHunterWoW_QuestEN[24916] = { title = "Jaina's Locket", description = "Yes, {class}? How can I assist you?", objectives = "Yes, <class>? How can I assist you?", progress = "Yes, <class>? How can I assist you?", completion = "What... how did you manage to come by this!?\n\nYou have done me a great service, hero. My heart could not bear to keep this locket, but I will place an enchantment upon it that you may find useful. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
WordHunterWoW_QuestEN[24917] = { title = "Muradin's Lament", description = "Whatdya got there, {race}?", objectives = "Whatdya got there, <race>?", progress = "Whatdya got there, <race>?", completion = "Aye. I know this blade... and I will treasure it always - a moment of time that will be lost forever.\n\nYou have done me a great service, hero. I offer you a gift from the Frostborn dwarves. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
WordHunterWoW_QuestEN[24918] = { title = "Sylvanas' Vengeance", description = "What is it, {race}?", objectives = "What is it, <race>?", progress = "What is it, <race>?", completion = "<Sylvanas silently reflects for a moment before returning her gaze to you.>\n\nYou have done me a great service, hero. I offer you the boon of the Banshee Queen. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
WordHunterWoW_QuestEN[24919] = { title = "The Lightbringer's Redemption", description = "How may I be of service, {race}?", objectives = "How may I be of service, <race>?", progress = "How may I be of service, <race>?", completion = "<Uther stares at the medal, speechless for a moment.>\n\nArthas' medal.\n\nI remember well the day I presented it to him...\n\nYou have done me a great service, hero. My soul may now rest in peace. I offer you a memory lost in time. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
WordHunterWoW_QuestEN[24920] = { title = "Slowing the Inevitable", description = "As much as I want to exact swift and brutal revenge... I must honor my son's memory first.  He cared for his people first and foremost.\n\nThe Undertaker's Pass goes underground below Northgate River.  You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic's Repose.\n\nWe captured one of the Forsaken's dreaded bombing bats.  I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people.  Hurry!", objectives = "Use the Captured Riding Bat to destroy 6 Forsaken Catapults and 40 Invading Forsaken.", progress = "Is it done, <name>?", completion = "You've done well, <name>.  Almost everybody managed to make it through." }
WordHunterWoW_QuestEN[24921] = { title = "Report to Aubrey", description = "You there! Fresh off the boat? Welcome to Kalimdor, a land hellbent to kill you or die tryin'.\n\nThere's trouble at the hold - as I'm sure you noticed on your way in. Admiral Aubrey needs all hands on deck if we're to make it through this. Consider yourself drafted, {class}!\n\nFollow the road up the hill and you'll find Aubrey in the tower, topside.", objectives = "Report to Admiral Aubrey in Northwatch Hold.", completion = "Hm? What unit are you with, <class>?\n\nNo matter, we need all hands. My fleet is in tatters and they've broken into the hold. You armed? That's good enough for me." }
WordHunterWoW_QuestEN[24922] = { title = "LFGDungeons - Burning Crusade - Heroic Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24923] = { title = "LFGDungeons - Burning Crusade - Heroic Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24924] = { title = "Oomlot Village", description = "The pygmies took most of our people back to their village. Who knows what evil they're up to?\n\n{name}, you have to go up there and free all of the captives before the pygmies work their voodoo on them!\n\nIzzy's already up near Oomlot Village to the southeast. She'll give you the heads-up on what's going down.\n\nYour pygmy helmet looks like it's in bad shape, but it should last long enough for you to get there.\n\nI hope.", objectives = "Speak with Izzy at Oomlot Village on the Lost Isles.", completion = "<name>? What are you doing wearing that pygmy helm? Looks like it's about to fall apart.\n\nI'm glad that they sent you up here. I thought for sure they were going to send that jerk, Grapplehammer and his ego-enabling assistant." }
WordHunterWoW_QuestEN[24925] = { title = "Free the Captives", description = "They've got a bunch of our people in there. I know that they're doing strange rituals to them. It looks like they're sucking the life force right out of them!\n\nYou have to go into the village and free the captives before it's too late!", objectives = "Free 5 Goblin Captives.", completion = "Great job, but that's not even half of the hostages that they took from town.\n\nDarn it all! They must have taken the rest of the captives to their other villages up in the volcano!" }
WordHunterWoW_QuestEN[24926] = { title = "Serving A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data that Karna needs.\n\nA-Me 01 not returning, though.  A-Me has new family now.  Here, with the gorillas, A-Me stay.\n\n<A-Me 01 detaches a small device from her hand and gives it to you.>\n\nYou bring data back to Karna.  You tell her what happen.", objectives = "Bring A-Me's Thumb Drive back to Karna Remtravel at Mossy Pile in Un'Goro Crater.", progress = "Wh... what's this?", completion = "She decided to stay?  Fascinating... I'll have to look over this data and find out why.\n\nThank you again, <name>. I really appreciate it." }
WordHunterWoW_QuestEN[24927] = { title = "Dead Man's Chest", description = "Look, babe, you should be able to see what's happening here pretty easily. There's pirates, there's goblins, the goblins are fighting the pirates. There's some sad little gnomes trying to fight the pirates too.\n\nI'll make it nice and simple for you: we need to kill a lot of pirates. Go do that, 'kay? We don't want the gnomes killing more than us, after all.", objectives = "Kill 15 Southsea Freebooters of any kind.", completion = "I'm pleased to report that our brand recognition in this area has skyrocketed now that you've killed most of the people who didn't want us here." }
WordHunterWoW_QuestEN[24928] = { title = "To The Ground!", description = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate.\n\nLuckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there.\n\nTry not to stand downwind.", objectives = "Set fire to the Northwest Shack, the Southeast Shack, and the Northeast Shack.", completion = "Wonderful job. Have you ever thought about becoming a full-time arsonist? I know a few people, it's a nice gig.\n\nWell, we'll chit-chat about that one later. More to do here!" }
WordHunterWoW_QuestEN[24929] = { title = "Send a Message", description = "The Oomlot leader, Yngwie, is too powerful to be left alive. He's barking nonsense from the raised west side of the village, across the rope bridge.\n\nGo up there and get him before he sends the rest of the village against us.\n\nPiece of cake!", objectives = "Slay Yngwie.", completion = "Nice work, bud! Hope he wasn't too tough." }
WordHunterWoW_QuestEN[24930] = { title = "While You're At It", description = "Fine by me if King Greymane wants you to risk your life to rescue a known traitor.\n\nDo me a favor and do something useful while you're out there and kill these cursed fleabags.", objectives = "Kill 5 Bloodfang Worgen.", progress = "What is it then, <name>?", completion = "If I hadn't seen you kill a few of the mangy things with my own eyes, I'd think you did not complete the task I asked of you.\n\nIt looks like we're hardly putting a dent in their numbers." }
WordHunterWoW_QuestEN[24931] = { title = "Gazer Tag", description = "You're going out to hunt hyenas, eh? If you don't mind, I've got an offer myself. I'm in need of eyes from the Glasshide Gazers that lurk to the north. Their eyes contain wonderful crystals, valuable to...collectors.\n\nNow, you may have heard that some sad individuals use these to enhance paramental abilities, but I assure you, my interests are purely academic!\n\nBring me a good portion of them and I'll pay you well for them. Better than these copper-pinching goblins will, at least!", objectives = "Collect 5 Ocular Crystals from Glasshide Gazers.", progress = "Do, ah, do you have them?", completion = "Ahh, perfect! Just what I need...full of potent focusing energies...\n\n...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!\n\nNow take your pay and be off!" }
WordHunterWoW_QuestEN[24932] = { title = "Cutting Losses", description = "I've spent the last week starin' at this ugly pit trying to think of how to exploit a bunch of dangerous, violent arthropods for profit. Now I'm out of ideas, and starving.\n\nThese things are a wash, and I say it's time to start clearing them out. Head down into that pit and start killin' bugs.", objectives = "Kill 15 Hazzali Silithid of any kind in the Gaping Chasm.", completion = "This isn't goin' fast enough. There's gotta be a faster way..." }
WordHunterWoW_QuestEN[24933] = { title = "Chicken of the Desert", description = "I've got an idea, but we're going to need bait.\n\nThe other day I saw a rabid blisterpaw hyena wander too close to the edge of the chasm, and one of the silithid comes diving out of nowhere. Nearly swallowed it whole! Horrible sight.\n\nSo we're gonna need hyena meat, obviously. Go gather some, make sure it's fresh, and bring it back here. There should be plenty just north of the camp.", objectives = "Collect 6 pieces of Hyena Meat.", progress = "This is fresh, right? They won't go after anything that's been withering in the sun.", completion = "Man, this stuff looks delicious. I'm half tempted to just fry some up myself.\n\nNo! We've gotta focus on gettin' out of here.\n\nMaybe just one piece..." }
WordHunterWoW_QuestEN[24934] = { title = "Repel Boarders!", description = "{name}, the sea is our only lifeline, and right now most of my fleet is either steaming back to Theramore for repairs or rusting at the bottom of this bay. Only the Blackpool remains afloat to defend our harbor.\n\nBut she's just signaled that she's being boarded!\n\nSpeak to me when you're ready, I'll have one of our naval gryphons deposit you right on the deck. Slaughter the rageroar sea dogs who dare assault my precious ship and report to Captain Fisher for further orders. ", objectives = "Speak to Admiral Aubrey to fly to the Blackpool and kill 6 Rageroar Sea Dogs.", progress = "Blood! All over my freshly polished brass.", completion = "You make a hell of a marine, <name>.\n\nWe'll mop up the others. But it looks like the Horde fleet is disengaging - maybe to land more troops ashore?\n\nAdmiral Aubrey will know what to do. Talk to me when you're ready to fly back!" }
WordHunterWoW_QuestEN[24935] = { title = "Body And Soul", description = "There are powerful and evil magics at work in this village. Yngwie, was tough. In fact, he was probably too tough.\n\nIf you were to drag his body down to the big blue bonfire and toss it in, you'd release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy Yngwie's Soul.\n\nIf you somehow misplace Yngwie's Body, ask Izzy if she found it." }
WordHunterWoW_QuestEN[24936] = { title = "Body And Soul", description = "There are powerful and evil magics at work in this village, <name>. Yngwie, was tough. In fact, he was probably too tough.\n\nIf you were to drag his body over to the big blue bonfire and toss it in, you'd release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy Yngwie's Soul.\n\nIf you somehow misplace Yngwie's Body, ask Izzy if she found it." }
WordHunterWoW_QuestEN[24937] = { title = "Oomlot Dealt With", description = "{name}, you have to get back to the Town-In-A-Box and warn them about the goblin zombies up in the volcano's caldera!", objectives = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "They turned some of our people into zombies? Tell me something I don't know...." }
WordHunterWoW_QuestEN[24938] = { title = "The Guns of Northwatch", description = "Captain Fisher signaled us from below. The Horde fleet is landing shore parties? We can't let them flank us from the beach.\n\nI've already sent two of my best gunners down there to defend the beach head. Talk to Cannoneer Smythe down on the shore.\n\nYou'll have to fight your way through the courtyard to get there. See if you can help the others secure the hold on your way down!", objectives = "Speak with Cannoneer Smythe.", completion = "Aubrey sent you? Good! I take it you know your way around a cannon?" }
WordHunterWoW_QuestEN[24939] = { title = "Run Out the Guns", description = "We've got the hardware but not the manpower, {name}. Man one of the carronades on the shore here and take out those incoming boats! ", objectives = "Use a Northwatch Shore Battery to destroy 10 Rageroar Rowboats.", progress = "Sure gets your ears ringing, doesn't it?", completion = "Ho ho! The beach is ours!\n\nWe just might keep a foothold on this miserable dustball of a continent after all." }
WordHunterWoW_QuestEN[24940] = { title = "Up the Volcano", description = "A whole bunch of our people headed up to the top of the volcano to mount a counter-offensive. There's something horrible brewing up there on the Lost Peak.\n\nThey're waiting for you before they make any moves against the pygmies. Those evil little things turned a lot of us into zombies!\n\n{name}, save us!", objectives = "Speak with Coach Crosscheck at the Lost Peak on the Lost Isles.", completion = "My star player has arrived!" }
WordHunterWoW_QuestEN[24941] = { title = "Langridge Shot", description = "{class}! Thank the Light - they've practically driven us back to the docks. The courtyard is overrun!\n\nWe're out of canister shot and the orcs are getting ready for an assault up the hill. We need to improvise some scatter-shot, and fast.\n\nHurry, run into the broken tower here and grab whatever sharp, pointy bits of scrap metal you can lay your hands on. Knives, forks, nails - anything! Load the cannon when you've got an armful!", objectives = "Gather 15 pieces of Langridge Shot.", progress = "Paxton has already loaded a charge into the cannon. All it needs is the ammunition you improvised.", completion = "The Horde is massing at the base of the hill. Breathlessly, you stuff the debris you collected into the muzzle of the cannon, step back, cover one ear, and tug on the igniter cord..." }
WordHunterWoW_QuestEN[24942] = { title = "Zombies vs. Super Booster Rocket Boots", description = "Those zombies that got past us are nothing compared to the numbers waiting just through the pass. If we don't deal with them soon, the pygmy witch doctors are going to send all of them against the town, and even the cannons down there won't be able to handle that many!\n\nI brought a couple of shredder boots along. Greely modded them and now they're Super Booster Rocket Boots!\n\nUse the boots to incinerate the zombies in the Oostan villages to the east.", objectives = "Use the Super Booster Rocket Boots to slay 50 Goblin Zombies.", progress = "You still have a few <race> zombies to deal with, <name>. Look sharp, superstar!", completion = "You did it! No more zombies to worry about. Let's pause a moment in silence for the stinky departed.\n\nOkay, done." }
WordHunterWoW_QuestEN[24943] = { title = "Re-Take the Courtyard", description = "That's one way to clear a hill. Those corpses are impaled with knives and forks!\n\nThe Rageroar clan has breached the walls, but we can still turn this fight around. Go down the hill and help our men hold on to the courtyard below...", objectives = "Kill 10 Rageroar Grunts.", completion = "Great work! We've knocked them on their heels, maybe long enough to shore up our defenses.\n\nProvided we find a way to take out their artillery..." }
WordHunterWoW_QuestEN[24944] = { title = "Back in the Fight", description = "This fight isn't over, {class}. Not by a long shot.\n\nSome of the soldiers in the courtyard still have breath in their lungs. We can save them! I've soaked these rags in an herbal remedy we used to rely on back in Gilneas. The smell is awful but this poultice can practically raise the dead.\n\nUse these bandages on wounded defenders down in the courtyard and we'll see if we can't get them back in the fight.", objectives = "Use the Herb-Soaked Bandages on 6 Wounded Defenders.", progress = "I hope you have enough bandages. My supply of those herbs was cut off when these brutes sacked my beloved Gilneas.", completion = "A steady stream of the walking wounded have come up the hill to see me, <name>. I trust that was your work? Well done!" }
WordHunterWoW_QuestEN[24945] = { title = "Three Little Pygmies", description = "Look, I think it's great that we're destroying all of these zombies, even though they're our friends and family. But don't you think we should be taking care of the pygmies that are creating them as well?\n\nAt the three Oostan villages, Nord, Sor, and Ost, there are witch doctors: Gaahl, Malmo, and Teloch.\n\nMaybe you could take care of them? I don't want to be turned into a zombie!", objectives = "Slay Gaahl, Malmo, and Teloch.", completion = "I gotta tell you, that's a load off of my mind. That is, I won't have to worry about no new zombies coming after my brains!" }
WordHunterWoW_QuestEN[24946] = { title = "Rockin' Powder", description = "I'll give these pygmies one thing... they sure know how to party! But they're not so clever. I think I've discovered the source of their rockin' powers: Rockin' Powder!\n\nIt turns out that this stuff, which turns them into world-class rockers, is also highly explosive. We must have it!\n\nSo, while you're in there at Oostan to the east, make sure that you pickup a whole bunch of the stuff. Trust me, you're going to need it for what's coming up!", objectives = "Collect 5 scoops of Rockin' Powder.", progress = "Hmm, let me see how much you've got.", completion = "This will do. In fact, it's more than we need. I devised an ingenious idea for a weapon that the boots will be turned into once you get them to Hobart.\n\nHand the powder over and I'll load it into the the Super Booster Rocket Boots." }
WordHunterWoW_QuestEN[24947] = { title = "Momentum", description = "We can't just rest on our laurels here, babe. We've got to keep this momentum going! People are talking about us.\n\nUnfortunately, they're also talking about this air-headed gnome, Kelsey, who's apparently been running jobs right alongside us. If we're going to drive her out of what's rightfully a goblin town, we need to seal the deal here.\n\nWe're going to take care of Gadgetzan's pirate problem for them, for good. Head south to Lost Rigger Cove, I'll meet you there.", objectives = "Meet Megs Dreadshredder at Lost Rigger Cove.", completion = "Good thing you're here! I'm gonna need a lot of help if we want to beat these gnomes to the punch." }
WordHunterWoW_QuestEN[24948] = { title = "Lifting the Siege", description = "We'll never be able to re-secure the fortress walls so long as Rageroar and his goons have access to artillery. I need you to fight your way across that chasm and take out his big guns.\n\nOrcs season their heavy machinery with coal tar, which makes them flammable. Take my torch and burn any catapults you see north of Northwatch.\n\nThen, torch those big blade-throwers in Rageroar's base camp! Those things have killed enough of our men. ", objectives = "Use Paxton's Torch to burn 3 Rageroar Catapults and 1 Rageroar Blade Thrower.", progress = "Burn it all, <class>. Burn it to cinders!", completion = "Good! Without heavy equipment, the Horde will have to pull back to regroup. We've bought ourselves some time to re-secure the fortress. Well done!" }
WordHunterWoW_QuestEN[24949] = { title = "Booty Duty", description = "Let's not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?\n\nI mean, why do they even bother taking it if it's just going to sit around? Stolen goods should be sold off and used to buy shiny new things.\n\nAnyway, be a dear and go grab as much of their loot as you can carry while you're out busting heads. Ciao!", objectives = "Collect 10 pieces of Pirate Booty.", progress = "Let's see what you've got. You're not hiding any for yourself, are you? You'll never find a buyer without me, you know.", completion = "Beautiful! And to think these idiots were just sitting on it.\n\nHere's a bit up front, we'll talk about profit-sharing bonuses later." }
WordHunterWoW_QuestEN[24950] = { title = "Captain Dreadbeard", description = "Alright, babe, I've got something bigger for you to take on here.\n\nWe spotted the captain of the Southsea over on one of his boats to the south; that's to the south, and NOT the one we've been suicidally bum-rushing for the better part of several hours. He's sitting up there, smug and stoic, watching us war down here.\n\nI'll spare you the \"hostile takeover\" jokes. Get on his ship and beat the tar out of him, and we're done here! ", objectives = "Kill Captain Dreadbeard.", progress = "I'm flattered that you'd rather stay here and flirt with me than go kill that pirate captain. So flattered that I might not fire you if you get going right now and do it already.", completion = "Sea giants? You think he was training them towards Gadgetzan on purpose?\n\nWhatever, he's splitsville now. And Gadgetzan owes us big time! I can't wait to see the look on Marin's face.\n\nHere's your cut, babe. You're moving up in the world." }
WordHunterWoW_QuestEN[24951] = { title = "A Great Idea", description = "Now that we've got a good pile of fresh chunks, we just tie it to this rope...and now you're ready to go catch me a silithid.\n\nWhat? Don't give me that look, it's perfectly safe. Well, mostly safe. Okay, you might die painfully. But it'll be easy! Just throw this meat out there, wait for a bug to pounce on it, and then drag 'em back here by the rope!\n\nGo after one of the swarmers. I haven't seen the other ones go for hyenas before, and you should find plenty of swarmers around the edge of the pit.", objectives = "Use the Bootlegger Bug Bait to capture a Hazzali Swarmer.", progress = "I don't see any bug with you, pal.", completion = "Look at the size of it! It's glorious. This ugly sucker's gonna help us bring down the whole hive." }
WordHunterWoW_QuestEN[24952] = { title = "Rocket Boot Boost", description = "You need to get those boots down into the caldera to Hobart Grapplehammer.\n\nNow that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot.\n\nWhen you're ready, activate the boots. Don't worry, they're automatically set to land you safely.\n\nI think.", objectives = "Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer.", progress = "Well there you are!", completion = "There's no time to waste, boy!\n\nWhat's wrong with the actuator on the left boot?!" }
WordHunterWoW_QuestEN[24953] = { title = "Just Trying to Kill Some Bugs", description = "Now it's time for my plan to go into full effect. We've got the captured bug strapped up with as many explosives as it can carry, and with Soothfancy's mostly amazing mental powers, we're gonna drive that sucker straight down into the center of the underground hive.\n\nAnd then...BOOM! No more bugs!\n\nYou get the personal honor of directin' the ugly thing. Go talk to Narain and get set up with your bug-pal.", objectives = "Talk to Narain Soothfancy to pilot the Mind-Controlled Swarmer into the Gaping Chasm hive.", progress = "I didn't hear no cave-ins, pal! Try again!", completion = "Oh man, that was awesome! You should've seen the flames coming out of the hive!\n\nHere's your reward, for entertaining me as much as for clearing the hive!" }
WordHunterWoW_QuestEN[24954] = { title = "Children of a Turtle God", description = "Volcanoth is the turtle god in the cave that these primitives worship.\n\nIt's not really a god.\n\n<Hobart rolls his eyes.>\n\nBut it is tough enough that I'm going to have to devise a new weapon for you from the one functioning boot we have left.\n\nI think that the age-old motto of \"fight fire with fire\" applies here. Plus, I like fire!\n\nLet's get some fire glands from Volcanoth's children. That should give me time to modify the rocket boot into something more fitting.", objectives = "Collect 5 Fire Glands.", progress = "No time like the present to be done with the simple task I put before you, <name>. Wouldn't you agree?", completion = "Careful with those glands, <name>, careful!\n\n\n\nAnd now to load them into the refashioned shredder boot. I'm certain that you'll be surprised and amazed by my genius invention." }
WordHunterWoW_QuestEN[24955] = { title = "Un-Chartered", description = "As I may have mentioned, I'm trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.\n\nTo pull this off, we've gotta pay lip service to the actual initiation process and all that, or I'm going to catch flak later on. So I've gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.\n\nI've got a disguise for you here, so suit up and get all these signatures filled out.", objectives = "Obtain 10 Charter Signatures from Dunemaul Ogres.", progress = "Babe, there's still blank spots on this sheet. Being near ogres isn't rubbing off on your intelligence, I hope.", completion = "Wow, nice work! I'm amazed you even got them to hold a pen without eating it.\n\nYou can uh, just throw the suit over there. Away from me. In the fire." }
WordHunterWoW_QuestEN[24956] = { title = "Silencing Rageroar", description = "I have encountered the Rageroar clan before, {name}. They are led not by an orc, but by a monster - a war-gorged fiend without a shred of decency or compassion. He and his lieutenants must be killed, not just to save Northwatch, but for the good of all of Azeroth.\n\nKarga Rageroar wears a helm. Execute him, {class}, and bring the helm to me. It is of ... particular importance.\n\nRageroar has made his camp across the chasm, east of here.", objectives = "Slay 4 Rageroar Lieutenants and acquire Rageroar's Helm by killing Karga Rageroar.", progress = "Is he dead? Do you have his ... helm?", completion = "<Tolliver grasps the helmet reverently with quivering hands.>\n\nRageroar's battleships intercepted our vessel as we fled from Gilneas. We were to be carried here as trophies to the Warchief. As we neared the shore, some of us fought back. Rageroar - he began killing indiscriminately - howling with laughter. Our ship capsized and he ordered his men to fire at us as we drowned. Few of us made it to land.\n\nAfterwards, I learned that he wore my brother's scalp as... as a trophy.\n\n<He closes his eyes.>" }
WordHunterWoW_QuestEN[24957] = { title = "Get The Centipaarty Started", description = "Okay, babe. Like I said, the ogres are too dumb to know what signing that charter meant. Now we have to actually get them to come along with us, so we'll be procuring what is apparently beloved local flavor.\n\nBeloved local flavor for drooling idiots, I mean.\n\nJust pop on over to the Noxious Lair to the west, it's that big horrible pit full of dangerous silithid. Kill a bunch of the Centipaar silithid and bring back the pieces so we can hand 'em out, okay? Ciao.", objectives = "Collect 20 Centipaarts from Centipaar Silithid.", progress = "Have you got enough? These ogres don't look like the type to like small portions.", completion = "Ugh! This entire camp is like a sampler course of awful smells.\n\nLet's not handle these things any longer than we have to." }
WordHunterWoW_QuestEN[24958] = { title = "Volcanoth!", description = "It took a lot of blood, sweat, and tears, but the Bootzooka, patent-pending, is ready for use!\n\nThese no-good pygmies have been feeding our people to their \"god\", Volcanoth, and they're about to unleash it on our town!\n\nYou have to get into the cave and kill that thing before it's too late!", objectives = "Use the Bootzooka to slay Volcanoth.", completion = "I managed to get everyone else safely back to town.\n\nJump in, we gotta get out of here before the volcano blows for good!!!" }
WordHunterWoW_QuestEN[24959] = { title = "Fresh out of the Grave", description = "{name}!\n\nRise, {name}!\n\nWelcome back to the realm of the living.  With the blessing and power of the Dark Lady, I have freed you from death's grip.\n\nYou are no slave, {name}.  You are free to follow whatever path you choose from here.  If you choose to serve the Dark Lady Sylvanas, I recommend you speak with Undertaker Mordo.  You will find him behind me, in the graveyard.", objectives = "Report to Undertaker Mordo at the Deathknell Graves in Tirisfal Glades.", completion = "Hello there.  You must be... <name>?" }
WordHunterWoW_QuestEN[24960] = { title = "The Wakening", description = "King, peasant, or {class}... I don't care WHAT you were before.  I just need somebody with a working tongue.\n\nBeing raised from the dead is strenuous.  Not everyone copes with it as well as you did.  In particular, there are three newly-raised undead who are having trouble coping right now.\n\nI want you to find them and talk to them.  It might be that they just need someone that they can relate with.\n\nYou'll find them here in the graveyard.", objectives = "Speak with Marshal Redpath, Lilian Voss, and Valdred Moray.", progress = "No dilly-dallying now.  You're among the Forsaken now, and we hold ours to a higher standard.", completion = "You've done well, <class>.  As you can see, not all of us have resigned to our fates.  I'm glad to see that you're at least willing to work.\n\nValdred will be a valuable asset to the Forsaken.  As for the other two... there is not much we can do.  We cannot force them to join us." }
WordHunterWoW_QuestEN[24961] = { title = "The Truth of the Grave", description = "Earlier on, I saw a young Forsaken woman running towards the old inn.  She was screaming for her life, pleading to be taken back home.\n\nNot all of us are as resolute as others, {name}.  Even so, we must accept our fate as undead if we are to rise up against those that would put us down.\n\nTake my hand mirror and show it to the young woman.  She needs to see what she really is, and join us in our cause.  Besides... we can use all the bodies that we can get.", objectives = "Find Lilian Voss inside the large inn in Deathknell. Then speak with her to show her Elreth's Hand Mirror.", progress = "Have you spoken with her yet?  She needs to be shown the truth.", completion = "You say she ran away?  What a shame.\n\nVery well.  As long as she's maintained her free will, there's still hope." }
WordHunterWoW_QuestEN[24962] = { title = "Trail-Worn Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the hunter trainer Xavier. I would take some time to read it before heading out again.", objectives = "Read the Trail-Worn Scroll and speak to Xavier the Huntsman in Deathknell.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need hunters with your type of cunning in the future.\n\nYou will be the backbone of our salvation. Do not forget it." }
WordHunterWoW_QuestEN[24963] = { title = "Maul 'Em With Kindness", description = "Okay, babe, listen up. There's two ways to get people to do what you want. You can provide goods, services, and things people want...or you can beat the living daylights out of them.\n\nI've often found it's useful to do both at the same time, and you're pretty familiar with both methods by now. Take these little silithid treats, go and beat some ogres dizzy, and then give them the treat before you knock them completely dead, 'kay?", objectives = "Use the Bilgewater Cartel Promotional Delicacy Morsels on 8 Dunemaul Ogres after weakening them.", progress = "Keep at it, babe. I can see 'em from here, don't get lazy on me.", completion = "Good job, you've taught half the ogres here to fear and respect anything vaguely <race>-shaped.\n\nIt's amazing what a little reward will do to keep people under your thumb, isn't it? Here's your payment, by the way.\n\n...what's with that look?" }
WordHunterWoW_QuestEN[24964] = { title = "The Thrill of the Hunt", description = "I've been told that I'm supposed to train you how to be a hunter.  That's all well and good, but in my opinion, you'll get more training out in the field than you will talking about theories with me.\n\nGo out, get some more experience, and see if you learn any new tricks. Then you can come back and show me.", objectives = "Reach level 3 to learn Steady Shot, then practice using Steady Shot 5 times on a Training Dummy.", completion = "You seem to be somewhat of a natural, <name>.  This is good.  I can't teach you everything myself.\n\nGo, practice what we've discussed today.  Return when you're stronger, and we'll cover some more tricks and abilities." }
WordHunterWoW_QuestEN[24965] = { title = "Magic Training", description = "Let's get some work done, shall we?\n\nAs you grow in power, your connection to the arcane will deepen, granting you access to new spells.\n\nYou'll see. Go, get some more experience, then come back and demonstrate what you've learned.", objectives = "Reach Level 3 to learn Frost Nova, then practice using it 2 times against a Training Dummy.", completion = "I've got to admit, the spell I just taught you probably won't increase your intellect severalfold.  That was a lie to get you to buy my services.  But it will still be a helpful spell for you and your allies.\n\nNo hard feelings!" }
WordHunterWoW_QuestEN[24966] = { title = "Of Light and Shadows", description = "A Forsaken priest is a curious beast,\n<his/her> path an unusual course.\n$G His: Her; shadowy rites cannot come from the Light, so <he/she> seeks a more sinister source.\n\nNot only has the world forsaken us, <name>... it seems the Light has left us as well.  As the poem hints, however... we are not without power.\n\nGo, get more experience, grow your power. Return to me, and demonstrate what you have learned.", objectives = "Reach level 3 to learn Shadow Word: Pain. Then, practice casting it 5 times on training dummies.", completion = "You're a good student, <name>.  You'll go far.  If you ever need any further training, return to me and I'll happily oblige." }
WordHunterWoW_QuestEN[24967] = { title = "Stab!", description = "Quiet down!  I don't want these novices around us to hear what we're about to discuss.\n\nListen up... <name>, is it? Soon, you'll learn something that'll change the way you operate as a rogue.  You'll be able to follow up on your attacks with a deadly finishing move. Maybe even slide a dagger between their vertebrae.\n\nTo learn it, you just gotta get some more experience. Don't worry, you'll figure it out.", objectives = "Reach level 3 to learn Eviscerate, then practice using Eviscerate 3 times on a Training Dummy.", completion = "Trust me, this'll be worth the money.  And hey - if you need any more training, stop by any time." }
WordHunterWoW_QuestEN[24968] = { title = "Dark Deeds", description = "As you continue your career as a warlock, you'll begin to hear the voices of fel power... they will reveal their secrets, teaching you new spells.\n\nI want to see you learn a new spell and try it out on one of the dummies here.", objectives = "Reach level 3 to learn Corruption, then practice casting Corruption 5 times on a Training Dummy.", completion = "Congratulations... you're one step closer to being a master of the dark arts.  Go practice a bit, and return when you're stronger.  I'll have more to teach you then." }
WordHunterWoW_QuestEN[24969] = { title = "Charging into Battle", description = "If you want to become a stronger warrior, you'll need to work on your weapons.  You'll find stronger swords and larger shields out on your adventures, that I have no doubt about.\n\nBut it isn't just your physical armory that will get stronger - you'll also begin to discover new techniques. Go, get some experience, learn something new, then come back and show me.", objectives = "Reach level 3 to learn Charge, then practice using Charge on a Training Dummy.", completion = "You have the makings of a great <class>, <name>.  Go, practice what we've discussed, and return when you are stronger.  Then I may have more to teach you." }
WordHunterWoW_QuestEN[24970] = { title = "No Better Than the Zombies", description = "While you were inside that cave, your big friend Darnell came by with some alarming news.\n\nSince the val'kyr arrived, we've seen more and more undead that chose not to join our forces under the banner of the Dark Lady.  They've been gathering at a small camp here in the valley, and now they've organized forces.\n\nThey plan to attack Deathknell, {class}.\n\nDarnell is just down the road, to the east.  Be careful, {name}.  While those undead aren't completely brainless, they're still not quite right in the head.", objectives = "Report to Darnell at Deathknell in Tirisfal Glades.", completion = "<name>.  You made it.\n\nYou see those tents up there?  That's where we're headed.  The battle's probably already started." }
WordHunterWoW_QuestEN[24971] = { title = "Assault on the Rotbrain Encampment", description = "While you were taking care of matters for Executor Arren, I went off on an assignment of my own.  Shadow Priest Sarvis asked me to peek in on the Rotbrain camp.\n\nThere's a reason why they're called Rotbrains.\n\nTheir leader goes by the name of Marshal Redpath, and he's an absolute beast.\n\nLook, {name}... the attack is starting.  You're better in combat than I am.  Get in there and help out!\n\nWhen you're done, meet up with Shadow Priest Sarvis in the chapel.  Good luck, {name}.", objectives = "Kill Marshal Redpath and 8 Rotbrain undead.", completion = "Being born again under the power of a val'kyr is a strenuous process.  Many don't survive the shock, turning into zombies or ghouls.\n\nOthers retain just enough humanity to seem normal on the outside... but they're sick inside.  We should have slain those rotbrains the day they were raised.\n\nAs for you... you're a strong <class>, <name>.  I knew you'd do well.  You'll be headed out of Deathknell soon." }
WordHunterWoW_QuestEN[24972] = { title = "Vital Intelligence", description = "<Sarvis produces a piece of paper from within his robes.>\n\nThese will need to be taken to my field agent, Deathguard Simmer.  This information contains the whereabouts of the last few holdouts from the Scarlet Crusade.  We will destroy these crusaders, once and for all.  And I have a feeling you'll be instrumental in that effort, {name}.\n\nTake the road north out of Deathknell.  Soon after entering Tirisfal proper, you'll see a large manse.  Simmer's inside.", objectives = "Deliver the Scarlet Crusade Documents to Deathguard Simmer at Calston Estate in Tirisfal Glades.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, <name>. Hmm... names of the Scarlet Crusade officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.  I will pass this information forward." }
WordHunterWoW_QuestEN[24973] = { title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive.  Gold was scarce in Lordaeron, even in the height of the Alliance's power so many years ago.\n\nThere is a gold mine to the west that has been overrun with spiders.  We need gold from the mine, but we can't very well get it while the spiders are crawling around in there.  I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, {name}.", objectives = "Kill 8 Young Night Web Spiders and 5 Night Web Spiders.", progress = "Be wary of the spiders' venom, <name>. If you feel a sharp burning, you may want to have it looked at.", completion = "Well, it's a start.  It'll take a few weeks or months to fully clean out the infestation.  After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, <name>." }
WordHunterWoW_QuestEN[24974] = { title = "Ever So Lonely", description = "You work hard your whole life, and what do you get?  Killed by a plague.  Then you work even harder in undeath, and what do you get?  Money, yes, and a small estate with a few pesky hangers-on, but happiness?  Not so much.\n\nI'm lonely in my old age, {name}.  I need a companion.  Use this leash on one of the murlocs at the Whispering Shore to the northwest.  You'll have to weaken it first before it can be leashed.  Then bring it back to me.", objectives = "Use the Murloc Leash on a Vile Fin murloc at the Whispering Shore, then return it to Sedrick Calston at Calston Estate.", progress = "Oh, the pain of loneliness is too much to bear!", completion = "Oh, look at him!  Isn't he the most adorable thing you've ever seen?  Thank you, <name>.  I feel more energetic already." }
WordHunterWoW_QuestEN[24975] = { title = "Fields of Grief", description = "What have we here?  You look like a fledgling {class}.  If you hope to prove yourself to the Dark Lady, you need to learn the ways of the Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, bring them back to me.", objectives = "Steal 10 pumpkins from the Solliden Farmstead in Tirisfal Glades.", progress = "Were you able to gather 10 pumpkins yet, <name>?", completion = "You have performed your bidding well, young <class>.  You are proving yourself to be quite an asset to the Dark Lady's army." }
WordHunterWoW_QuestEN[24976] = { title = "Variety is the Spice of Death", description = "These pumpkins have a purpose, {class}.  They'll be the delivery mechanism for my latest batch of plague, which should be a particularly painful and virulent concoction.  However, the plague requires a few rare ingredients.\n\nWe'll need Marrowpetals, which grow at the bottom of Stillwater Pond, just to the east of here.  We'll also need Xavren's thorn, which grows on rocky cliffs to the northwest.  Finally, we need some briny sea cucumbers, found in the surf off of Whispering Shore.", objectives = "Obtain 4 Marrowpetals, 4 Xavren's Thorns, and 8 Briny Sea Cucumbers.", progress = "I've got a feeling this will be my best batch yet, good <class>.", completion = "Excellent work, <name>.  Now comes the fun part." }
WordHunterWoW_QuestEN[24977] = { title = "Johaan's Experiment", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat the Scourge advances from the North and the human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept outside, by the gazebo.  Take this pumpkin to the fool.", objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot at the gazebo at Calston Estate.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your...\n\n...oh wait.  Is that food for me?  I am so hungry...", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin...." }
WordHunterWoW_QuestEN[24978] = { title = "Reaping the Reapers", description = "Humans are notoriously fickle creatures.  The farmers to the west are no exception.  Sure, they may be plowing their fields peacefully now, but tomorrow, they may be raising their scythes against us.  The Alliance looms close by in Gilneas, and the power of Stormwind looms to the south... any of these could recruit these tillers and use them as a wedge against us.\n\nI want them dead.  See to it that it's done.", objectives = "Kill 10 Tirisfal Farmers or Tirisfal Farmhands.", completion = "You've the makings of a mighty <class>, <race>.  I heard the cries of those humans from all the way over here.  Perhaps soon we will be rid of this human blight." }
WordHunterWoW_QuestEN[24979] = { title = "A Scarlet Letter", description = "Lieutenant Gebler:\n\nHow curious that you would decide to take a prisoner... an undead one at that.  What were you thinking?  Do you think that, just because of the prisoner's former status, that she would be above the edicts of the Scarlet Crusade?\n\nThis is most troubling, Gebler.  I would remind you that there are penalties for such behavior.  I command you to execute the prisoner at once.  She is no longer one of us.", objectives = "Find the prisoner in Scarlet Palisade.", progress = "A letter?  What does it say?", completion = "The Scarlet Crusade takes no prisoners.  That they would do so with this young woman... curious.\n\nThe powers that you describe are even curiouser.  She passed through the bars of her prison and killed her captor?  Why hadn't she done that in the first place?" }
WordHunterWoW_QuestEN[24980] = { title = "The Scarlet Palisade", description = "We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slaying 10 warriors of the Scarlet Crusade.", objectives = "Kill 10 Scarlet Warriors.", completion = "Most excellent, <class>.  Your skill in the art of combat is undeniable." }
WordHunterWoW_QuestEN[24981] = { title = "A Thorn in our Side", description = "Information we've received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill 3 of his zealots and 3 of his missionaries.  And while you're there, see if you can dig up any other information about what they're up to.", objectives = "Kill 3 Scarlet Zealots and 3 Scarlet Missionaries, and obtain the Scarlet Epistle.", progress = "We shall herd the Scarlet Crusade like cattle to their demise.", completion = "It sounds like we'll have to keep our eyes out for this Voss character.  I don't expect any Forsaken to receive a reward if we capture her... I'm just worried she'll eventually turn against us." }
WordHunterWoW_QuestEN[24982] = { title = "The New Forsaken", description = "Speaking frankly, the Forsaken of yesteryear were a sniveling, pathetic group.  We huddled together in decrepit old human buildings, hiding from the Scourge, cowering from the Alliance, and groveling at the foot of the Horde.\n\nLook before you now, and see the product of the new Forsaken.  We have made our mark here on Azeroth, and that mark will grow.  Our dominion will soon blanket the world!\n\nYou want my advice?  Speak with Magistrate Sevren in Brill, down this road.  He runs that town.", objectives = "Report to Magistrate Sevren at Brill in Tirisfal Glades.", completion = "Yes, I'm Brill's local magistrate, reporting directly to the Dark Lady.  Impress me, and you may end up meeting the Banshee Queen herself.  Now, onto your first task..." }
WordHunterWoW_QuestEN[24983] = { title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", objectives = "Speak with Deathguard Linnea at Death's Watch Waystation in Tirisfal Glades.", completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead." }
WordHunterWoW_QuestEN[24984] = { title = "The Prodigal Lich", description = "Long ago, the mage Gunther Arcanus, along with Bethor Iceshard and the now-Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther fell to the Plague, but we thought he either remained dead, or was raised into the ranks of the Lich King.  We now know he is free.\n\nWe must have him.  If you travel east, you will find him on an island in Brightwater Lake.  Convince him to join our ranks.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to Gunther Arcanus at Gunther's Retreat in Tirisfal Glades." }
WordHunterWoW_QuestEN[24985] = { title = "Proving Allegiance", description = "Fine.  I will continue with this charade, but only because I sense in you a spark of... excellence.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  It is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are an ally.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her." }
WordHunterWoW_QuestEN[24986] = { title = "The Prodigal Lich Returns", description = "Take this Nether Gem to my old comrade Bethor, who resides in the Undercity.  It will let us communicate ... and I have much to tell him.You will receive:", objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity." }
WordHunterWoW_QuestEN[24987] = { title = "Dark Lady, Watch Over Us", description = "In fact, why don't you speak with Lady Sylvanas herself?  The presence of another Kirin Tor-trained mage among our ranks is an occasion worthy of an audience.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Lady Sylvanas Windrunner in the Undercity.In fact, why don't you speak with Lady Sylvanas herself?  The presence of another Kirin Tor-trained mage among our ranks is an occasion worthy of an audience.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24988] = { title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The mindless state will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five duskbat pelts, I could sew myself a blanket.  Help me, {name}, so that I can continue to serve the cause.", objectives = "Obtain five Duskbat Pelts.", progress = "Do you have five duskbat pelts yet, <name>?", completion = "I appreciate your efforts, <name>.  May Sylvanas recognize your bravery one day. . . ." }
WordHunterWoW_QuestEN[24989] = { title = "Return to the Magistrate", description = "You should return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.", objectives = "Return to Magistrate Sevren in Brill.", completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  Even now, they are ceaseless in their assaults.\n\nBut we will not give in.  The Lich King is dead; we will not be taken again!" }
WordHunterWoW_QuestEN[24990] = { title = "Darkhound Pounding", description = "Lady Sylvanas has called upon the Royal Apothecary Society.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring our enemies - living and dead - to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Here, fill these vials with darkhound blood so I can test my theory. ", objectives = "Collect 5 Vials of Darkhound Blood.", progress = "Have you collected the darkhound blood yet, <name>? Time is fleeting!", completion = "You have done well, <name> and I thank you for your efforts." }
WordHunterWoW_QuestEN[24991] = { title = "Garren's Haunt", description = "As you're probably already realizing, the Royal Apothecary Society is a widespread organization.  We take our plague-alchemy seriously.  It is our belief that the more agents we have performing experiments, the sooner we will realize our objective.\n\nOne of our agents performs his work at a small encampment to the north of here.  His name is Jerrod, and he could use an apprentice of your... stature.", objectives = "Report to Apothecary Jerrod at Garren's Haunt in Tirisfal Glades.", completion = "Holland?  He's an amateur.  You don't need a fancy two-story apothecarium to make plague... you need love.  And maybe some good assistants.\n\nLet me show you how plague is REALLY made." }
WordHunterWoW_QuestEN[24992] = { title = "Escaped From Gilneas", description = "As far as you know, a worgen rogue roaming in Tirisfal is a new development.  This is something that Executor Zygand would certainly be interested in.", objectives = "Report the worgen's presence to Executor Zygand at Brill in Tirisfal Glades.", completion = "Hmm... yes, that makes sense.  Since the worgen have come streaming out of Gilneas, I knew it would only be a matter of time before they arrived here in Tirisfal." }
WordHunterWoW_QuestEN[24993] = { title = "Annihilate the Worgen", description = "These worgen must be dealt with, and quickly.  Our first priority is to eliminate any which may have infiltrated Brill.\n\nI want you to be on the lookout for any suspicious activity here in Brill, {name}.  We know that these worgen can hide in the shadows, so look for any signs you can find... footsteps, kicked-up rocks... anything.", objectives = "Find and kill 5 Worgen Infiltrators within Brill.", completion = "To think, they've been right under our noses!  I'll put my deathguards on alert... this will NOT happen again." }
WordHunterWoW_QuestEN[24994] = { title = "Doom Weed", description = "My envoy just delivered me a bushel of gloom weed.  Gloom weed!  I don't need gloom weed, I need doom weed!  You can see the predicament that I'm in, {name}.\n\nI'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", objectives = "Collect 10 Doom Weed.", progress = "<The apothecary mutters to himself.>\n\nThey brought me gloom weed?  GLOOM WEED?!", completion = "Ah, my doom weed. Excellent!\n\n<Apothecary Jerrod rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, <name>. As promised, here is the reward that you deserve." }
WordHunterWoW_QuestEN[24995] = { title = "Off the Scales", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly.  Poisoning some hapless victim is child's play.  Plaguing an entire world proves to be a bit more complicated.\n\nI will need several scales from murlocs in the vicinity.  You will find the creatures ambling brainlessly along the coast to the north.", objectives = "Obtain 5 Vile Fin Scales.", progress = "<name>, were you able to obtain those scales from the murlocs?", completion = "The scales are perfect, <name>. Exactly what I needed for this concoction." }
WordHunterWoW_QuestEN[24996] = { title = "Holland's Experiment", description = "I am to understand that another one of those foolish Dwarven Mountaineers has just been captured.  The deathguard has him stored here in this building, and they've assigned one of their own to persuade him not to escape.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", objectives = "Bring Holland's Special Drink to the Captured Mountaineer.", progress = "Why if I had my trusted rifle you'd be as good as dead, <class>.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  What matter of ale is this?  I'm sure it's no Rhapsody Malt but I'll take anything to wet the old whistle at this point." }
WordHunterWoW_QuestEN[24997] = { title = "Graverobbers", description = "The mass graves within the forest to the west of us were made to accommodate the... impressive... number of deaths Tirisfal suffered when the plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the mass grave and Garren's Haunt, and gather from them the embalming ichor that gives them life.", objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels, and obtain 6 flasks of Embalming Ichor.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, <name>.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by my master.  It may have secrets we can use against them." }
WordHunterWoW_QuestEN[24998] = { title = "Maggot Eye", description = "Maggot Eye is a foul beast, even by gnoll standards.  He leads a band of renegade gnolls through the land, tearing up the glades and stealing whatever corpses he can find along the way.\n\nThose are our corpses!  We had plans for those!\n\nMaggot Eye resides just up the path from us.  Show him no mercy.  Mercy is for the weak.", objectives = "Kill Maggot Eye and obtain his paw.", progress = "Yes?", completion = "Excellent work!  Now if only I can convince Jerrod to let us move our operation into that shack..." }
WordHunterWoW_QuestEN[24999] = { title = "Planting the Seed of Fear", description = "It seems that Jerrod has you hunting the murlocs to the north.  That's good... we can use their parts for our poisons.  I get a little worried sometimes, though...\n\nThe Vile Fin spawning grounds are not far off Tirisfal's northern coast, so you'll probably notice several tadpoles among the adults on the shore.  If these impressionable young murlocs were to seek revenge against us... that could ruin us.  Go chase them, and show them that the Forsaken and the Horde are not to be trifled with.", objectives = "Chase 12 Vile Fin Tadpoles until they pass out in fear.", completion = "Did they run from you, <name>?  Good.  This is better than killing them... if they live to tell the tale, then future generations of murlocs will learn to fear us." }
WordHunterWoW_QuestEN[25000] = { title = "Teegan's People", description = "Hey, {class}!\n\nAre you headed to support Corporal Teegan? He's in charge of keeping the supply routes open.\n\nHe's got two of the most ornery dwarves I've ever met in charge of sundries. If you want to make an impression on those two crotchety hunters, you're going to need to show that you can hold your own against the predators around here.\n\nThe raptors west of the hold here are especially vicious. Bring Goucho some fresh hides and you'll make an impression while supplying the troops in one swoop.", objectives = "Kill Terrortooth Runners and Terrortooth Scytheclaws to collect 8 Terrortooth Hides.", progress = "What is it, <class>? This here camp ain't fit for sight-seein'.", completion = "Hey, you're tougher than you look. These terrortooth hides reflect arrows and turn axe-blades - they don't go down easy, but their hides are worth their weight in silver in these light-forsaken Barrens. Nice work." }
WordHunterWoW_QuestEN[25001] = { title = "Sandscraper", description = "My other assistants are making sure our proud new comrades are put into comfy cages and shipped to where they're needed most. For the Horde. Meanwhile, we've got one last item on our agenda.\n\nSandscraper, the chief of the Dunemaul Clan, is probably too dumb to even be aware of what we're doing here. But I absolutely loathe unfinished business, babe. He's lurking in the den just over there to the west. Knuckle down, take him out, and we'll be good to sign off on this, 'kay?", objectives = "Kill Sandscraper.", completion = "And that's a wrap! Nothing left here for us but sand. Good job, babe.\n\nWell, maybe I shouldn't be so hasty. Did you find anything in that ogre den?" }
WordHunterWoW_QuestEN[25002] = { title = "Scavenged", description = "<You discover a cargo manifest on the body, detailing a long list of sundries urgently needed on the front.>\n\n<A bloody trail in the dirt indicates bodies were dragged south of here, toward the raptor dens.>\n\n<The raptors may have dragged away the supplies, as well. Retrieving those supplies for Corporal Teegan could help salvage this disaster!>", objectives = "Retrieve 10 Northwatch Supply Crates from the Raptor Den.", progress = "What? My supply caravan was sacked by those cold-blooded scissor-paw things?", completion = "My supplies! Well, that showed some real initiative, <class>. Those rap-saws or whatever they're called have torn lesser men to ribbons. Thank you!" }
WordHunterWoW_QuestEN[25003] = { title = "The Family Crypt", description = "The strongest point in the mills is the Agamand Family Crypt.  With necromancy, Captain Dargol has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.", objectives = "Kill 5 Wailing Ancestors and 5 Rotting Ancestors.", progress = "Time is not a luxury we have, <name>.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, <name>, and one day the Forsaken will have the dominion over Azeroth that they are owed!" }
WordHunterWoW_QuestEN[25004] = { title = "The Mills Overrun", description = "The Scourge are trying to form a base here at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nCollect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.", objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls.", progress = "Our battles with the Scourge wage on, <name>.  Do your part and throw those cursed, mindless <race> back into the Plaguelands!", completion = "Your efforts are appreciated, <name>.  I will not thank you for doing what is necessary, but I will remember your name." }
WordHunterWoW_QuestEN[25005] = { title = "Speak with Sevren", description = "I have destroyed the remains you've given me, {name}.  That is, all remains except for these...\n\nDevlin Agamand was weak and sharp-tongued in life, and was among the first to succumb to the plague.  He existed as a slave of the Scourge for a long time, longer than most.  As such, he may possess knowledge that would be of value to us.\n\nBring his remains to Magistrate Sevren, and tell him what I've told you.  He'll know what to do.", objectives = "Speak with Magistrate Sevren at Brill in Tirisfal Glades.", progress = "The fetor of Scourge hangs about you, <name>.  What is it you seek?", completion = "Devlin Agamand?  Is that him you carry in your sack there?  Ha!\n\nYes, I know what Coleman wants to try, and I want to try it too.  I hope you're prepared, <name>." }
WordHunterWoW_QuestEN[25006] = { title = "The Grasp Weakens", description = "While the Frozen Throne lies dormant, the grasp that the Lich King once held over the Scourge grows ever-weaker.  His grip on a weakling like Devlin Agamand should be weak enough that we can remove it entirely.\n\nSpeak with Shadow Priestess Malia in the manor on the east side of town.  She will assist you in the procedure.", objectives = "Speak with Shadow Priestess Malia in Brill and participate in the extraction of Devlin Agamand.", progress = "What did you find out?", completion = "Ah, how unfortunate.  Perhaps the Scourge's dominion over Devlin's mind remained too strong.  Or perhaps our methods are simply not strong enough.  It's also possible that Devlin was too simple-minded to comprehend what we were asking him." }
WordHunterWoW_QuestEN[25007] = { title = "East... Always to the East", description = "You've done much for us here, {name}, but men of your caliber are needed elsewhere.\n\nTo the east lies the Bulwark: a fortified barricade against the ravages of the Plaguelands.  The Bulwark protects us from Scourge invasions, and has allowed us enough sanctity to build up our forces here in Tirisfal Glades.\n\nGo, speak with High Executor Derrington.  He is an ally, and will doubtless appreciate whatever aid you can give him.", objectives = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", completion = "<The High Executor sizes you up.>\n\nNot much of a <class>, are you?  Well, you will be when I'm done with you." }
WordHunterWoW_QuestEN[25008] = { title = "Filthy Animals", description = "You probably caught wind of some of them Hecklefang scavengers on the way in - they reek worse than ol' Durty Pete here. Worthless animals! They steal our kills, rummage through our supplies, and worse... they ain't good for eatin'.\n\nGo kill some.\n\nThen kill some more, if you want to. ", objectives = "Kill 6 Hecklefang Scavengers.", completion = "Ooooo-oooh aye! The best Hecklefangs are the dead ones." }
WordHunterWoW_QuestEN[25009] = { title = "At War With The Scarlet Crusade", description = "Though the strength of the Scarlet Crusade wanes, we are still at war.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill 3 of his zealots and 4 of his friars. It should prove to be a devastating blow to the Crusade!", objectives = "Slay 3 Scarlet Zealots and 4 Scarlet Friars.", completion = "Your actions will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit... hopefully for good.  But other threats loom." }
WordHunterWoW_QuestEN[25010] = { title = "A Deadly New Ally", description = "Shortly before you arrived at the Bulwark, I was approached by the most unusual young undead woman.  She swore enmity against the Scarlet Crusade, so I sent her to work on our enemies to the north.  You say you saw some dead crusaders earlier?  Those were probably her work.\n\nGo check up on her, and see if she can use any assistance in her vendetta against the Crusade... though I wouldn't be surprised if she's already killed them all.", objectives = "Look for your new ally at the Scarlet Encampment in Tirisfal Glades.", completion = "As you look over the ruins of the camp, you hear a whisper behind you.\n\n<\"I could kill you right now if I wanted to.  You'd better watch your step, <race>.\">" }
WordHunterWoW_QuestEN[25011] = { title = "To Bigger and Better Things", description = "There isn't much more glory for you here on the Bulwark, {name}.  You've done enough already.  There may, however, be further adventures waiting in Silverpine Forest.\n\nSpeak with my bat man, Timothy Cunningham.  He'll give you a ride to Brill, free of charge.", objectives = "Speak with Timothy Cunningham at the Bulwark in Tirisfal Glades.", completion = "Sure, I'll give you a ride.  If High Executor Derrington asks for it, then technically I have to." }
WordHunterWoW_QuestEN[25012] = { title = "Take to the Skies", description = "If you're headed back to Brill, you'll want to stop by Executor Zygand on your way out.  I hear there's some excitement going on in Silverpine Forest, to the south.  He'll know more than I do.\n\nSpeak with me again when you're ready to head out.", objectives = "Speak with Executor Zygand at Brill in Tirisfal Glades.", completion = "Welcome back, <name>.  I've heard stories from the east.  Who would have thought that a young <race> <class> like you would have been the one to wipe out the last whimpering remnants of the Scarlet Crusade?" }
WordHunterWoW_QuestEN[25013] = { title = "A Little Oomph", description = "<Dithers samples his latest concoction.>\n\nHmm... this isn't quite there.  It needs something to give it a little more zing.  I've got it!  The spiders to the north have a potent venom that'll do the trick.  See if you can extract some for me, {name}?", objectives = "Obtain 4 samples of Vicious Night Web Spider Venom.", progress = "Do you have some venom from a Vicious Night Web Spider yet, <name>?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, <name>.  Everything else has been added to my concoction and boiled down.  Thank you, <class>!" }
WordHunterWoW_QuestEN[25014] = { title = "Sandscraper's Treasure", description = "Inside this weathered stone chest at the back of Stonescraper's lair, you find a curious artifact.\n\nShaped like a beetle, its surface is a smooth, brilliant blue, lined with gold. It looks mechanical, but unlike anything you've seen crafted by mortal hands, and very old.\n\nMegs will probably be interested in this.", objectives = "Talk to Megs Dreadshredder.", progress = "Find something?", completion = "You found that in the ogre den? That's...\n\n...nothing to get excited about, I'm sure! I'm sure it's just...a perfectly benign trinket...that I'm going to give you precisely detailed instructions on exactly how to handle.\n\n<Megs drops her voice to a whisper.>\n\nKeep your voice down and don't wave that thing around." }
WordHunterWoW_QuestEN[25015] = { title = "Make 'em Squeal", description = "One of the native species in Kalimdor is the 'quilboar.' Prickly little buggers. Reason enough to hate this continent.\n\nThe raids started shortly after we established our forward camps. Worse, those spiny fiends seem to thrive in this thorny hell of a jungle. I need you to help beat them back so we can re-establish contact with Forward Command.\n\nWhile you're out there, acquire one of those twisted branches their casters seem to be using to manipulate the jungle growth...", objectives = "Kill any combination of 8 Bristleback Bladewardens or Deviate Thornweavers, and collect a Bramblestaff from one of the Thornweavers.", progress = "I should mention, you're probably going to need a machete to hack through this mess.\n\nThis jungle came out of nowhere!", completion = "<Corporal Teegan nods as you deliver your report, then grasps the Bramblestaff with both hands.>\n\nSo, this is what the quilboar are using against us? Do you think they used these to create this jungle?" }
WordHunterWoW_QuestEN[25016] = { title = "FLAG - Training Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[25017] = { title = "Ancient Obstacles", description = "For years, this valley has been sealed behind impenetrable gates. Now that the cataclysm has torn them down, the secrets within are ours to discover.\n\nThere are yet some obstacles in the way. From within the gates, the bygone creations of the titans have awoken. They wander aimlessly across the sand, attacking any who approach.\n\nSomeone needs to destroy the golems patrolling the valley; are you up to it?", objectives = "Destroy 6 Sandstone Golems.", completion = "Thank you, <class>. We would be hard pressed to face such enemies without your assistance." }
WordHunterWoW_QuestEN[25018] = { title = "Andoren Will Know", description = "Listen carefully, {name}. I don't know how those ogres got ahold of it, but that thing's a titan artifact. I'm no expert, but just that fact alone makes it probably older than the sand we're standing on.\n\nI also know that things like this are nothing but trouble. I don't want anything to do with it. Take it south, to the Valley of the Watchers, and give it to a blood elf named Andoren Dawnrise there. And don't ask any questions, babe, please.", objectives = "Deliver the artifact to Andoren Dawnrise at the Valley of the Watchers.", completion = "Of all the...you found this in an ogre den? Unthinkable. I'm amazed they didn't try to smash it to pieces.\n\nWith any luck, <class>, we'll be able to obtain even more fascinating antiquities here...if you're willing to help." }
WordHunterWoW_QuestEN[25019] = { title = "Laying Claim", description = "We are not the only ones who have discovered the value of the Southmoon Ruins. The dwarves of the Explorers' League have swarmed there, taking artifacts and inscriptions for the Alliance.\n\nI don't think I have to explain much further. We will not allow the discoveries here to fall into the hands of the Alliance. Slay as many dwarves as you can, and drive them from the ruins!", objectives = "Kill 10 Dwarven Archeologists.", completion = "Excellent. The less interference from the Alliance, the better." }
WordHunterWoW_QuestEN[25020] = { title = "Fragments of Language", description = "At the Southmoon ruins, just east of here, we've made some finds. My colleagues have found stone shards, engraved with ancient writings, newly exposed by the shifting sands.\n\nThe writings are in no known tongue, though they bear resemblance to markings we've seen on other ruins of the titans. Deciphering them could reveal many more secrets.\n\nUnfortunately, my colleagues are also busy defending the tablets from the Alliance. I need you to go to the Southmoon ruins and retrieve the tablets yourself.", objectives = "Collect 5 Ancient Hieroglyphs.", progress = "Do you have the tablets?", completion = "Thank you, <name>. With that dealt with, we can focus our attentions fully on exploring the gateway." }
WordHunterWoW_QuestEN[25021] = { title = "Blood to Thrive", description = "To survive in de harsh desert, de Sandfury had to learn all de secrets of blood magic. You drink de blood, you get de power...darkest voodoo, yah? But dere be no room for holdin' back out here.\n\nIf we gonna find de sword, we need blood. Lucky for ya, Mazoga be a traitor, yah? And dere be plenty of Sandfury trolls wanderin' over de hills dere.\n\nGo an' get Mazoga blood...plenty of blood...and we make de ritual to find Jang'thraze. ", objectives = "Collect 6 Fistfuls of Blood from Sandfury Trolls.", progress = "Ya ain't been drinkin' it yaself, eh? I need all of it...", completion = "<Mazoga gathers the pile of blood in his hands and raises it to his mouth. It liquifies and pours gorily down his throat.>\n\nDey drink de blood, dey get de power. I drink dere blood...\n\n<Mazoga gives you a wide, blood-smeared grin.>" }
WordHunterWoW_QuestEN[25022] = { title = "A Failure to Communicate", description = "I told him he was a fool, but Ambassador Gaines insisted he could negotiate an alliance with the quilboar against the Horde. Even if he succeeded, I for one wouldn't want to fight with those ... pig-men at my side.\n\nWell, Gaines hasn't returned, and General Hawthorne will hold me accountable if I lose one of our best negotiators to these squealing savages.\n\nLocate the Ambassador in this steaming mess of a jungle and rescue him if he's still alive.", objectives = "Rescue Ambassador Gaines from the quilboar in the Overgrowth.", completion = "Good work. Gaines passed through here not long ago on his way to Northwatch and a warm bath.\n\nThe mission wasn't a total loss, though. We've learned a good deal about these quilboar and their leadership structure.\n\nNow we can handle things ... MY way." }
WordHunterWoW_QuestEN[25023] = { title = "Old Friends", description = "Alright then, grab onto the ladder. We gotta get outa here!\n\nWe'll make a flyby of the town, and then I'm gonna get you to some old friends!", objectives = "Speak with Thrall at the Warchief's Lookout on the Lost Isles.", completion = "I told you we would meet again, <name>.\n\n\n\nUnfortunate that it's under such dire circumstances." }
WordHunterWoW_QuestEN[25024] = { title = "Repel the Paratroopers", description = "The Alliance have caught back up with us at just the wrong moment, my friend. We took care of their ships, but they still have planes that are dropping their vaunted 127th Paratroopers onto the coast below.\n\nIt's all that the battlesworn and scouts can do to hold the two ramps against their overwhelming numbers. I'm certain that if you were to aid them, the tide would quickly be turned.", objectives = "Slay 10 Alliance Paratroopers.", completion = "I've not seen a finer display of <class> prowess." }
WordHunterWoW_QuestEN[25025] = { title = "Sang'thraze the Deflector", description = "The blood speaks. I can feel its flow through the sand...drenched in death, a desert of suffering...\n\n<Mazoga's eyes roll back in his head.>\n\nThere! The blood flows to the south, in a valley of bones. Zakkaru! Zakkaru, spawn of Makkari, the dark one who demands sacrifice... his father forced from Zul'Farrak, his ascension interrupted... he will taste blood once more...\n\n<Mazora reels.>\n\nGo, {class}. Zakkaru has Sang'thraze. Ya not be wanting him to keep it, trust me.", objectives = "Defeat Zakkaru and collect the Sealed Sang'Thraze.", progress = "Did the spirits speak true, mon? You got it?", completion = "<Mazoga grins as he takes the sword from you in both hands.>\n\nDidn't like ya much, eh? More in this world craves blood than just trolls, mon.\n\nLet's find the other blade..." }
WordHunterWoW_QuestEN[25026] = { title = "Darkest Mojo", description = "Jang'thraze eludes me, mon... de blood is not enough. We gonna need somethin' stronger to find it.\n\nWhen you need every troll you got to help out to scrape by, one o' them dyin' on ya is a big problem, mon, an' dat's why de Sandfury learned to raise our dead wit' da voodoo. You fall over, you just get back up again and keep workin'... forever!\n\nDe zombies we make be imbued wit' darkest mojo. You go on to de west an' find a whole mess o' dem, an' get me dat mojo, yah?", objectives = "Collect 6 Darkest Mojo from Sandfury Zombies.", progress = "You got de stuff, mon?", completion = "<Mazoga tilts his head back and inhales the clumps of mysterious material. His eyes flash.>\n\nPowerful stuff, mon...ah, if ya could see what I see now...mebbe you go try it yaself sometime.\n\nThe spirits call..." }
WordHunterWoW_QuestEN[25027] = { title = "You Flicked a Fine Vine to Leaf Me", description = "According to Gaines, \"Three-Tooth\" is what the quilboar call their matriarch. She's been twisting the thorns of this crazy jungle to her own ends, and it was her orders that Gaines be \"torn apart and fed to the overgrowth.\" Nice lady.\n\nLet's give her a taste of her own. Take the Bramblestaff you recovered, and use it on Three-Tooth to take her out of the picture. Then kill the crones she's been training, to ensure nobody else can take her place.", objectives = "Use the Bramblestaff on Three-Tooth and kill her 2 Deviate Crones in the Overgrowth.", progress = "I can see why the Horde hates these little nuisances. Have you taken on Three-Tooth yet?", completion = "...Torn limb from limb!? Well, I'd almost feel bad but the burning hatred gets in the way. She got what she deserved.\n\n<Corporal Teegan takes the Bramblestaff and snaps it over his knee.>\n\nProblem solved." }
WordHunterWoW_QuestEN[25028] = { title = "Trouble From the Ground Up", description = "Teegan's a fool to think the quilboar caused this sudden overgrowth. Look around you. I've been watching these plants bloom and sprout daily - each generation is more mutated than the last. This isn't tribal magic - it's something primal. And dangerous.\n\nThe day before last a great druid passed through our camp. Seek out Naralex, somewhere in the midst of this jungle. He'll know what to do.\n\nAnd bring him some plant samples from around the overgrowth to help his studies.", objectives = "Gather 10 Unusual Flower Buds from Budding Flowers in the overgrowth.", progress = "I am very busy, <class>. This uncontrolled growth threatens to engulf the continent. Do you have any news?", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, <class>." }
WordHunterWoW_QuestEN[25029] = { title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the plague.  Serve me by bringing me their remains.", objectives = "Obtain Gregor's Remains, Nissa's Remains, Thurman's Remains, and Devlin's Remains.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless." }
WordHunterWoW_QuestEN[25030] = { title = "The Haunted Mills", description = "You sense a malign presence coming from within the skull of the beast.  Coleman Farthing may be interested in seeing this.", objectives = "Bring Dargol's Skull to Coleman Farthing at the Agamand Mills.", progress = "Well well... what do we have here?", completion = "Is this Dargol?  He was vicious even in life, with a temper that bit deep and a blade that bit deeper.\n\nUndeath has not done him any favors, though it suits his personality.\n\n<Coleman holds the skull up and peers into the empty eye sockets.>\n\nYes, this was certainly Dargol.  I can sense his malice, even from the remains you've fetched.\n\nYou have my thanks, <name>." }
WordHunterWoW_QuestEN[25031] = { title = "Head for the Mills", description = "The Agamand Mills, to the west, have been lost to the Scourge.  The Agamand family has been slain, and the entire residence has been claimed by the Scourge.\n\nThis is probably the largest Scourge outpost in Tirisfal, {name}.  If you think you're enough of a {class}, head up there and speak with Coleman Farthing.  He's been doing his best to take the land back, and he'll need help.  Just follow this road, it'll take you right to him.", objectives = "Report to Coleman Farthing at Agamand Mills in Tirisfal Glades.", completion = "Argh!  Get back!  Oh, you're not Scourge, are you?\n\nThank the Banshee Queen that you're here.  I've greatly underestimated how bad it's gotten up here." }
WordHunterWoW_QuestEN[25032] = { title = "Secrets in the Oasis", description = "Yes, I see the other half now, mon...to the south...\n\nWe be close now, mon. It's in an oasis, buried in de muck beneath de water. Don't delay!", objectives = "Search for Jang'thraze the Protector.", progress = "Don't be gawkin' here at me all day, mon. Best get goin'.", completion = "Mazoga? He's taken the sword? That filthy...\n\n<Trenton glowers for a moment.>\n\nAt least you escaped with your life. The Lasher's bite is a vicious one." }
WordHunterWoW_QuestEN[25033] = { title = "The Red Messenger", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, <name>. Find that messenger and bring me whatever information you can find.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, and obtain any information you can find." }
WordHunterWoW_QuestEN[25034] = { title = "To the Front!", description = "I'd love to keep you here behind the lines, but it looks like you've been summoned to the front. Ambassador Gaines - remember him? - has relocated to Forward Command and in his latest missive he's requested you, personally, to assist him.\n\nYou'll find our Forward Command operation south of here, in what's become known as the \"Fields of Blood.\"\n\nBe careful, {name}. The Horde has taken to ambushing some of our officers en route.", objectives = "Locate Ambassador Gaines at Forward Command in Southern Barrens.", completion = "Ah, <name>! I've been talking you up to the General here. Thank you again for saving my life." }
WordHunterWoW_QuestEN[25035] = { title = "Breaking the Line", description = "Vol'jin be callin' for an all out attack on da naga that have taken over our northern isle. Many of our men were already engaged with their forces near da bridge, but several of us are breakin' through their lines ta assault their isle itself.\n\nSpeak to Jornun right 'ere to secure a ride to da isle. Once there, seek out Morakki, da Captain of da Watch. He will be tellin' ya how ya can aid in da battle.", objectives = "Speak to Jornun to secure a ride to Spitescale Cove and then seek out Morakki.", completion = "Good to have ya, brotha.\n\nVol'jin makes us all proud in dese moments. It feels good ta be tacklin' threats head on." }
WordHunterWoW_QuestEN[25036] = { title = "Teegan's Troubles", description = "The Admiral will be pleased that Northwatch is almost secured, but if we're to keep a grip on this continent we're going to need to maintain the supply lines to the interior.\n\nJust before the assault I received the strangest of reports from Corporal Teegan, who's in charge of maintaining our contact with Forward Command. Says he's having trouble with the \"jungle?\" There's no jungle in the Barrens!\n\nFollow the upper road out of Northwatch and see if you can render any assistance to our wayward Corporal.", objectives = "Report to Corporal Teegan at Teegan's Expedition in Southern Barrens.", completion = "So, Paxton says there's no jungle in the Barrens? What do you call THIS!?\n\nI've got a pile of supplies to move to the interior and my camp has been overrun by a forest that - I swear - grows by the hour!" }
WordHunterWoW_QuestEN[25037] = { title = "Crab Fishin'", description = "Perhaps me agin' body is just growin' too picky after all dese years, but boar meat just ain't goin' down easy no more. More for da new recruits I be thinkin'.\n\nWe just set out some crab traps, but if ya be willin' ta help an impatient old troll, I'd love ta have some fresh crawler meat right now. Dey're all around da island, but da best spot ta be huntin' them is off da eastern coast.", objectives = "Kill Pygmy Surf Crawlers and collect 5 Fresh Crawler Meat.", progress = "Da sea be offerin' few boons as delicious as fresh crawler meat.", completion = "Oi! Tasty, mon. Thank ya for your great kindness, young one. Da spirits shall surely be regardin' ya with great favor." }
WordHunterWoW_QuestEN[25038] = { title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill.\n", objectives = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in Brill.", progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nWe'll deal with the Gloom weed later.  For now, we've got other matters to discuss." }
WordHunterWoW_QuestEN[25039] = { title = "Have You Seen Anything Weird Out There?", description = "{race}!  Listen up, I got somethin'... odd to discuss.\n\nI was out fishin' by Brightwater Lake when I saw the darnedest thing... some sorta wolf-man, running around Tirisfal.  Ya don't suppose that could be a... worgen, do ya?\n\nAnyway, I keep tellin' myself I should tell Executor Zygand about it, but I just get so scared when I talk to that guy.  Maybe you could talk with him?", objectives = "Speak with Executor Zygand about your encounter with the worgen.", completion = "Hmm... yes, that makes sense.  Since the worgen have come streaming out of Gilneas, I knew it would only be a matter of time before they arrived here in Tirisfal." }
WordHunterWoW_QuestEN[25040] = { title = "FLAG - Worgen Attacked", description = "", objectives = "" }
WordHunterWoW_QuestEN[25041] = { title = "Lion's Pride", description = "Respect the lion, {name}! A ferocious killer. You gotta admire the elegance of the beast... Muscle and claws... Running down its food... So primal...\n\nI'm sorry, my mind wandered. As I was saying, I respect these lions, but they're just murder on our patrols. I mean that literally. The men are afraid to go to the bathroom alone at night. Can you help make our camp a little safer?\n\nBarrens lions like to linger under trees.", objectives = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", completion = "Nice work! How was it? Did you enjoy the hunt?\n\nDid you run through tall grasses, the scent of your prey urging you forward, until you leapt at its throat, adrenaline surging as your slavering fangs... Well, something like that." }
WordHunterWoW_QuestEN[25042] = { title = "Marching On Our Stomachs", description = "It's true what they say: An army marches on its stomach. And we've been marching a long way.\n\nI'm thinking if we barbecue up a few of those giant lumbering stormsnouts, we'll have enough meat to feed us for weeks.\n\nStormsnouts are big and slow, so they should be easy to kill. Except... Hey you're not carrying any metal on you are you?", objectives = "Collect 4 Fresh Stormsnout Steaks by killing Stormsnouts in Southern Barrens.", progress = "<Trawley licks his lips, barely able to constrain his drool.>\n\nYou get my steaks yet? Nice and bloody?", completion = "<Sam's eyes bug out of his head as you slam the huge slabs of meat before him.>\n\nOh yeah... oh ... YES! I'll have mine raw. I suppose I can grill some up for the others... How would you like yours?" }
WordHunterWoW_QuestEN[25043] = { title = "Fields of Blood", description = "The Horde has taken to calling this region the \"Fields of Blood.\" It's an apt name: these reeds run red with the blood of some of my best men.\n\nI've sent out recon patrols to crush the quilboar and report on the Horde troop movements, but not all of them return. They could use your support out there.\n\nPatrol the fields and seek out the Desolation Grunts that are causing us so much grief. Do not expect them to surrender; their Warchief has instructed them to fight to the death.", objectives = "Kill 10 Desolation Grunts at the Fields of Blood in Southern Barrens.", completion = "Very good. We may never drive the Horde completely from these lands, but with a strong presence we can undermine their will to fight." }
WordHunterWoW_QuestEN[25044] = { title = "Diplomacy By Another Means", description = "I have not forgotten my brush with death at the hands of the quilboar in that filthy jungle. The General here has ordered some tactical strikes, but he stops short of genocide. I have no such qualms.\n\nTake this horn that I 'borrowed' during my negotiations. Blow the horn within the Bristleback challenge ring west of our position - you can't miss it. I want you to challenge the champion of the Bristleback, Sabersnout, to single combat. His death in front of his followers will leave them in utter chaos.", objectives = "Take the Horn of Challenge to the Bristleback Challenge Ring in Southern Barrens. Blow the horn to challenge Sabersnout and kill him.", progress = "Sabersnout! Is he dead? What's the news?", completion = "A \"Boarpocalypse,\" you say? These animals certainly have a unique idea of \"Single combat!\"\n\nNo matter, you've done well. With the quilboar in chaos I should have no trouble convincing the field commanders to execute any strays they find scurrying about. The General need not know we've stepped up the campaign... it's for the better." }
WordHunterWoW_QuestEN[25045] = { title = "A Line in the Dirt", description = "Strategically, control of a region requires constant observation. See here on this map - I've identified a number of strategic hills, similar to this one, that the Alliance must acquire if we are to keep the enemy under our thumb.\n\nMy scouts have already marked their location on the field. What I need is someone to spearhead their capture, and you're the man for the job.\n\nSeek out neutral grey flags on hills to the north, east, and south of the Taurajo Ruins. Capture one and defend it!", objectives = "Capture a neutral hill in the Fields of Blood and defend it against a Horde counter-attack.", progress = "How goes the fight? Every inch of territory our valor earns today grants us continued security tomorrow.", completion = "Your report, <class>?\n\n\n\nIncredible, <name>! You're a real asset to the Alliance. I'll see to it that my men follow your example!" }
WordHunterWoW_QuestEN[25046] = { title = "A Daughter's Embrace", description = "The whisper continues:\n\n<\"My name is Lilian Voss.  Before I died, I was a member of the Scarlet Crusade.  My father, High Priest Voss, raised me to be a weapon against the plagued.  I studied stealth, sorcery, martial arts, anything to make myself stronger.  I gave up my childhood for him.\">\n\n<\"Then, as fate would have it, I died and returned as... this.  My father instantly forgot me and, when I returned, ordered me executed.\">\n\n<\"Come.  We will speak with him now, in his tower to the northwest.\">", objectives = "Bring Lilian Voss to her father in the tower at Crusader's Run.", completion = "From birth to grave to undeath, we all have our own path to follow.  Some are easier than others.  It sounds like this Voss girl has had a rough path so far.\n\nHopefully she ultimately chooses to join us and follow the Dark Lady.  With power like hers, we could do incredible things.\n\nBy the way, <name>... excellent work out there.  If you're ever ready and willing, I may have some more work for you in the Plaguelands." }
WordHunterWoW_QuestEN[25047] = { title = "Broken Panther Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "Repair the broken figurine using your skill and materials." }
WordHunterWoW_QuestEN[25048] = { title = "Seaside Salvage", description = "If we want to convince Mister Noggenfogger to let us move more gnomes here, we've got to show him just how nice we are! I know just the thing.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nIf you could go collect those supplies for them, it'd help us make friends! And it'll keep that mean goblin girl over there from taking them and selling them.", objectives = "Collect 7 Steamwheedle Supplies.", progress = "Do you have a whole buncha boxes? Let's see!", completion = "Most of this looks just fine! How lucky!\n\nThe Steamwheedle goblins will be so happy to see their cargo back safe and sound. And here's a reward for your good deeds, of course!\n\nWe've got lots of other stuff to do though! Busy busy!" }
WordHunterWoW_QuestEN[25049] = { title = "Puddle Stomping", description = "There's a big problem here! It's great that the ocean came in so far, because now ships can get to Gadgetzan. But now there's a bunch of nasty old sea giants encroaching on the town! I'm sure Mister Noggenfogger would appreciate us taking care of them for him.\n\nDon't worry, I won't ask you to do it just out of the goodness of your heart! Take care of them and I'll give you a reward!", objectives = "Kill 8 Tidal Striders.", completion = "Oh, it's going to be so much nicer around here now that they're gone!\n\nAt least until more show up. But thank you!" }
WordHunterWoW_QuestEN[25050] = { title = "Rocket Rescue", description = "When the water came in, Steamwheedle Port to the east was flooded, and a lot of poor goblins are still stuck there! Now those mean pirates are shooting at any boat that leaves the docks here.\n\nBut they won't expect us to fly! There's a hot air balloon by the docks. We can use that, fly over to rescue the goblins, and take care of the pirates, too. Mr. Noggenfogger will be so pleased!\n\nGo to the docks and hop in the balloon and I'll be right behind you, okay? I've got to get some rockets...", objectives = "Deliver Liferockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southsea Blockaders.", progress = "Let's not wait around, silly! We weren't done yet! We've gotta get out there!", completion = "That was great! It looks like most of the goblins we helped made it back here and didn't blow up. We really showed that goblin girl!\n\nHere's a special reward for you, mister." }
WordHunterWoW_QuestEN[25051] = { title = "Darkmist Extermination", description = "The spiders that occupy Darkmist Cavern to the northwest are another vicious threat to us here. They are nothing the ogres cannot handle, but splitting our attention to them when Theramore's forces lurk nearby is a deadly mistake.\n\nI need someone to destroy the eggs inside Darkmist Cavern, to cut off this infestation. You will find the eggs in the deepest part of the webbed mines... along with their guardians.", objectives = "Destroy 8 Darkmist Eggs in Darkmist Cavern.", completion = "This is a great relief, <class>. Thank you." }
WordHunterWoW_QuestEN[25052] = { title = "Dead Man's Chest", description = "Well gosh, as you can plainly see there's this really big battle with these pirates here going on. We're doing our best to make sure they never bother Gadgetzan or our new gnomish homes there ever again!\n\nBy killing them.\n\nSo how about helping us? We really wanna make sure we kill more than green-nose over there and her awful thugs. I'd really appreciate it!", objectives = "Kill 15 Southsea Pirates.", completion = "Good job! We're really cleaning up around here!" }
WordHunterWoW_QuestEN[25053] = { title = "To The Ground!", description = "You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing.\n\nI mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!", objectives = "Use the Burning Rum to set fire to the Northwest Shack, the Northeast Shack, and the Southwest Shack.", completion = "Isn't that just so pretty to watch?" }
WordHunterWoW_QuestEN[25054] = { title = "Lootin' Plunder", description = "It's just really so wasteful that all these pirates have golden treasures lying around. Some of this stuff could be used for practical things! Like melting into wire, or intrinsic shielding matrices, or selling to other stupid races that buy gold just to keep it around.\n\nAnd speaking of other stupid races, I bet those greedy goblins are going to be taking all of it. We can't let that happen! Go collect that treasure for Gnomeregan!", objectives = "Collect 10 pieces of Pirate Loot.", progress = "I hope you don't think you're hiding any for yourself, silly! These goggles can see right through your bags.\n\nAnd your armor.", completion = "Fantastic! Gosh, this will make enough wire for an entire army.\n\nLucky us!" }
WordHunterWoW_QuestEN[25055] = { title = "Subduing the Elements", description = "The elements are restless, <class>.  The earthquakes that plague the land and threaten to collapse Ironforge are not normal.  The Earthen Ring are convinced that we must put the elements to rest before they tear Azeroth apart.  We need your help, <name>.\n\nI will give you a bag of Earthen Ring supplies.  In it you will find two items, elemental sapta and a cleansing totem.  Use the sapta to see into the elemental world.  Then use the cleansing totem to subdue the agitated earth spirits.", objectives = "Gavan Grayfeather wants you to use the elemental sapta and cleansing totem from the Earthen Ring supplies to subdue 20 Agitated Earth Spirits.", progress = "Have you subdued the elements yet?", completion = "Well done <name>.  But for every element that is subdued another one takes it's place.  The solution we have here is merely a stopgap.  Hopefully my brethren in the Earthen Ring are making more headway." }
WordHunterWoW_QuestEN[25056] = { title = "Grisly Grizzlies", description = "Have you seen the plagued bruins that wander to the west of here?  Those hides... so hideous, so diseased, so... perfect!\n\nFetch me 5 of them.  I've got an idea for an anti-Scourge poison that's guaranteed to succeed!", objectives = "Obtain 5 Plagued Bruin Hides.", progress = "Let's see... do you have enough hides?", completion = "Dithers, you've done it again!  These are perfect." }
WordHunterWoW_QuestEN[25057] = { title = "Clap 'Em In Irons", description = "Our policy of conscripting non-violent criminals from the Stormwind Stockades has come back to haunt us, {name}. Some of my less-scrupulous soldiers broke ranks after our victory in Taurajo and are looting the remains of the city.\n\nThis is a breakdown in discipline. Worse, the desecration of their homes only spurs the enemy to fight harder when our ultimate goal should be peace.\n\nTake these manacles and bring the Taurajo looters to justice. Speak to them first, but you may need force to subdue them.", objectives = "Speak to the Taurajo Looters in the Taurajo Ruins and place them under arrest. Use the Northwatch Manacles to subdue 5 wounded looters.", progress = "Is the Taurajo situation under control?", completion = "Well done, <name>. Several of the looters have already crawled back, requesting clemency. I'll let them stew for a bit in the Northwatch brig.\n\nThank you for helping maintain discipline in the ranks. It is important for our army to be perceived as soldiers, not common bandits." }
WordHunterWoW_QuestEN[25058] = { title = "Mine Disposal, the Goblin Way", description = "The paratroopers have mined the beach!\n\nThe Warchief asked me if there's anything we can do about that. I told him, 'You bet we can!'. I was thinking maybe you could take this satchel of grenades and detonate the land mines from a safe distance?\n\nIt's how we do things, right?!", objectives = "Detonate 10 Land Mines.", progress = "Boss, do you think you could go back down there and detonate a few more?\n\nThanks!", completion = "Score one for the goblins! Stupid dwarves and gnomes." }
WordHunterWoW_QuestEN[25059] = { title = "The Taurajo Briefs", description = "The General is too preoccupied with the looters in Taurajo. Too soft! We ought to be focused on our next move against the Horde.\n\nThere's valuable intelligence that might be compromised if we allow the ruins of Taurajo to continue to burn. While you're running the General's errand, dig around for any maps or notes you can find. I can speak a little of the orcish tongue - I'll be able to make sense of what you find.", objectives = "Search the Ruins of Taurajo for 3 pieces of Taurajo Intelligence.", progress = "Have you searched the ruins yet?", completion = "What have you dug up for me? Hmm. Interesting. This notice from Orgrimmar indicates a change in Horde leadership is underway - I guess heads are going to roll after what we did to Taurajo.\n\nWhat's this? A death warrant for the General here! This is good to know... Very good to know..." }
WordHunterWoW_QuestEN[25060] = { title = "Define \"Crazy\"", description = "We received reports that a goblin shipwreck occured on this beach some time ago, with the survivors left to fend for themselves. We expected there to be a modicum of survivors, perhaps some even suitable for interrogation.\n\nWhat we found was a crew of Bilgewater goblins who have all become insane, delusional, and maniacally violent...to further degrees than is normally observed, rather.\n\nIn short, they are useless and dangerous. Gnomeregan will be best served by cutting down as many as we can.", objectives = "Kill 10 Crazed Survivors.", progress = "I sincerely doubt you'd prefer to adjust our mechanostriders or oil my boots for spare copper instead, <name>. Go kill more goblins.", completion = "Your reports of their behavior are truly disturbing...but also slightly amusing.\n\nIf only that Dreadshredder wench had escaped on these vessels instead..." }
WordHunterWoW_QuestEN[25061] = { title = "Land's End", description = "Psst! Hey! Come closer, you fool, you expect me to read your mind or--oh. Come closer anyway!\n\nYou've done a wonderful job advancing the agenda of Gnomeregan here, friend! And an amazing job of pretending you were only in it for the coin, simply splendid. But now Kelsey Steelspark could use more of your direct help.\n\nShe's moved on yet again...she asked me to tell you to meet her far south, at Land's End Beach. I wouldn't keep her waiting, either!", objectives = "Talk to Kelsey Steelspark at Steelspark Station.", completion = "I'm amazed that Soothfancy was capable of following a simple set of instructions. And ones that required him to keep his foolish mouth silenced as well.\n\nIn addition, it is honestly good to see you again, <name>. Now that I've dropped the charade, you'll get to see how gnomes get things done around here." }
WordHunterWoW_QuestEN[25062] = { title = "What We Came For", description = "Gnomeregan previously learned that the Bilgewater goblins of the Horde survived a crash on an uncharted island near Kalimdor before arriving in Durotar. We initially came here to investigate what techniques and technology could possibly allow a hopeless pack of imbeciles to survive such harsh conditions.\n\nWhile the goblins are at a loss, we still need to find out exactly what happened here. Search the beach for wreckage and belongings and bring anything that appears significant back to me.", objectives = "Search Bilgewater Footlockers for evidence.", progress = "What have you found?", completion = "<Kelsey takes the journal and gingerly flips through it.>\n\nI'm trying not to laugh. This is classic. They have no idea they're even on Kalimdor!\n\nThese later pages though...something more significant may be occuring here." }
WordHunterWoW_QuestEN[25063] = { title = "Terrapination", description = "We need to obtain the object described in this journal, for certain. Extracting it from a chest would be a feasible matter, but the object itself sounds compromised, and unstable. Attempting to forcefully open the chest could be disastrous.\n\nFortunately, we know where the key is...statistically speaking, at least. There's plenty of sea turtles at the east end of this beach. One of them may hold the key.", objectives = "Obtain a Turtle-Digested Key from a Surf Glider.", progress = "Hopefully your spree of turtle destruction left it intact.", completion = "Well, gosh, this day just keeps getting better and better! I may actually smile.\n\nWhen you're not looking. You've seen enough of that already." }
WordHunterWoW_QuestEN[25064] = { title = "Moraya", description = "Moraya has been lookin' for some help with tha raptors. Ya should talk to her on the other side of Darkspear Hold when ya get a chance.", objectives = "Speak with Moraya.", completion = "Hey there, hon. Vol'jin sent you? So sweet of him to be thinkin' of me.\n\nI surely could use da help, but ya have a bit more walkin' ahead of ya." }
WordHunterWoW_QuestEN[25065] = { title = "You Too, Brute?", description = "It's time to conclude this matter efficiently. From what we've determined, this mysterious object is in the possession of the \"smart\" brute described in the journal. We don't know exactly what's happened to this creature, obviously, so you should take caution.\n\nThis... \"Meatface\" is hiding in the hills, near where these goblins bury their dead. Look for the graveyard and he should be just past it.", objectives = "Obtain Meatface's Chest.", progress = "Do be careful with the contents of the chest.", completion = "Well done, <name>. The contents of this chest are sure to advance Gnomeregan's knowledge base significantly. I believe you've earned a reward." }
WordHunterWoW_QuestEN[25066] = { title = "The Pride of Kezan", description = "This is ridiculous! Those gnomes just don't know when to stop!\n\nGoblin pride is on the line here! {name}, you gotta jump into the Pride of Kezan and show them what's what!\n\nLet me know when you're ready!", objectives = "Shoot down 10 Gnomeregan Stealth Fighters.", progress = "What are you doing back here? Get up there and shoot them down!", completion = "YES!" }
WordHunterWoW_QuestEN[25067] = { title = "Thunderdrome: The Ginormus!", description = "The rules are simple: Two men enter, one--wait. Sometimes there's women.\n\nTwo people enter, one--Wait, no, sometimes it's more than two...and that means more than two come out--\n\nAlright, only rule is stay in the drome! There are no other rules!\n\nYou're up against the biggest, baddest member of the Wastewander Bandits first. This'll either be a warmup or a bloodbath...it's up to you which!", objectives = "Defeat Lord Ginormus.", progress = "Stop wasting my time. Enter and fight!", completion = "An impressive start. Be prepared for more." }
WordHunterWoW_QuestEN[25068] = { title = "The Crumbling Past", description = "The creatures wandering these ruins are Earthen, the ancient ancestors of dwarves, made by the Titans to shape the world itself.\n\nThe original Earthen broke down and went awry thousands of years ago, and these freshly uncovered ones seem no different. We may as well make use of these confused and unstable constructs.\n\nEnter the ruins and destroy the Earthen, and collect the jewels embedded in them; their magical energies will be both valuable and worthy of study.", objectives = "Collect 5 Earthen Jewels.", progress = "Handle those carefully, <name>; they are as ancient as the world itself.", completion = "Marvelous. To think the shapers of our world crafted these..." }
WordHunterWoW_QuestEN[25069] = { title = "The Secrets of Uldum", description = "We are ready to enter the antechamber itself, {name}. This is a momentous occasion.\n\nFrom the writings you've brought us, I believe these ruins were in fact once the grand entrance to Uldum itself. The quakes that ripped its doors open have probably collapsed the tunnels, but we may yet find amazing things hidden within.\n\nSearch the ruins for anything intact that may be studied.  The thrill of discovery awaits!", objectives = "Search the Antechamber of Uldum for an intact artifact.", completion = "This chest lies undisturbed, sealed for thousands of years." }
WordHunterWoW_QuestEN[25070] = { title = "What Lies Within", description = "As you lay your hand upon the chest, a faint rumbling can be heard. The sound of grinding movement echoes behind you as the chest begins to shut itself.\n\nSomething is approaching!", objectives = "Defeat the Antechamber Guardian.", completion = "The chest now grinds open again, the rest of the antechamber fallen silent." }
WordHunterWoW_QuestEN[25071] = { title = "FLAG - Purple Murloc", description = "", objectives = "" }
WordHunterWoW_QuestEN[25072] = { title = "A Few Good Goblins", description = "We haven't just been camped here singin' songs with gnomes and playing with dangerous machinery, you know. My men have been trying to clear this hive out for a week now! Problem is, we've taken so many losses by now that the bugs have the advantage.\n\nLucky for us, the bugs either don't like to eat goblins, or they like us so much they save us as treats, because nearly all my men are still cocooned up out there. I need you to go save 'em.", objectives = "Save 8 Captured Goblin Bughunters from Hazzali Cocoons.", completion = "Thanks for the help, this was really killin' things here. Once you start losing men, you start losing manpower. And morale. And weapons. And the magazines you loaned to that one guy.\n\nYou know how it is." }
WordHunterWoW_QuestEN[25073] = { title = "Sen'jin Village", description = "You've be doin' quite well for one so young. I've no doubts you'll be makin' quite da name for yarself.\n\nGo now, northwest, across da shallows ta Sen'jin Village. Dere you'll be meetin' Master Gadrin. He'll likely have a task or two for ya before ya truly make ya way out into the Durotar wilds.\n\nPlease remember, {name}, we may disagree wit' the young Hellscream at times, but his intentions are noble, and it be very important that we remain united as one Horde. Make da Darkspear proud.", objectives = "Report to Master Gadrin in Sen'jin Village.", completion = "Welcome, young <race>.\n\nYa come highly recommended, mon. It's nice ta finally be meetin' ya in person." }
WordHunterWoW_QuestEN[25074] = { title = "Meet Me at Triumph", description = "Thanks in part to your efforts, we've stabilized the situation here. We need to turn our attention south, to Fort Triumph.\n\nFort Triumph is the keystone of our operation in the Barrens - the vital land-link between Northwatch and Theramore.\n\nI'll pack up and head out separately. Report to Commander Roberts at the fortress and I will see you there soon. Together, we will secure the frontier!", objectives = "Report to Commander Roberts at Fort Triumph in Southern Barrens.", completion = "Have you heard? The General never made it!\n\nKilled in the field, like some kind of dog!" }
WordHunterWoW_QuestEN[25075] = { title = "Pick-a-Part", description = "These bulky dwarven siege engines aren't cut out for the close-quarters fighting of the Battlescar.\n\nI've got some new designs I'd like to try out, but first I'm going to need some spare parts. There's plenty of wreckage sitting in the Battlescar. All I need is an enterprising {class} to haul it back for me.\n\nThat's you, {name}. I'm talking about you.", objectives = "Collect 8 Siege Engine Scrap pieces from the Battlescar in Southern Barrens.", progress = "What have you got for me?", completion = "Oohh look! A mostly complete exhaust manifold, a reciprocating junction box, a working counterweight slip differential ... you sure know your junk, <name>." }
WordHunterWoW_QuestEN[25076] = { title = "Taming the Beast", description = "You have spent your young career mastering the arts of single combat.  I feel it is high time that you learned a new form of combat - that of the trained pet.\n\nTake this rod and use it on a vampiric duskbat until it joins you and your cause.  It may take you some time, but I have faith that you can bend the bat to your will.You will receive:", objectives = "Use the Taming Rod to befriend a Vampiric Duskbat." }
WordHunterWoW_QuestEN[25077] = { title = "Taming the Beast", description = "Lately we have seen some young, plagued bears passing over the mountains between here and the plaguelands.  While these bears' trek into Tirisfal tests and threatens the defenses that we have laid at the Bulwark, their passage is a blessing to us hunters.\n\nProve to me you learned something from our last lesson, and use the rod on a plagued bruin, far to the east.You will receive:", objectives = "Use the Taming Rod to befriend a Plagued Bruin." }
WordHunterWoW_QuestEN[25078] = { title = "Taming the Beast", description = "Your final test involves the spiders that reside in Venomweb Vale, north of the Bulwark.  Yes, even these simple creatures can become a valuable trained ally.  I have seen many hunters that count these venomous creatures as part of their arsenal.\n\nUse the rod to tame one, and return to me when you finish.You will learn:", objectives = "Use the Taming Rod to befriend a Vicious Night Web Spider." }
WordHunterWoW_QuestEN[25079] = { title = "Powder Play", description = "Our shipments of saltpeter from Dustwallow have been held up, which means we can't manufacture our own gunpowder here.\n\nBut I can retrofit our armaments to use goblin Blast-O powder. It's unstable, dangerous, toxic to the skin, and harmful if swallowed... but I think I can make it work!\n\nGet me a keg of the stuff by attacking one of those goblin sapper specialists who've been storming our walls.", objectives = "Defeat a Sapper Specialist near the Battlescar and acquire a Keg of Blast-O Powder.", progress = "Do you have a keg of Blast-O powder yet?\n\nWhen you get one ... don't shake it.", completion = "Great! Set the keg down right here. I'll measure out some charges once I've donned my full-body protective gear." }
WordHunterWoW_QuestEN[25080] = { title = "Batteries Not Yet Included", description = "Okay! Using the spare parts you've found for me, I've got a framework roughed out for my versatile new assault vehicle. All I need now is a compact power supply.\n\nI've noticed that the indigenous wildlife here packs quite the punch, electrostatically speaking. Can you hunt down Thunderheads near the base here and get me an intact electrogizard? It might take a few kills to find a usable gland.", objectives = "Acquire a Humming Electrogizard from a Thunderhead in Southern Barrens.", progress = "It must be an enormous evolutionary advantage to be able to shoot lightning. From your face.", completion = "<The gizard shocks Mizzy as you hand it over, blasting her to the ground.>\n\nOh, OH! That's nasty! I love it!" }
WordHunterWoW_QuestEN[25081] = { title = "Claim the Battlescar", description = "The Horde has fought us to a standstill from their stronghold west of here. The fighting continues, even as the land breaks open under our feet.\n\nSomeone's got to break the stalemate! I need you to venture into the Battlescar and help my men crush the Horde opposition there.\n\nIn the center of the scar you will find a flag marker designating who controls the area. Scout out the flag. It'll be worth your while to claim the scar for the Alliance if someone hasn't already done so.", objectives = "Go to the Battlescar. Scout out the flag marker and kill 10 Desolation Raiders.\n\nCapturing the flag will give all Alliance players in the scar a combat advantage.", completion = "Incredible work, <name>! My men report a breakthrough. Their stronghold won't survive much longer..." }
WordHunterWoW_QuestEN[25082] = { title = "Working the Bugs Out", description = "Why high command decided that a silithid mound was the ideal place to build a fortress, I'll never know. Them lil' buggers are tunneling under our fortifications and setting back our timetables. We need to scorch 'em out!\n\nTake this here bucket of burning pitch and dump it on the silithid mounds right outside the main gate. They look like big piles of sand. Kill anything that comes out, but be careful, {name} - them nasties are likely to swarm you when you light those mounds up.", objectives = "Use the Bucket of Burning Pitch on the silithid mounds outside of Fort Triumph to flush out and kill 10 Silithid Swarmers.", progress = "How goes the fight, <name>?", completion = "That oughta take care of our bug problem for a while - they'll be hard-pressed to tunnel their way outta that!" }
WordHunterWoW_QuestEN[25083] = { title = "Beast Training", description = "One last thing, <hunter/huntress>.  You'll want to speak with Apolos at the Undercity.  He'll teach you the last few bits of knowledge necessary to care for and train your pet.\n\nYou can find him in the War Quarter.You will also receive:", objectives = "Speak with Apolos in the War Quarter of the Undercity.One last thing, <hunter/huntress>. You'll want to speak with Apolos at the Undercity. He'll teach you the last few bits of knowledge necessary to care for and train your pet.\n\nYou can find him in the War Quarter.You will also receive:" }
WordHunterWoW_QuestEN[25084] = { title = "A Growing Threat", description = "A moment there, {class}.\n\nWe've got more problems here than just the end of the world as we know it. Our vigil here's threatened by the quilboar. We've been content to leave them be when they stay in the Kraul, sure, but every day they press further and further out towards our camp.\n\nMahka, bless her green heart, wouldn't ever forgive me if I went out bashing heads in myself, but if you could help drive back those that're wandering near the camp, I'd appreciate it.", objectives = "Kill 13 Razormane Quilboar.", completion = "You've my thanks, if not that of the entire Earthen Ring.\n\nMaybe someday we'll find a way to talk it out with these pigs, but we can't heal the land if we're dead in our sleep." }
WordHunterWoW_QuestEN[25085] = { title = "Mangletooth", description = "Una here used to spend time in Camp Taurajo. She's told me about a quilboar that used to be captured there, named Mangletooth. Quite the clever one, for a quilboar.\n\nI've been tryin' to think what got these quilboar riled up so much recently, and it might be that Mangletooth escaped Taurajo alive. If he has, he's certainly calling the shots.\n\nThere's a large hut up in the hills to the northwest. If you find Mangletooth there, cut 'im down.", objectives = "Kill Mangletooth.", progress = "Did you find him?", completion = "That's a relief. Maybe the rest of 'em will keep to their own devices now. The less fighting around here, the better." }
WordHunterWoW_QuestEN[25086] = { title = "Firestone Point", description = "Can you do me a huge favor, {name}? My sister-in-law's uncle is in the Earthen Ring, and he's here in the Barrens studying the impact of the Cataclysm, down at Firestone Point. He says their camp is surrounded by quilboar and I worry that they might get overrun.\n\nCan you check in on Dorn Redearth for me? I'd hate for anything to happen to him, what with the close family bond and all. ", objectives = "Seek out Dorn Redearth at Firestone Point in Southern Barrens.", completion = "What? Little Logan thinks I might need protection?\n\nIt's me doing the protectin'!\n\nThe quilboar here are poised to rampage. They've choked off the entire south, and we're the only thing standing in their way." }
WordHunterWoW_QuestEN[25087] = { title = "Report to Twinbraid", description = "The Alliance owes a debt to the dwarves of Bael Modan, who built some of our earliest fortifications in the Barrens.\n\nTheir commander, General Twinbraid, is a real stalwart. One of our best. He's on patrol south of here, keeping the Horde on their toes.\n\nI definitely want to keep him appraised of the situation here so we can coordinate our next move. Can you deliver this frontline report to him in the field? ", objectives = "Deliver the Frontline Report to General Twinbraid, who is on patrol in Southern Barrens.", progress = "Hrm, news from the fortress? Well. Spit it out!", completion = "<The General reads over the report, nodding in approval as he reads about the Battlescar.>\n\nQuite a name you're earning for yourself here in the Barrens, <name>. But Roberts isn't going far enough. What we need is a decisive victory..." }
WordHunterWoW_QuestEN[25089] = { title = "Beyond the Graves", description = "Darnell tells me that the two of you have already met.  That's good, because I'm sending you both into Deathknell.  Your work is done here.\n\nSpeak with Deathguard Saltain in Deathknell, to the north.  He will tell you more of what you must know.", objectives = "Speak with Deathguard Saltain at Deathknell in Tirisfal Glades.", completion = "Those val'kyr have been really busy resurrecting you newbies lately.  I've already seen a couple dozen new bodies run down that hill since this morning.\n\nYou, however, are the most promising <class> I've seen today." }
WordHunterWoW_QuestEN[25090] = { title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested this area.\n\nI need someone to beat back the rotting dead and ravaged corpses that have taken this small farm.  Scatter their bones and bring back their putrid claws.  The Deathguards will reward you.", objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Cold Hearth Manor.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I enjoyed watching you smash those <race> into rotting pulp!" }
WordHunterWoW_QuestEN[25091] = { title = "Sandsorrow Watch", description = "If you're looking for more work, I've got a line for you.\n\n I know an elf by the name of Trenton Lighthammer who's been obsessed with the sand trolls near here for years. He's dead-set on finding some kind of mythical sword made by them, and just a while ago he finally got a crew together to go to Sandsorrow Watch and look for it.\n\nLast I heard, they kicked the trolls out of one of their camps and set up shop there. Look for it to the west, near Zul'Farrak.", objectives = "Speak with Trenton Lighthammer at Sandsorrow Watch.", completion = "Marin sent you? I'm appreciative of his help.\n\nI'm here to seek out Sul'thraze. If you wish to help, speak with Mazoga...he's been cooperative so far." }
WordHunterWoW_QuestEN[25092] = { title = "Subduing the Elements", description = "The elements are restless, <class>.  The earthquakes that plague the land and the fires that threaten to burn down Orgrimmar are not normal.  The Earthen Ring are convinced that we must put the elements to rest before they tear Azeroth apart.  We need your help, <name>.\n\nI will give you a bag of Earthen Ring supplies.  In it you will find two items, elemental sapta and a cleansing totem.  Use the sapta to see into the elemental world.  Then use the cleansing totem to subdue the agitated fire spirits.", objectives = "Seer Bahura wants you to use the elemental sapta and cleansing totem from the Earthen Ring supplies to subdue 20 Agitated Fire Spirits.", progress = "Have you subdued the elements yet?", completion = "Well done <name>.  But for every element that is subdued another one takes it's place.  The solution we have here is merely a stopgap.  Hopefully my brethren in the Earthen Ring are making more headway." }
WordHunterWoW_QuestEN[25093] = { title = "The Heads of the SI:7", description = "These orcs were murdered in cold-blood by the Alliance down on the coast. We did nothing to provoke them.\n\nTheir deaths should not be in vain, {name}. Will you bring them justice?\n\n<Aggra appears as if she can barely contain her rage.>\n\nThere are three SI:7 leaders down there along the beach. Bring me each of their heads.", objectives = "Collect the heads of Commander Arrington, Darkblade Cyn, and Alexi Silenthowl.", progress = "Has justice been served?", completion = "Thank you, <name>. The spirits of the fallen can now be put to rest." }
WordHunterWoW_QuestEN[25094] = { title = "Thunderdrome: Zumonga!", description = "Splendidly done! But you'll be fighting more than mere humans!\n\nYour next opponent's a mean one...watch out for his right hook. And his left. I'd be wary of his fists in general.", objectives = "Defeat Zumonga.", completion = "Not bad. You've got a ways to go, however." }
WordHunterWoW_QuestEN[25095] = { title = "Thunderdrome: Sarinexx!", description = "I hope you're ready for the next one, {name}. One mistake could mean instant, painful death! But that's what the people pay to see, isn't it?\n\nI hope you're not afraid of bugs...", objectives = "Defeat Sarinexx.", progress = "Stop wasting my time. Enter and fight!", completion = "Rather impressive. Few can bear to see a silithid reaver face to face, let alone defeat it." }
WordHunterWoW_QuestEN[25096] = { title = "Thunderdrome: Prince Mosh!", description = "We're gonna have to bring out the big guns to top that last fight!\n\nDon't worry, my friend, we've got more blood for you to spill. Many goblins died to capture the next fighter...he's a whopper!You will receive:", objectives = "Defeat Prince Mosh." }
WordHunterWoW_QuestEN[25097] = { title = "Little Sumpthin'", description = "Lissen, pal.\n\nI got a friend, who knows a fella, who might just be lookin' for a <class> that knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands dirty, head south over the mountains and look for a goblin named Vern.\n\nTell him Drazz sent ya...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Drazzit Dripvalve wants you to talk to Vern Futzwidget in Thousand Needles.Lissen, pal.\n\nI got a friend, who knows a fella, who might just be lookin' for a <class> that knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands dirty, head south over the mountains and look for a goblin named Vern.\n\nTell him Drazz sent ya...You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25098] = { title = "The Warchief Wants You", description = "True to his word, Thrall is going to get us going in the right direction to rescue our people. He asked to speak with you.\n\nGood luck, {name}. We're all depending on you.", objectives = "Speak with Thrall at the Warchief's Lookout on the Lost Isles.", completion = "Once again you have helped us to overcome our mutual enemy, the Alliance.\n\nNow it is time for us to help you." }
WordHunterWoW_QuestEN[25099] = { title = "Borrow Bastia", description = "Head back down to the coast and tell Kilag that I'd like for you to borrow Bastia. The panther knows the way to where your friends are being held captive.\n\nGo now. I will see you again before we make our move against the Trade Prince.", objectives = "Speak with Kilag Gorefang at the Tranquil Coast on the Lost Isles.", completion = "Of course you can borrow Bastia. That is, if she'll take you.\n\n<Kilag winks.>" }
WordHunterWoW_QuestEN[25100] = { title = "Let's Ride", description = "Bastia will make sure that you get to where you need to go, goblin.", objectives = "Speak with Slinky Sharpshiv at Sky Falls on the Lost Isles.", completion = "<name>?! Nice kitty.\n\nLook we don't have much time here. You might have noticed that the volcano is blowing?!" }
WordHunterWoW_QuestEN[25101] = { title = "Friend of a Friend", description = "Say, you look like a frisky sort...\n\nI know a guy who knows a fella that might be lookin' for a <class> who knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands a little dirty, make your way south across the mountains and look for a goblin by the name of Vern.\n\nTell him Smiling Jim sent ya.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Smiling Jim wants you to talk to Vern Futzwidget in Thousand Needles.Say, you look like a frisky sort...\n\nI know a guy who knows a fella that might be lookin' for a <class> who knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands a little dirty, make your way south across the mountains and look for a goblin by the name of Vern.\n\nTell him Smiling Jim sent ya.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25102] = { title = "No Bull", description = "Twinbraid's patrols always throw us right into the thick of danger. If it's not Horde ambushes, it's a quilboar hit-and-run.\n\nThe problem is them lousy landquaker kodos. Big walkin' walls of fur, shakin' the ground... We can't see or hear an ambush creepin' up on our backside.\n\nGo scare 'em off from our patrol, here. Killing a few should drive the herd south and out of what's left of me hair.", objectives = "Kill 4 Landquaker Kodos and 1 Landquaker Bull in Southern Barrens.", progress = "Good to see you're not squished.", completion = "I thought you might be responsible for them clouds of dust I saw to the east. Nice work! Them bulls ain't sissies." }
WordHunterWoW_QuestEN[25103] = { title = "Bootlegger Outpost", description = "We've done a bang up job here. I'm gonna make sure these mooks finish properly and then head back to Gadgetzan for a bit.\n\nIf you want to keep making a good impression on our Steamwheedle friends, or just make more money, you should head southwest of here. Bootlegger Outpost is set up on the edge of the gaping chasm.\n\nTalk to Zeke Bootscuff. I'd bet good money he'll need help.", objectives = "Talk to Zeke Bootscuff at Bootlegger Outpost.", completion = "You're with Megs, huh? Word is she's been pretty hell-bent on making nice with Noggenfogger.\n\nNot like I care. Are you ready to kill some bugs?" }
WordHunterWoW_QuestEN[25104] = { title = "Digsite Status", description = "The patrol's been quiet today. And that's got me worried, {name}.\n\nEver since the Alliance sacked Taurajo, none of our positions are secure. You look like you can handle yourself - can you scout around for me?\n\nCheck in with my son Marley outside the Bael Modan excavation, southeast of here. The site's exposed and susceptible to raids, and my son's too proud to signal for help if he needs it.", objectives = "Locate Marley Twinbraid outside the Bael Modan Excavation in Southern Barrens.", completion = "Father sent you? He worries too much. There's nothing here I can't handle...\n\nBut I'd still appreciate the help." }
WordHunterWoW_QuestEN[25105] = { title = "Nibbler!  No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", objectives = "Cut three Solid Zephyrites and give them to Isabel Jones in Stormwind City.", progress = "Have you brought the solid zephyrites I need?", completion = "You've really saved my skin, <name>.  Thanks!" }
WordHunterWoW_QuestEN[25106] = { title = "Hands Off Me Dig!", description = "Look at the chaos down there, {name}! I've instructed the foremen to save what artifacts they can. Who knows what treasures these tauren animals are like to make off with.\n\nCan you help get a handle on things? Kill the raiders and save what artifacts you can.\n\nWhile you're at it, look for my missing tools. A few quick repairs and I can get this flying machine up and running again.", objectives = "Kill 8 Excavation Raiders, rescue 5 Bael'modan Artifacts, and acquire Twinbraid's Tools in the Bael'modan Digsite.", progress = "How's the situation down there?\n\nWhen the raid started I popped a bullet into their ringleader, Stonespire, but they just kept right on coming.", completion = "My father would be proud of you, <name>.\n\nNow, to get this flying machine up and about again..." }
WordHunterWoW_QuestEN[25107] = { title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Andoren would probably like to see this.", objectives = "Take the Grand Tablet to Andoren Dawnrise.", progress = "You're back! What have you found?", completion = "This is truly incredible. The hieroglyphs are undoubtedly titan, but the markings below it...\n\nSome of these characters resemble ancient Kaldorei writings. And you say the antechamber was covered in hieroglyphs?\n\nYou've made a find more monumental than any riches, <name>. Please, take whatever reward you prefer." }
WordHunterWoW_QuestEN[25108] = { title = "Feegly the Exiled", description = "Saddest story I ever heard told, {name}. Feegly was one of our fastest diggers, until he got a hold of that - thing. \"The Tear of the Moons\" we called it. It changed him. Remade him. I wish it had stayed buried.\n\nFeegly was banished from Bael Modan but I've heard reports he's come sniffing around the dig site again. He's suffered enough, the wretched thing. If you find him down there, put ol' Feegly out of his misery.", objectives = "Kill Feegly the Exiled in the Bael Modan Digsite.", completion = "<Marley nods grimly.>\n\nAye, it's for the best I suppose." }
WordHunterWoW_QuestEN[25109] = { title = "The Gallywix Labor Mine", description = "We barely escaped with our hides intact!\n\nThe Trade Prince has a whole bunch of us enslaved and performing manual labor inside the cavern.\n\nGreely helped the seven of us to get out, but she was recaptured in the process.\n\n{name}, you're the only one crazy enough to walk into an exploding volcano! The assistant will be able to help you free the others.\n\nHurry! This place is about to blow for good!", objectives = "Speak with Assistant Greely inside the Gallywix Labor Mine on the Lost Isles.", completion = "<The assistant looks confused.>\n\nHuh... what? Who?" }
WordHunterWoW_QuestEN[25110] = { title = "Kaja'Cola Gives You IDEAS! (TM)", description = "Assistant Greely is clearly bewildered and intimidated. How will she help you to find a way to rescue everyone in this condition?\n\nMaybe if she were to drink one of those Kaja'Cola Zero-One drinks you saw, she'd be able to have a bright idea?", objectives = "Collect 1 Kaja'Cola Zero-One.", progress = "Huh?", completion = "<Assistant Greely spots the Kaja'Cola Zero-One in your hand and her eyes seem to come to life.>" }
WordHunterWoW_QuestEN[25111] = { title = "Scavengers Scavenged", description = "Now that I know you're not squeamish, I've got another job for you. Have you seen the red-feathered birds swarming around the bones out there? Those are fire rocs. They'll light you up good if you're not careful.\n\nThey're also pretty darn valuable thanks to their unique anatomy. Most of the hunters loafing around here aren't up to the task of killing fire-spitting buzzards for money... think you can handle it?", objectives = "Use Butcherbot to harvest 12 Fire Roc corpses.", completion = "Alchemists pay through the nose for these things. Sure, maybe I tell some of them they're dragon parts, but that ain't my problem, right?" }
WordHunterWoW_QuestEN[25112] = { title = "Butcherbot", description = "I make my money around here selling animal parts. I've been perfecting a foolproof method of maximizing profit: The butcherbot!\n\nThese little guys are programmed to harvest every scrap of usable material from the wildlife around here, on a case-by-case basis. He does all the work, and best of all, only I know how to get the goods back out of him.\n\nIf you're interested in making some coin, take one of these guys for a spin. I need some glasshide basilisk parts; you'll find a bunch of them to the south.", objectives = "Use the Butcherbot to harvest 10 Glasshide Basilisk corpses.", completion = "Nice going, kid. Didn't lose any fingers? Good, we can get some more work for you then." }
WordHunterWoW_QuestEN[25113] = { title = "corpid Poaching: Dunestalkers", description = "The bigger scorpids to the south, the dunestalkers, are too tough and dry for the tail meat to sell. But I'll tell you what everyone overlooks: the legs!\n\nI won't bother you with all the finer details of scorpid part appraisal, but suffice it to say they sell like hotcakes. Or crablegs. Crabcakes?\n\nAnyway, I don't care what the chefs do with them as long as the money flows. Bring me about, oh, twelve pounds of legs.You will receive:", objectives = "Collect 12 Pounds of Dunestalker Legs from Scorpid Dunestalkers." }
WordHunterWoW_QuestEN[25114] = { title = "asilisk Poaching: Gazer Guts", description = "That last job didn't exactly paint you as the dainty type, so I think you're cut out for more.\n\nThe larger basilisks to the south, the gazers, get to some impressive sizes. The alchemists prefer the smaller brains, usually, but the other organs are better sized up.\n\nAt any rate, I'm no alchemist: I just know what Driz sells by the truckload. Bring us back a sack full of gazer guts.You will receive:", objectives = "Collect 12 Gazer Guts from Glasshide Gazers." }
WordHunterWoW_QuestEN[25115] = { title = "Blisterpaw Butchery", description = "The hyenas wandering the wastes here might look scrawny, but they've got some of the strongest jaws you'll find! If you're not careful, they'll take a leg off in one bite. That kind of bone strength is a valuable resource, my friend, just waiting to find a buyer!\n\nTake one of my Butcherbots with you. Jaw separation isn't an easy task, and this little guy has been set up to know exactly what to do. Just bring him back when he's full.", objectives = "Use the Butcherbot to harvest 10 Blisterpaw Hyena corpses.", completion = "Beautiful! We'll have these puppies shined up and ready to sell in no time." }
WordHunterWoW_QuestEN[25116] = { title = "yena Poaching: Rabid Livers", description = "I know Driz hates sport hunting, but the way I see it, it's okay to have fun as long as you're not being wasteful! Right?\n\nWhat I mean is, the northern hyenas are no fun. The ones further south, they've all got nasty cases of rabies. Now that's fun, when a single deep bite could do you in! And what's more, the rabies makes the liver swell up so much, it's prized for its weight.\n\nNow I've gotten all worked up again. Could you bring back some livers while I sit here, bored? Sigh.You will receive:", objectives = "Collect 12 Rabid Livers from Blisterpaw Hyenas." }
WordHunterWoW_QuestEN[25117] = { title = "Scout's Dishonor", description = "The Dark Iron are up to their usual tricks out here. They've been keeping to themselves, but I just know trouble's brewing.\n\nWe're going to take a look at it. There's a Dark Iron Scout puttering around the center of what used to be the Loch, keeping an eye out. I want you to take him out and bring back any documents or orders he has.\n\nIf my suspicions are unfounded... I'll take the blame from Moira myself. Promise ya.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect the Dark Iron Dispatch from the Dark Iron Scout." }
WordHunterWoW_QuestEN[25118] = { title = "Looking for Lurkers", description = "I don't know about you, but I'm not much a fan of spiders, much less the kind that come bigger than me. Loch Modan's a gorgeous place, but I'd say it could do without those horrid things waltzing around.\n\nTell you what, I've got some spare coin, and you look like a tough one. If you head out and off some of those things for me, I'll pay you for your time.", objectives = "Kill 8 Forest Lurkers.", completion = "I'll rest easier knowing one of those lumbering things won't be wandering into my bedroom at night... again.  Thanks much." }
WordHunterWoW_QuestEN[25119] = { title = "Impulse Hunting", description = "Ashlan's no doubt going to send you off to the Loch to investigate the Dark Iron hooligans he keeps muttering about. If you're headed down there, might as well make some coin while you're at it, right?\n\nThe loch's draining wiped out most of the wildlife in it. Not many places to swim anymore. But there's still crocolisks padding around on the now-dry ground.\n\nThey'll starve in time, so we may as well get 'em while they're fresh. Bring me back some full sides of croc and we'll talk rewards.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Sides of Crocolisk from Loch Crocolisks." }
WordHunterWoW_QuestEN[25120] = { title = "Marley's Final Flight", description = "Okay, {name}! Let's take these artifacts to my father and give him our report firsthand.\n\nThanks to your help my flying machine is ready to roll. We can fly there together and share in the glory.\n\nTalk to me when you're all set to move out!", objectives = "Talk to Marley Twinbraid and take a spin in his flying machine.", completion = "<The battered dwarf hangs limply from the cockpit. As you approach the burning wreckage, his eyes flutter open.>\n\n<Marley Twinbraid is still alive!>" }
WordHunterWoW_QuestEN[25121] = { title = "Momentum", description = "It looks like we've got more work to do! Having Mr. Noggenfogger ask us to take care of the rest of the pirates is a true honor.\n\nSince you've been SO helpful, why don't you meet me at Lost Rigger Cove? I've just got to slip into something a bit more comfortable, so don't wait on me. I'll beat you there, promise!", objectives = "Meet Kelsey Steelspark at Lost Rigger Cove.", completion = "Hi there! The fun's already started!" }
WordHunterWoW_QuestEN[25122] = { title = "Morale Boost", description = "You've got to get all the Kaja'Cola Zero-One that you can and make the goblins drink it to boost their morale and free them!", objectives = "Use Kaja'Cola Zero-One to free Ace, Izzy, Gobber, and 6 Goblin Survivors or Kezan Citizens.", progress = "Increase their morale, <name>, so that they will run to freedom!", completion = "I hate the Trade Prince, but you can't argue with the results of his methods. Kaja'Cola Zero-One is a huge improvement over regular old Kaja'Cola at half the calories and twice the ideas!" }
WordHunterWoW_QuestEN[25123] = { title = "Throw It On the Ground!", description = "This nightmare will never be over while Blastshadow the Brutemaster still breathes. There are a couple of problems though.\n\nOne, being a warlock, he's got a succubus named Delicia Whipsnaps. If you kill Blastshadow quickly, the demon will go back to where it was summoned from.\n\nThe second problem, since Blastshadow is a warlock, he has a soulstone that allows him to resurrect. You have to get his soulstone and destroy it so that he'll be dead forever!", objectives = "Destroy Blastshadow the Brutemaster's soulstone.", progress = "The soulstone is the key, <name>!", completion = "Your soulstone has expired, Blastshadow!" }
WordHunterWoW_QuestEN[25124] = { title = "Brute Brutality", description = "I was thinking. You should probably take care of some of these Brute Overseers while you're doing everything else.\n\nYou know?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 6 Brute Overseers." }
WordHunterWoW_QuestEN[25125] = { title = "Light at the End of the Tunnel", description = "Okay, we have got to get out of here before she blows for good!\n\nLet's head out the other end of the tunnel on the north side of the mine. We should be able to use one of the mine carts for a quick ride down the side of the volcano.", objectives = "Interact with the Mine Cart outside the Gallywix Labor Mine on the Lost Isles.", completion = "Looks a little rickety...." }
WordHunterWoW_QuestEN[25126] = { title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you'll be of more use to us slaughtering the boars you'll find in the farms to the north and northeast of here.", objectives = "Slaughter 6 Mottled Boars.", progress = "I hope you haven't returned to try and convince me that you have completed your task, <name>? No, of course not. I would think better of you.", completion = "Hmmm, not bad, <name>. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection." }
WordHunterWoW_QuestEN[25127] = { title = "Sting of the Scorpid", description = "I must send you back into the fields again, {class}. You will find large numbers of scorpids northwest of here. Bring me eight of their tails.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", objectives = "Obtain 8 Scorpid Worker Tails.", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, <name>. You have done well, and I will watch your progress with interest." }
WordHunterWoW_QuestEN[25128] = { title = "Hana'zua", description = "Hey mon, take a knee and hear me out. We got a problem.\n\nA good friend of mine, Hana'zua, has gone out into the valley and he hasn't returned. Last I seen, he was headin' north, where the scorpids hunt. Maybe you go take a look for him? The spirits be tellin' me that he's not well.", objectives = "Find Hana'zua in the Valley of Trials.", completion = "<Hana'zua groans in pain.>" }
WordHunterWoW_QuestEN[25129] = { title = "Sarkoth", description = "{class}! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", objectives = "Kill Sarkoth and bring his claw back to Hana'zua.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger." }
WordHunterWoW_QuestEN[25130] = { title = "Back to the Den", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to our settlement unassisted. Please, {name}, return and tell Gornek of my situation. Perhaps he can help me.", objectives = "Bring the news of Hana'zua's plight to Gornek in the Valley of Trials.", completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, <name>. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened." }
WordHunterWoW_QuestEN[25131] = { title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young {class}.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nOne of the Burning Blade - a foul, demon-worshipping cult - has made camp here in the Valley of Trials. He skulks in a cave to the north, and his vile familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", objectives = "Kill 8 Vile Familiars.", progress = "To prove yourself against the Burning Blade, you must first defeat these vile familiars. Return to me when you have done this.", completion = "You have done well, <name>.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead." }
WordHunterWoW_QuestEN[25132] = { title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power--a medallion--hides deep within the Burning Blade Coven, guarded by beasts and black magic. We must have it.\n\nFor too long these demon-worshippers have defiled our homelands. Cleanse the coven of its demonic taint by slaying the fel beasts and their leader. Return with this medallion as proof of your deed.\n\nGo, {name}. You will find the coven in a cave to the north.", objectives = "Slay 5 Felstalkers and obtain the Burning Blade Medallion.", progress = "Is your task complete, <name>?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them." }
WordHunterWoW_QuestEN[25133] = { title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley. But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin. Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials. Discover from him if they have yet reached Sen'jin.\n\nGo, {name}, and be swift. I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", objectives = "Speak with Master Gadrin in Sen'jin Village.", completion = "Hm... your report comes at a bad time.  The Burning Blade is no longer seen here in Sen'jin, but we will be vigilant in our efforts to prevent their return to the area.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too." }
WordHunterWoW_QuestEN[25134] = { title = "Lazy Peons", description = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right <race> for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLook for them underneath the trees in the valley.  Lousy slacking peons...", objectives = "Use the Foreman's Blackjack on 4 Lazy Peons when they're sleeping.", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!" }
WordHunterWoW_QuestEN[25135] = { title = "Thazz'ril's Pick", description = "{name}, you are a dependable {race}. Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind. When I later returned to retrieve it I found the cave was filled with vicious beasts! Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls. My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", objectives = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", progress = "Have you entered the Burning Blade Coven, <name>?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, <name>.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!" }
WordHunterWoW_QuestEN[25136] = { title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, {name}. If you bring me six cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", objectives = "Obtain 6 Cactus Apples.", progress = "Have you finished collecting cactus apples?", completion = "Wonderful, <name>! As promised, here is your cactus apple surprise plus a little something extra." }
WordHunterWoW_QuestEN[25137] = { title = "Valley of Trials: PRK - H - Warlock Pet Imp", description = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.You will learn:", objectives = "Bring 6 Vile Familiar Heads to Ruzan." }
WordHunterWoW_QuestEN[25138] = { title = "Glyphic Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Acrypha. She would have words with you when you're ready.", objectives = "Read the Glyphic Parchment and speak with Acrypha in the Valley of Trials.", progress = "What?  Who are you?  Get away!\n\nOh, you're the other <class>, the new one, the one with the big arms.  Come on, let's get to work.", completion = "Ahh, where to start... introductions!  I'm Acrypha - the one who sent you that parchment - I've spent the last several years in an Undercity library, my head in a book.  I learned everything I could about the arcane, and now I've returned home to share it with grunts like yourself.\n\nShall we begin?" }
WordHunterWoW_QuestEN[25139] = { title = "Steady Shot", description = "You already know how to fire an arcane shot. Good. But doing so depletes your focus. To gain your focus back you will need to switch to a second type of ranged attack.\n\nGo out and get some more experience. As you do, you'll learn some new abilities. The first of these will help you get your focus back.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy and practice using Steady Shot 5 times.", completion = "You learn quickly." }
WordHunterWoW_QuestEN[25140] = { title = "Swine Hunting", description = "Just to the south of this village, you will find a young swine that goes by the name of Lo'shall.  He hides among the cactus and the trees.  While he is small of size, he conceals an intelligence that most boars lack.\n\nFind him, pluck one of his hairs, and then return to me.\n\nRemember what I taught you, <name>.  You may find Track Beasts to be helpful here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Pluck Lo'shall's hair. You may wish to use Track Beasts." }
WordHunterWoW_QuestEN[25141] = { title = "Eviscerate", description = "Let's start with the basics, shall we?  I'm the only rogue trainer in town, so you're going to have to learn it from me.\n\nGo get some more experience, figure out how to eviscerate your foes, and then show me on the training dummies here. I'll evaluate your form.", objectives = "Reach Level 3 to Learn Eviscerate, then locate a Training Dummy and practice using Eviscerate 3 times.", completion = "You won't be sorry.  The ability to capitalize on the opportunities created by previous attacks is one of our greatest strengths." }
WordHunterWoW_QuestEN[25142] = { title = "Into the Shadows", description = "I want to see you try to sneak past me.  I'll still be able to detect you, since you're still a novice, so don't try anything funny.  I just want to see what you've learned.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use your Stealth ability next to Rwag in the Valley of Trials." }
WordHunterWoW_QuestEN[25143] = { title = "Primal Strike", description = "As you grow in power by gaining levels, you will discover the power to use new abilities. The first you will discover on your journey is Primal Strike.\n\nUse it to deliver a strike with your weapon, infused with the power of the elements.\n\nIt is time to learn and master your new skill. Practice using it on the training dummies outside the Den.", objectives = "Learn Primal Strike by reaching Level 3, then look for a training dummy near Shikrik and practice using Primal Strike 3 times.", completion = "Very well.  Now that you know how to speak with the elements, we will test your bond with them." }
WordHunterWoW_QuestEN[25144] = { title = "Rock Meets Flesh", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to use this ability on one of these invaders, <name>.  Enchant your blade with the power of earth, then strike out at these enemies!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat a Captured Northwatch Scout while your weapon is enchanted with Rockbiter Weapon." }
WordHunterWoW_QuestEN[25145] = { title = "Corruption", description = "It is my duty to train you, and I intend to do just that.\n\nAs you become more powerful, you will begin to hear the fel voices revealing new spells to you.\n\nGo, get more experience, learn a new spell, and then practice your new spell against one of the training dummies around here.", objectives = "Reach level 3 to learn Corruption. Locate a Training Dummy and practice casting Corruption 5 times.", completion = "You appear to be a quick learner." }
WordHunterWoW_QuestEN[25146] = { title = "A Demonic Fire", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to burn one of these invaders, <name>.  Cast your newly-learned spell on the human dogs, then watch them suffer.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Cast Immolate on a Captured Northwatch Scout." }
WordHunterWoW_QuestEN[25147] = { title = "Charge", description = "I've been instructed to prepare you for battle. Though, from the look of you, it looks like you've already spent a little time out in the field. Good.\n\nAs you continue your journey, you'll discover that you can begin to use new techniques\n\nGo, get some more experience, and teach yourself how to Charge, then show me what you've learned.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy and practice using Charge.", completion = "You understand now?  Good, let's try it out." }
WordHunterWoW_QuestEN[25148] = { title = "Hone Your Holler", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to use your shout on one of these invaders, <name>.  Defeat a captured Northwatch scout while under the effects of your battle shout.  Return when you are successful.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat a Captured Northwatch Scout while under the effects of Battle Shout." }
WordHunterWoW_QuestEN[25149] = { title = "Frost Nova", description = "Alright, here's the easy part.\n\nAll you have to do to deepen your connection to the arcane is to get more experience and grow your power. You'll begin to find that you can cast new spells.\n\nYou'll see. Go try it, and show me what you learn.", objectives = "Reach level 3 to learn Frost Nova. Locate a Training Dummy and practice using Frost Nova 2 times.", completion = "Good.  Now we practice." }
WordHunterWoW_QuestEN[25150] = { title = "Empowered Minds", description = "Arcane Intellect is a spell that you can use on yourself, your friends, or even random passers-by.  While under the spell's temporary effect, you should feel a bit more... mentally acute.  Now let's try it out.\n\nI want you to cast Arcane Intellect on someone.  Actually, scratch that.  I want you to cast it on ME.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Cast Arcane Intellect on Acrypha." }
WordHunterWoW_QuestEN[25151] = { title = "He Needs Ale!", description = "<Marley grasps the side of your head with a shaking, bloody hand.>\n\nAle... Must... have ale...\n\nOl' Barkerstout from inside. <He coughs.> That should ... do the trick.", objectives = "Search Bael'dun Keep for a Mug of Ol' Barkerstout and bring it to Marley Twinbraid at the entrance.", progress = "<Marley's breathing is ragged, coming and going in shuddering gasps.>\n\n<His eyes look at you imploringly.>", completion = "<Marley's eyes sparkle as you rush toward him with the ale. He grasps the mug in both of his shaking hands and upends it, white foam spilling out over his blood-caked beard.>\n\nAh... that's the stuff. Ol' Barkerstout... Thank you, friend.\n\nThat'll make this... a little easier.\n\n<Coughing one final time, he slumps over the shattered control console, the half-empty mug crashing to the ground and spilling its contents into the sand. His eyes glaze over.>\n\n<Marley Twinbraid is dead.>" }
WordHunterWoW_QuestEN[25152] = { title = "Your Place In The World", description = "Finally, you are of age, {name}... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young {class}. You will find him seated at the fire behind me.", objectives = "Speak with Gornek.", completion = "Another one of Kaltunk's recruits, hm?\n\nA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud warrior of the Horde." }
WordHunterWoW_QuestEN[25153] = { title = "Bael'dun Rescue", description = "Help - Help! You've got to do something!\n\nSome dwarves are still inside - so many - they're trapped in the debris. Buried alive. The flames! It's a nightmare in there. We don't know how much longer until the roof collapses...\n\nPlease, {class}, you've got to save them!\n\nRun inside. Use the emergency fire valves to protect yourself from the flames. You're the only hope they have...", objectives = "Go into Bael'dun Keep and rescue 10 Bael'dun Survivors from the rubble.\n\nUse the Emergency Fire Valves to protect yourself from the flames.", progress = "So many corpses... I don't know how I got out alive...", completion = "You're a legend, <name>.\n\nThe other survivors and I will be telling the story of your deeds for years to come." }
WordHunterWoW_QuestEN[25154] = { title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Curver last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Curver didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", objectives = "Cut three Timeless Nightstones and give them to Isabel Jones in Stormwind City.", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Marith Lazuria in Orgrimmar with these!  I can't wait to see the look in her beautiful eye when I give this to her." }
WordHunterWoW_QuestEN[25155] = { title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", objectives = "Cut three Jagged Jaspers and give them to Isabel Jones in Stormwind City.", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!" }
WordHunterWoW_QuestEN[25156] = { title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Barnsworth Elemental Glue!  The professor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", objectives = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Isabel Jones in Stormwind City.", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�" }
WordHunterWoW_QuestEN[25157] = { title = "The Latest Fashion!", description = "Professor Barnsworth has been working on this new stardust - what with the fashion in Stormwind this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some humanoid testing - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on some humanoid subjects.", objectives = "Test Stardust No. 2 on 10 \"humanoid subjects\".", completion = "It did what!?  We're ruined!  Hmm.  Well, actually... Maybe the professor can find some other applications for it?" }
WordHunterWoW_QuestEN[25158] = { title = "Nibbler!  No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", objectives = "Cut three Solid Zephyrites and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me those solid zephyrites I need?", completion = "You've really saved my skin, <name>.  Thanks!" }
WordHunterWoW_QuestEN[25159] = { title = "The Latest Fashion!", description = "Dr. Vernstrom has been working on this new stardust - what with the fashion in Orgrimmar this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some \"live testing\" - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on humanoid subjects.", objectives = "Test Stardust No. 2 on 10 \"humanoid subjects\".", completion = "It did what!?  We're ruined!  Hmm.  Well, actually...  Maybe the doctor can find some other applications for it?" }
WordHunterWoW_QuestEN[25160] = { title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Bonder last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Bonder didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", objectives = "Cut three Timeless Nightstones and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Isabela Jones in Stormwind with these!  I can't wait to see the look in her beautiful eye when I give this to her." }
WordHunterWoW_QuestEN[25161] = { title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", objectives = "Cut three Jagged Jaspers and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!" }
WordHunterWoW_QuestEN[25162] = { title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Vernstrom Elemental Glue!  The doctor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", objectives = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Marith Lazuria in Orgrimmar.", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�" }
WordHunterWoW_QuestEN[25163] = { title = "Who Did This?", description = "Sabotage! It had to be. The whole fortress magazine exploded. The Horde must've gotten someone inside...\n\n{class}, if you've the stones to rush into that burning nightmare... look for some clues as to who did this to us. The General will want to know! Look for a Horde corpse in the wreckage and get to the bottom of this disaster...", objectives = "Look for a Horde corpse within Bael'dun Keep.", completion = "<One smoldering corpse stands out amidst the carnage. The dead goblin clutches the schematics of the fortress in his lifeless hand...>\n\n<The Bilgewater Cartel goblins. They did this!>" }
WordHunterWoW_QuestEN[25164] = { title = "Backed Into a Corner", description = "The naga are upon us, {class}. Aid us in fightin' dem off!", objectives = "Defend the Earthen Ring camp until the naga retreat.", progress = "Dey seem relentless, but we gonna turn dem back!", completion = "I'm glad you were here, mon.\n\nToshe be lookin' like he wants to chase dem down. You should go help'em." }
WordHunterWoW_QuestEN[25165] = { title = "Never Trust a Big Barb and a Smile", description = "Next, we gonna get some poison from the scorpions that be runnin' around here.  But don't you worry, Bom'bay's not gonna let you get hurt!\n\nBom'bay's got a big totem that you gonna stick in the ground when the scorpion strikes.  The totem gonna suck up all the poison, and you gonna walk away still breathing.  Sound good?", objectives = "Obtain 6 samples of Scorpid Venom by placing the Poison Extraction Totem near a Clattering Scorpid.", progress = "You got the jujus, ya?", completion = "This is it!  The scorpid juju Bom'bay been waitin' for!  Now we gonna fix you right up, <class>.\n\nYou come back to Bom'bay when you be needin' a pickup.  Bom'bay got the spells to fix ya!" }
WordHunterWoW_QuestEN[25166] = { title = "Captain Dreadbeard", description = "This is getting pretty fun, but let's not forget we're here for Gnomeregan!\n\nWe spotted the captain of the Southsea over on one of his boats to the south, past where all the fighting is. He's all alone on his little boat, undefended!\n\nIf you go take care of him, we'll have the rest of these pirates mopped up in no time.", objectives = "Kill Captain Dreadbeard.", progress = "My patience is beginning to wear thin. I don't have enough time to wait around for you, so kill that captain already.\n\nUm, I mean, please? Tee-hee?", completion = "He was controlling a sea giant? Fascinating. If we'd managed to investigate further...\n\nOh, I mean, wow, that's totally crazy! But thank goodness he's gone, hooray! Mister Noggenfogger will be so pleased.\n\nHere's a nice big reward, you!" }
WordHunterWoW_QuestEN[25167] = { title = "Breaking the Chain", description = "Aw man, this ain't good.  Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin.  And then what happens?  Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base.  You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.", objectives = "Destroy 3 Northwatch Supply Crates and kill 10 Northwatch Lugs.", progress = "We gotta get rid of these humans, <class>.", completion = "Well, we've stymied their efforts for now, but they're still here.  We'll have to press on, <name>." }
WordHunterWoW_QuestEN[25168] = { title = "Purge the Valley", description = "Northwatch is a highly-defended stronghold southwest of here, across the harbor.  It's a strategically-located stronghold that the Horde still struggles to overtake.  We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, {name}.  Let them know the power and the fury of Sen'jin.", objectives = "Defeat 12 Northwatch troops in Northwatch Foothold.", completion = "A battle well-fought, <class>, but I still have my doubts about our effectiveness.  These humans don't seem to be going anywhere.\n\nYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you." }
WordHunterWoW_QuestEN[25169] = { title = "The War of Northwatch Aggression", description = "These humans in the west, they don't just wanna camp out in Durotar, mon.  They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it.  Nope!  Not Lar!  I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon.  Big scrolls, real important-lookin'.  We gonna burn those scrolls before they burn us.", objectives = "Destroy the 3 sets of Attack Plans held within Northwatch Foothold.", progress = "Destroy those humans, <name>.", completion = "Good work, hero.  You done good for Sen'jin today.  No... you done good for all of Durotar." }
WordHunterWoW_QuestEN[25170] = { title = "Cleaning Up the Coastline", description = "Heya mon!  Bom'bay be workin' on some new mojo.  You wanna try a piece of it?  Well, before ya do, Bom'bay's gonna need ya to pick up some jujus.\n\nFirst, Bom'bay needs ya to get some o' the goop from the crabs down by the water.  Let me see your hands!\n\n<Bom'bay examines your hands closely.>\n\nBom'bay gonna need 5 handfuls.  Go on now!", objectives = "Obtain 5 handfuls of Crawler Mucus.", progress = "You bring the jujus, I show you my mojo.", completion = "Ya mon, that's tha stuff.  Now we get the other jujus." }
WordHunterWoW_QuestEN[25171] = { title = "Riding On", description = "We gotta pass the word on to Razor Hill.  These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin.  He'll give you a ride to Razor Hill.  His wolves know the path well.", objectives = "Speak to Raider Jhash to get a ride to Razor Hill. Once there, speak with Gar'thok.", completion = "That <race> wants us to send help?  Bah, he can forget it.  I've got my own human problems to worry about, and even those are the least of my worries right now.\n\nSen'jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation." }
WordHunterWoW_QuestEN[25172] = { title = "Invaders in Our Home", description = "You're not just another grunt - you seem to be a serious {class}. Good, because that's exactly what I need.\n\nTry not to let the word out, since I don't want to cause a panic... but there have been reports of more humans nearby. This is an egregious betrayal of the peace that we negotiated with that miserable Jaina Proudmoore! We can't allow humans here in Durotar, and especially not here in the Valley.\n\nYou will find them to the south. Slay them quickly, before their numbers increase any more.", objectives = "Slay 7 Northwatch Scouts.", progress = "Quickly, <name>. Dispatch of these humans in our valley.", completion = "Executed with quickness and discretion.  A job well done." }
WordHunterWoW_QuestEN[25173] = { title = "From Bad to Worse", description = "Tiragarde Keep lies to the southeast of here, on Durotar's eastern shore.  You probably passed it on your trip from Sen'jin Village.  This castle has been a thorn in my side for too long.\n\nHumans from Kul Tiras lived in the castle for years, thwarting my every attempt to crush them.  When the cataclysm hit us, the shore was wiped out, along with the castle and all the humans.  However, these upstarts from Northwatch have moved in to take their place!\n\n<Gar'Thok roars in aggravation.>", objectives = "Kill 6 Northwatch Marines, 6 Northwatch Sharpshooters, and Lieutenant Palliter in Tiragarde Keep.", completion = "Word of your bravery travels fast, <class>. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar." }
WordHunterWoW_QuestEN[25174] = { title = "Twinbraid Needs to Know", description = "<General Twinbraid will want to know the details of this cowardly attack. You gather up the evidence.>", objectives = "Report to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "What... WHAT!?\n\nBael'dun in ruins? Corpses everywhere - no. No!\n\n<You describe the evidence you found at the scene.>\n\nThe Bilgewater goblins, was it? They want a fight do they? We'll show 'em what it means to be a part of the Horde, we will. I'll fill the Battlescar with their corpses. I'll redden the dirt with their blood.\n\n<Twinbraid grabs you by the collar.>\n\nGoblins. Are going. To die!" }
WordHunterWoW_QuestEN[25175] = { title = "The Bad News", description = "<You gently close Marley's eyes.>\n\n<Someone is going to have to tell General Twinbraid that the Horde has killed his only son.>\n\n<That someone is you.>", objectives = "Bring the bad news to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "<General Twinbraid hurls his axeblade into the dirt, his voice quiet but his body quivering with disbelief and rage.>\n\nThat was my boy, <name>. My only boy.\n\nThey've made it personal, <class>. Personal." }
WordHunterWoW_QuestEN[25176] = { title = "Exploiting the Situation", description = "Hey there, handsome!  I've had my eye on those big, beefy biceps ever since you stepped into town.\n\nListen, I've got something for you to do.  I hear Gar'Thok's got you headed over to Tiragarde.  While you're there, think you could find some abandoned Kul Tiras knicknacks?\n\nThanks sweetie!", objectives = "Obtain 6 pieces of Kul Tiras Treasure.", progress = "<Gail purrs disarmingly at you.>", completion = "You brought me my treasure!  What a sweetheart!" }
WordHunterWoW_QuestEN[25177] = { title = "Storming the Beaches", description = "Now that those humans are out of our hair for a bit, we can move on to more pressing matters.\n\nThe cataclysm utterly decimated Durotar's eastern coast.  You saw the wreckage that it made of Tiragarde.  The devastation was even worse on the coast to the east of here.\n\nAfter the first wave, the beach was overtaken by angry elementals that came from the sea.  I sent grunts to take care of it, but the onslaught was too much.  I'm guessing you'll have a little more luck than they did.\n\nBeware the tides!", objectives = "Kill 11 Foaming Sea Elementals.", completion = "The scent of the sea hangs about you, <name>.  Your efforts may have purchased another day for Razor Hill.\n\nI will pass word of your deeds up my chain of command.  You have our gratitude." }
WordHunterWoW_QuestEN[25178] = { title = "Shipwreck Searching", description = "Hey handsome, welcome back!  You wouldn't mind running another errand, would you?  I'd be EVER so grateful...\n\nI hear you're headed off to the shore east of here.  The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use.\n\nSee you soon, beefcake!", objectives = "Obtain 4 sets of Gnomish Tools.", progress = "Has my knight in shining armor returned?", completion = "You really know how to treat a girl, you know that?  If you ever need anything..." }
WordHunterWoW_QuestEN[25179] = { title = "Loss Reduction", description = "You've got to help us.  The elementals... they're stronger than they look, and they come in waves.  They took us completely by surprise, and we were overcome.\n\nMany of my fellow grunts lay dying on the beach.  If you could save them... I would be grateful, as would Gar'Thok back in Razor Hill.", objectives = "Rescue 4 Injured Razor Hill Grunts.", completion = "I've already spoken with several orcs that have returned from the beach.  All of them told me that you were the one who saved them.\n\nYou've done a noble task today, <name>.  Lok'tar ogar!  For the Horde!" }
WordHunterWoW_QuestEN[25180] = { title = "Tablets of the Earth", description = "Some time ago, Brann sent King Magni an urgent message from Ulduar. He said he'd found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier. I was to meet him here and examine the tablets, but the courier is nowhere to be seen.\n\nMagni is worried, {name}. I haven't heard anything about the courier's arrival. Would you be willing to travel to Stormwind Harbor and see if he's arrived?", objectives = "Bring the Tablets of Earth to Advisor Belgrum in Ironforge.", progress = "Did you meet up with the courier?", completion = "Why would Twilight's Hammer take an interest in these tablets? Brann himself wrote that he hardly knows their significance, although he did mention something about becoming one with the earth. I will need to confer with my fellow Explorer's League scholars to decipher these as soon as possible.\n\nThank you, <name>. Without your aid, these tablets would've fallen into enemy hands." }
WordHunterWoW_QuestEN[25181] = { title = "Tablets of Fire", description = "I'm expecting the arrival of a courier traveling from Northrend. He's carrying a collection of ancient titan treasures, ones I'm hoping will shed light on my troubling visions. The shaman should've arrived on one of the recent zeppelin flights and I'm starting to get worried.\n\nHe was to meet me by the zeppelin tower southwest of Orgrimmar's gates, but I don't want to miss my audience with the warchief. Would you be willing to look for the courier and see what's delaying him?", objectives = "Bring the Tablets of Fire to Earthmender Norsala in Orgrimmar.", progress = "Did you meet up with the courier?", completion = "Why would Twilight's Hammer take an interest in these tablets? Their contents are a mystery to our most learned scholars and deciphering them will take some time. If Twilight's Hammer knows about these relics and desires them, what more are they plotting?\n\nWe are most fortunate that you protected them from capture, <name>." }
WordHunterWoW_QuestEN[25182] = { title = "Kill 'em All!", description = "I want to see some dead goblins, {name}! Just west of here you'll find a whole warren of those little insects burrowing into the mountain.\n\nLet's see to it that they're digging their grave.\n\nDestroy them. Lay waste to their whole grubby operation. They've sown their own demise in Bael'dun, {class}, and it is time to meet the reaper. ", objectives = "Kill 10 Frazzlecraz Miners at the Frazzlecraz Motherlode in Southern Barrens.", completion = "Dead? Good.\n\nLet word of this deed spread, and with it, terror.\n\nThe Horde will feel the consequences of their attack on Bael'dun, and they'll rue the day they ever crossed us, <name>." }
WordHunterWoW_QuestEN[25183] = { title = "...And Bury the Rest", description = "It's not enough to kill 'em - after Bael'dun, I want to give those goblins a taste of their own.\n\nGo into Frazzlecraz's mine and arm a pile of the explosives inside.\n\nAt the entrance to the mine you should see some sort of switch or plunger. Once the explosives are armed, use the plunger to blow that place sky-high. Put the fear in 'em, {class}! ", objectives = "Arm 6 Frazzlecraz Explosives in the Frazzlecraz Motherlode mine.", progress = "<The plunger has a number of jury-rigged wires leading into the mine.>", completion = "<The explosives are armed and ready!>" }
WordHunterWoW_QuestEN[25184] = { title = "Wild Mine Cart Ride", description = "All you have to do is jump in and speak with Assistant Greely when you get to the bottom.", objectives = "Use the Mine Cart to take a ride to the end of the line and then speak with Assistant Greely.", completion = "As we would say in the Tinker's Union, out of the heat-applied metallic cooking container and into the oxydizing, energetic mixture of reacting gases and solids!" }
WordHunterWoW_QuestEN[25185] = { title = "The Deed Is Done", description = "<You shield your eyes from the blast and the debris as the mine implodes onto itself.>\n\n<General Twinbraid will be pleased, but somehow you doubt it'll be enough to quench his thirst for vengeance.>", objectives = "Return to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "<Twinbraid nods as you describe the destruction of the mine, but his eyes still burn with rage.>\n\nVery nice work, <name>. I suppose there's some strategic value in depriving the Horde of those minerals, but I'd have done it anyway just to crush those little green monstrosities." }
WordHunterWoW_QuestEN[25186] = { title = "Futile Resistance", description = "{name}, I certainly don't want to deliver my report to Commander Singleton without at least a little bit of good news. We've got to wrestle control of these roads back from these Horde holdouts.\n\nFrom what we can gather, Kona Thunderwalk is the name of the ringleader. He's got a camp just north of here. A Stonetalon native, he knows these roads better than his own hide. If we can wipe him out, resistance from the west might vanish.\n\nFind and kill Kona Thunderwalk, then report to Commander Singleton!", objectives = "Slay Kona Thunderwalk on the border between Stonetalon and Southern Barrens.", completion = "So our supplies aren't getting through? Hmmm. Honor's Stand just gets more and more isolated.\n\nStill, the defeat of Thunderwalk should send a signal to our foes that we mean to stay. Thank you, <name>." }
WordHunterWoW_QuestEN[25187] = { title = "Lost in the Floods", description = "The recent cataclysmic events have done more than wash a few boats onto our shore, {class}.  The Southfury River has overflowed, and Durotar's entire western basin is now flooded.\n\nThere are still people out there.  I've been searching for a while, but haven't been able to find anything.  Would you mind using my telescope and taking a look for yourself?", objectives = "Use Thonk's Spyglass to search for survivors in Southfury Watershed.", progress = "What have you seen?", completion = "I see... so the trick is that you need to put the LITTLE end of the spyglass up to your eye.  I'll remember that piece of information." }
WordHunterWoW_QuestEN[25188] = { title = "Watershed Patrol", description = "My post is here on the tower, {name}, and I cannot leave it.  I need someone to go out there and help the people who are still trapped in the river's overflow.\n\nCan I count on you?", objectives = "Search the Southfury Watershed and help the people you saw in the spyglass.", completion = "I used that trick you taught me with the spyglass, and I watched you running around down there.  Quite impressive!\n\nHow'd you make the old woman fly, by the way?" }
WordHunterWoW_QuestEN[25189] = { title = "Spirits Be Praised", description = "Who are you?  What happened?\n\nI was alone in my hut, meditating, when...\n\nAhh, I remember now.  The spirits cried out, and the river swept in.  I'm lucky that you found me here.  I am old, and no longer physically able to endure the elements like this.  Will you lead me out of here?", objectives = "Escort Grandmatron Tekla to Raggaran.", completion = "My grandmother was a powerful shaman in her day.  I thought she had lost most of her powers in her old age, but I suppose some things stay with you forever." }
WordHunterWoW_QuestEN[25190] = { title = "Raggaran's Rage", description = "The quilboar are a stain on the land that not even the river can wash away.  They told me to evacuate, but I told them that my job was not yet done.\n\nHrrrraaagh!  I hate quilboar so much!  Will you help me kill them?", objectives = "Kill 4 Razormane Quilboar and 4 Razormane Scouts.", progress = "I hate quilboar!", completion = "<Raggaran appears to have calmed down a bit since your last encounter.>\n\nGood, good.  One step closer to eliminating those beady-eyed, basket-wearing, hog-nosed, two-toed...\n\n<Raggaran's anger is clearly rising again.>\n\n...hunchbacked, squealing, prickly... no-good... gnome-loving... GREEEAAAAGH!  Quilboar!" }
WordHunterWoW_QuestEN[25191] = { title = "Survey the Destruction", description = "I had heard of enormous seismic anomalies here in Kalimdor, but I had no inkling that the geological chaos would be so profound!\n\nI need an up-to-date survey of the destruction while I stay here to study the seismographic readings. Could you gather some data via my automated survey craft? I'll take care of all the flying.\n\nWhen the survey is complete, present the data to my colleague Horton Gimbleheart in Northwatch.", objectives = "Speak with Nibb Spindlegear at Honor's Stand to survey the cataclysm's destruction.", completion = "What, what!? Can't you see we're under attack here!\n\n<Gimbleheart snatches the readouts from the survey craft, then stuffs them haphazardly into a duffel bag.>\n\nYes sure of course I'll give Nibb's findings careful study. Later. From the safety of the Eastern Kingdoms, if I have any say about it!" }
WordHunterWoW_QuestEN[25192] = { title = "Raggaran's Fury", description = "I will not rest until they're defeated!  Slay them all!\n\n<Raggaran catches his breath.>\n\nTheir stinking lairs are to the north, or to the southwest!  ", objectives = "Kill 5 Razormane Dustrunners and 5 Razormane Battleguards.", progress = "Quilboar!  Kill them!", completion = "<Again, Raggaran appears calmer.>\n\nYou've done well, stranger.\n\nI'm sorry you had to see me like that.  Thank you for killing the quilboar, but maybe you should leave before I fly into another one of my rages." }
WordHunterWoW_QuestEN[25193] = { title = "Lost But Not Forgotten", description = "Today marks the anniversary of my son Kron's passing.  As long as I refused to admit it, I recognize now: Kron is not returning from his crocolisk hunt.\n\nI've been working on a project... something that will memorialize Kron's passion for the hunt.  It's a crocolisk-tooth necklace... rows and rows of teeth, suitable to be worn by only the bravest young orc.  I will place it on his grave.\n\nKron was brave, but he was not strong, like you.  Will you bring me the teeth for my necklace?", objectives = "Obtain 250 Crocolisk Teeth.", progress = "Kron will be remembered.", completion = "Thank you, <race>.  I will get to work on the necklace right away.\n\nBefore Kron died, I had made this for him to wear.  I have no use for it now, but perhaps you might." }
WordHunterWoW_QuestEN[25194] = { title = "Unbidden Visitors", description = "Don' worry, Zen'Taji's not in any trouble.  He just been studyin' what happens when the river overflows.\n\nYa see the big tall birds that stand on the riverbank?  Zen'Taji thinks they're in trouble.  The earthquake and the flood pushed the plainstriders over to this side of the water, but they can't fly back, and they're too scared to swim.\n\nThey'll die if they stay here.  Zen'Taji doesn't like violence, but maybe YOU can attack them and scare them over to the other side.  Yes?", objectives = "Attack 3 Wayward Plainstriders until they flee toward the Barrens.", progress = "Just beat on 'em, mon.  Trust Zen'Taji, they will run.  It is no big thing.", completion = "I love all the little animals, mon.  I love the big ones, too.  I just hate to see you hurt them like that... but it's for the best." }
WordHunterWoW_QuestEN[25195] = { title = "That's the End of That Raptor", description = "Many creatures died when the water came rushin' into the valley.  The raptors, however, thrived.  They're clever predators, and they've been living off the misfortune of the other creatures.\n\nOne of the raptors is particularly cruel.  He's killing the little animals and letting them rot in the water without even eating them!  He goes by the name of Screamslash, and if we're not careful, he could seriously disrupt the balance of nature.\n\nTravel north, slay him, and give his body back to nature.", objectives = "Slay the raptor called Screamslash.", progress = "The raptor has always been a quick adapter.", completion = "Something happened to Screamslash when the cataclysm hit, Zen'Taji thinks.  He wasn't always so violent and irrational.\n\nThank you for your help, <name>.  Zen'Taji gonna get back to his studying now." }
WordHunterWoW_QuestEN[25196] = { title = "The Dranosh'ar Blockade", description = "You should head north from here, {name}.  Speak with Gor the Enforcer at the Dranosh'ar Blockade.  He's been placed in charge of securing shipping lanes for Orgrimmar, and Skull Rock sits right next to his precious dock.  I'm certain he'll be interested in picking up where we left off.", objectives = "Report to Gor the Enforcer at the Dranosh'ar Blockade in Durotar.", completion = "You're the one who handled the Burning Blade to the south?  I've got ears in all kinds of places, boy, and word travels fast." }
WordHunterWoW_QuestEN[25197] = { title = "The Admiral Won't Back Down", description = "What? You want to stay here to fight? Typical {class}, wanting to stay and fight off the Horde while there's still a chance to run for it.\n\nLook, if you really want to save Northwatch, you should report to Admiral Aubrey in the tower behind me. He's keeping his ships here to fight, instead of ferrying us all away like I begged him to.\n\nNow if you'll excuse me, I've got to finish packing!", objectives = "Report to Admiral Aubrey at Northwatch Hold in Southern Barrens.", completion = "You've ventured all the way here from Honor's Stand? Excellent, we could use your experience here.\n\nThey may have breached the walls, but Northwatch isn't going down without a fight." }
WordHunterWoW_QuestEN[25198] = { title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", objectives = "Speak to Winnoa Pineforest at Vendetta Point in Southern Barrens.While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice. The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25199] = { title = "Basic Orders", description = "Hey! You look like you could give us a hand!\n\nIf you're willing to help our cause, we have to get you through training.  Gnome training is brutal and rigorous, so I hope you're ready.\n\nHead over to Drill Sergeant Steamcrank and he'll walk you through what you need to know.  Make sure you follow his orders when he gives them, or else you'll never make it\n\nI'm warning you though, it's tough over there.  Come back to see me, if you make it.", objectives = "Follow Drill Sergeant Steamcrank's cues and then report back to Captain Tread Sparknozzle." }
WordHunterWoW_QuestEN[25200] = { title = "Shredder Shutdown", description = "That no-good Trade Prince Gallywix somehow managed to stow the whole Steamwheedle Sharks footbomb team away on the yacht. I didn't even see any of them!\n\nNow he has them doing his dirty work here at the lumber yard. {name}, you're the guy who won the championship for us back home on Kezan. You've got to get rid of them!", objectives = "Slay 8 Steamwheedle Sharks.", progress = "Looks like you might need to tackle one or two more of those Sharks.", completion = "I can't say that I was ever much of a footbomb fan, but you're giving me an appreciation for the game!" }
WordHunterWoW_QuestEN[25201] = { title = "The Ultimate Footbomb Uniform", description = "Look, kid, I'm here to see to it that you've got a fighting chance at the end game. Thrall's going to need your help in the fight against the Trade Prince.\n\nGreely, Hobart, and I have a plan to put together the ultimate footbomb uniform for you so that you can win the game, but I'm going to need some things first.\n\nLucky for us, this lumber yard is sick with spare shredder parts. Now get out there and give me 110%!", objectives = "Collect 8 Shredder Spare Parts.", progress = "Let's see what you have there, <name>.", completion = "Yeah, these will do nicely. You did good, kid. I'll see to it that you get the best footbomb uniform ever made.\n\nIn the meantime, you've got other bombs to drop on the Trade Prince's lackeys." }
WordHunterWoW_QuestEN[25202] = { title = "The Fastest Way to His Heart", description = "Oh, man! You're never going to guess who's out on the oil platform to the north.\n\n<Izzy shakes her head sadly at you.>\n\nChip's out there, and he's working for the Trade Prince. That cold-hearted snake dropped you like a bad habit and now he's working for the other team. I even heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was my former definitely-real boyfriend, I'd rip his still-beating heart out of his chest.", objectives = "Rip the Still-Beating Heart from out of Chip Endale's chest.", progress = "What did you decide? Death or forgiveness?", completion = "He got just what he deserved. There, there, don't cry. You'll find someone else that'll treat you right.\n\nHere, let me take that... we wouldn't want people to think that you're crazy." }
WordHunterWoW_QuestEN[25203] = { title = "What Kind of Name is Chip, Anyway?", description = "Dude! You're never going to guess who's out on the oil platform to the north.\n\n<Ace shakes head in disbelief.>\n\nChip's out there, and he's working for the Trade Prince. That traitor's now working for the other team. But worse, I heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was shmoozin' up to my former definitely-real girlfriend, I'd do something about it.", objectives = "Slay Chip Endale.", completion = "There's no two ways about it... he got exactly what he deserved." }
WordHunterWoW_QuestEN[25204] = { title = "Release the Valves", description = "We have to stop Trade Prince Gallywix's oil supply and bring his machines to a grinding halt.\n\nWe're going to need you to go out to the KTC Oil Platform and release the valves to overload the coolant system. After you do that, head to the platform control panel on the platform and set it to blow.", objectives = "Release Valves #1 - 4.", progress = "You have not yet released all four of the valves. The coolant to the platform is still functioning within normal operating parameters.", completion = "All of the lights and indicators on the control panel are going crazy!" }
WordHunterWoW_QuestEN[25205] = { title = "The Wolf and The Kodo", description = "My \"associate\" here has some plans for you that I don't agree with.  His actions are hasty, uncontrolled, and irresponsible, and you may end up paying for them with your life.\n\nBefore you work with Gor, first listen to the tale that I have to tell.  It's a moralistic story - a fable - but I believe its lesson will prove valuable.  Speak to me when you are ready.", objectives = "Hear the moral of Shin Stonepillar's story.", progress = "Pay close attention to the meaning behind my words, child.", completion = "The moral of the story: hasty, lazy actions have ruinous results.  We mustn't take shortcuts... we must work for our rewards.  I've been trying to tell this story to the \"Enforcer\", but I fear his Hellscream-worshipping skull is a little bit too thick." }
WordHunterWoW_QuestEN[25206] = { title = "Ignoring the Warnings", description = "Ignore the shaman, soldier.  Certain powers-that-be within the Horde demand that I keep him with me, but I assure you, that Thrall-loving farseer truly sees no farther than the borders of this hut.\n\nElementals war against one another to the west of here.  I normally wouldn't mind, but I need that land clear to secure a broader shipping route to and from the Barrens.  The elementals are normally quite strong, but they are weakened by their attacks against one another.  Use this knowledge to destroy them.", objectives = "Destroy 12 Warring Elementals. You may slay either Furious Earthguards or Teeming Waterguards.", progress = "Elementals?  Pfuh!  No match for the power of the Horde.", completion = "See?  The shaman's tales are nothing but that... a youngling's bedtime stories.  The new Horde takes what it wants, and doesn't waste time with such frivolity.\n\nIf you get a chance, I recommend you tell Shin... and those like him... not to waste any more of your time." }
WordHunterWoW_QuestEN[25207] = { title = "Good-bye, Sweet Oil", description = "There is single big, red button on the platform control console. Clearly if ever there were a button to cause massive explosions, that is it!", objectives = "Press the Big Red Button to destroy the KTC Oil Platform.", completion = "I felt the heat from the explosions all the way over here!" }
WordHunterWoW_QuestEN[25208] = { title = "Tell Silvia", description = "It seems we've found an infestation far worse than the one we expected. Cho'gall is no doubt trying to use the Gordok to gain access to the remnants of Eldre'thalas within Dire Maul, full of the forbidden powers that brought the downfall of the Shen'dralar...\n\nI am rambling. Leave me, {name}. Tell Silvia of what you've learned. Whatever is occuring in Dire Maul must be stopped.", objectives = "Talk to Silvia at the Tower of Estulan.", completion = "You're back. What did Estulan say?" }
WordHunterWoW_QuestEN[25209] = { title = "The Gordunni Threat", description = "Within the High Wilderness to the south lay countless ancient ruins. It's there that the ancestors of the night elves fooled about with arcane magic, and it's there that the Gordunni ogres wander, searching for leftover scraps.\n\nYou'll notice the forest is completely destroyed in that area; the ogres leave only useless muck in their wake, depriving the Horde of valuable resources.\n\nGo and slay the Gordunni there, {name}. Secure the area for the Horde, and only for the Horde!", objectives = "Kill 16 Gordunni Ogres in the High Wilderness.", completion = "You have proven yourself to be a trustworthy and dependable ally, <name>." }
WordHunterWoW_QuestEN[25210] = { title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", objectives = "Collect 8 Infected Stag Antlers.", progress = "This is a sad task, <name>, but necessary.", completion = "I thank you, <name>. I will study the horns, but the situation has become even more dire since you left." }
WordHunterWoW_QuestEN[25211] = { title = "Cleaning Hovel", description = "Don't listen to Rharen. He's as addled as they come. It's his fault that the ale got captured!\n\nAnd what's more, I figure there's a bigger issue here than the ale being stolen. The fact that there's a bunch of orcs runnin' about Dun Algaz after all these years is ridiculous!\n\nTell you what, {class}. You head in there and be sure to drive as many orcs out of those ruins as you can. Dun Algaz isn't good for much anymore, but I'll be damned if we let them just sit in there.", objectives = "Kill 5 Dragonmaw Orcs in Dun Algaz.", progress = "C'mon now, put some effort into it! I can still smell 'em from here!", completion = "That'll show 'em!  Nice work!" }
WordHunterWoW_QuestEN[25212] = { title = "Vent Horizon", description = "We thought that we could wait for the radiation to subside around Gnomeregan, but it doesn't appear to be getting better.\n\nIf we want to take back our city, we need to make sure it's safe for our troops to enter.\n\nTake these Radiageigatrons, hop in 'Thunderflash' here,  and toss them at the ventilation shafts outside of Gnomeregan. They'll report the radiation levels directly to me.", objectives = "Use Pilot Muzzlesprock's flying machine to toss Radiageigatrons at the vents surrounding Gnomeregan." }
WordHunterWoW_QuestEN[25213] = { title = "The Slave Pits", description = "Sassy's over at the Slave Pits. She's there with the orcs getting ready to execute the final play on the Trade Prince.\n\n{name}, take the footbomb uniform up the road to the southwest and find her. I know she's going to want you to lead the charge!\n\nAck, I'm starting to talk like the coach now!", objectives = "Speak with Sassy Hardwrench at the Slave Pits.", completion = "I was wondering where you were!\n\nDon't worry, Hobart will get that footbomb uniform converted into the most Ultimate Footbomb Uniform ever!" }
WordHunterWoW_QuestEN[25214] = { title = "Escape Velocity", description = "We really don't have time to rescue those that are incompetent enough to get themselves captured over and over. Still, since I have some extra rockets leftover, this problem should be a snap.\n\nTake these single-stage booster rockets down into the Slave Pits to the north and put them on the cages.\n\nThe cage will lift off into orbit and those idiots will be freed.", objectives = "Use the Single-Stage Booster Rockets to launch the cages of 8 Kezan Citizens or Goblin Survivors.", progress = "You still have have more cages to liberate from their Azerothian bonds.", completion = "Oops. Well, what goes up must eventually come down." }
WordHunterWoW_QuestEN[25215] = { title = "A Distracting Scent", description = "Predators will smell these dead naga from nearly a mile away. Soon we'll find ourselves fighting just to get in and out of the cave. Care to help me clean up?\n\nJust over the ridge to the south is Glimmerdeep Gorge. If you drag the corpses from the eastern exit of the cave over there to the gorge and cut them loose, the wildlife will pick them clean before they hit the sea floor. Just steer clear of the sharks as much as you can.", objectives = "Drag 3 Dead Zin'jatar Raiders into the open water over Glimmerdeep Gorge to the south.", completion = "It shouldn't take long to cleanse the water. Thank you for your help." }
WordHunterWoW_QuestEN[25216] = { title = "The Great Sambino", description = "If you're heading down the trench, I'd like you to check in one of our novice members for me.\n\nHis name is Sam, but he's likely to embellish it a bit. He doesn't really understand how members of the Earthen Ring work, but he tries hard, so we try to give him the benefit of the doubt.\n\nDon't get too wrapped up in helping him with his crazy schemes. Just make sure he's still in one piece and let me know so that I can have a little peace of mind.", objectives = "Find \"Sam\" at the western end of Silver Tide Trench.", completion = "Another fan of the Great Sambino! Come all this way for an autograph perhaps? I'm far too busy to be signing anything... move along now." }
WordHunterWoW_QuestEN[25217] = { title = "Totem Modification", description = "Okay, I'll let you in on the real work, since you're looking at me so desperately.\n\nThis rock is untapped! It's probably richer than a trade prince during a great war! I need samples. More samples. Samples from everywhere!\n\nI've modified my earth totems to drill through the sand and store samples of the rock underneath. Go find a nice spot and plant one.\n\nThe shaking and rumbling will probably attract all the cute, curious wildlife, so maybe you can make some friends while you're at it.", objectives = "Plant one of Sambino's modified totems in the sand of Silver Tide Trench.", progress = "Bah! There's sand in my helmet. It itches!", completion = "Another sample. Brilliant! The rocky riches of the sea shall soon be mine!" }
WordHunterWoW_QuestEN[25218] = { title = "Undersea Inflation", description = "Fine! Fine. You argued me into it. You can help.\n\nI'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench.\n\nI brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too.\n\nI bet the crabs snatched it up... pinchy, greedy little things.", objectives = "Fill one of Sambino's Air Balloons and find his Lost Air Valve.", progress = "If only air weren't so darn floaty! Or if only those water breathing spells came with stylish helmets! Either would do nicely.", completion = "Ya know, I should have given you a weight belt so that you wouldn't just float away, air balloon and all. Lucky for me you came down here with armor and all! Hah!" }
WordHunterWoW_QuestEN[25219] = { title = "Don't be Shellfish", description = "I'm researching snails.\n\nYes. Snails. When you're done laughing, maybe you can help.\n\nI'm sure you noticed the gigantic shellfish across the ridge... well, I'm pretty sure there's something inside it. It has several points that can only be mouths or entrances of some kind, and I've seen those sifting snails squeezing in and out.\n\nI'm thinking that we might be able to use the snails to gain entrance ourselves. That's the theory anyway.", objectives = "Collect 10 Coilshell Sifters.", progress = "I know, this isn't the most desirable work, but can you really help but be curious about that shell? It's immense. There has to be something more to it.", completion = "Thank you. Seriously. If I would have had to endure another shipwreckee laughing at me, I swear I would have gored someone.\n\nI'll let you know if I come up with anything." }
WordHunterWoW_QuestEN[25220] = { title = "Slippery Threat", description = "Been attacked by any of the eels along the ridges yet? If not, you will. They are vicious, bloodthirsty little monsters. They don't seem to show much of any preference in what they're biting.\n\nIf you're going out into the valley, I'd appreciate if you thinned their population a bit. Not everyone here is as well equipped as you - we might not come back with just scratches.", objectives = "Kill 12 Spiketooth Eels.", completion = "Thank you, <class>. There are still much bigger predators we'll have to keep an eye out for, but this will at least give us a bit of peace of mind around the cave." }
WordHunterWoW_QuestEN[25221] = { title = "Rundown", description = "They're getting away!\n\nThese are the same naga that attacked the boats and carried away our friends. We cannot let them escape!\n\nTake these spears and run them down with that seahorse of yours... don't waste your time dismounting, just keep after them and kill all that you can with the spears.\n\nI will try to hunt down that Fathom-Lord. Meet me at the far end of the ledge when you're done.", objectives = "Use Toshe's Hunting Spear to run down 20 fleeing Zin'jatar naga.", progress = "Our other allies are in the cave below. Things look safe from here, but it's hard to be certain.\n\nDid you do as I asked of you?", completion = "Swift work. Very impressive.\n\nThat Fathom-Lord got away... I don't see him anywhere. He's most certainly the key to finding our captured friends.\n\nI will hunt him down. He cannot stay hidden for long." }
WordHunterWoW_QuestEN[25222] = { title = "Silver Tide Hollow", description = "Most of the other Earthen Ring that escaped the massacre on the boats have taken shelter in a cave a short swim down from the ridge. It's tucked midway up a huge rock formation, west of Nespirah, the gigantic shell on the horizon.  I need you to make sure they're okay. There's no telling how many naga might have attacked them as well.\n\nI'm going to hunt down that Fathom-Lord. I'll send word if I find the rock he's hiding under.", objectives = "Seek out Felora Firewreath in Silver Tide Hollow.", completion = "A friendly face! Welcome!\n\nVery kind of you to come check on us. We're fine. A naga scouting force did find us, but I'm pretty sure none escaped. We should be safe for now." }
WordHunterWoW_QuestEN[25223] = { title = "Trial By Fire", description = "I'd love to say that with the tides turning against us in Hyjal, every recruit helps our cause and so on... but to be perfectly blunt, most of you are nothing but a burden.\n\nIf I had a copper for every peasant who got too scared when the cataclysm hit and now wishes to join our side... well, let's just say I'd be a rich woman.\n\nFortunately we have checks in place to separate the wheat from the chaff.  Go and prove yourself to the fiery instructors below.  Hopefully you'll do better than the others.", objectives = "Defeat 8 Fiery Instructors.", completion = "I suppose your abilities are... suitable.  Color me impressed." }
WordHunterWoW_QuestEN[25224] = { title = "In Bloom", description = "It is customary for new recruits to be sent on a difficult or sometimes impossible task.  I was sent to obtain a black dragon's scale; last year's instructors demanded a feather from a phoenix.\n\nYour lot has it relatively easy.  Find me a handful of flame blossoms.\n\nThey grow around here in relative abundance.  Oh, right.  There will be a gigantic core hound roaming the fields to keep things interesting.  Do your best to avoid him.", objectives = "Obtain 5 Flame Blossoms.", progress = "Yes, Yshkaldamus?", completion = "So you managed to pass this part of the test without getting yourself eaten by Smolderos or being incinerated by the fire elementals?\n\nI suppose I should congratulate you on ascending the lowest rung of our ladder.\n\nWell... congratulations, recruit!" }
WordHunterWoW_QuestEN[25225] = { title = "Oil Change", description = "The lubricant in these shredders is useless. What we need is some good ol' Kajaro 0W Grade Oil!\n\nYou know what has that kind of oil? KTC Oil Bots! You know where you can find them? At the KTC Oil Platform to the northwest!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Kajaro 0W Grade Oil." }
WordHunterWoW_QuestEN[25226] = { title = "Kill Chip Endale Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[25227] = { title = "Thonk", description = "Oh, sweetie, I just remembered!\n\nMy VERY good friend Thonk works in the guard tower on that cliff, just to the northwest of Razor Hill.  He said something about a river overflowing, lots of work to be done, and so on.  I wasn't really paying attention... I was staring into those deep brown eyes of his.\n\nWhat, we can't see other people?", objectives = "Report to Thonk on the guard tower northwest of Razor Hill.", completion = "Gail sent you?  Did... did she say anything about me?" }
WordHunterWoW_QuestEN[25228] = { title = "Prophecies Of Doom", description = "Harbingers of doom are nothing new on the streets of Orgrimmar, but I'm worried about this latest batch. These people are organized and they've attracted a lot of attention in the Drag, where they seem to congregate.\n\nI've thought about rounding them up or otherwise disrupting their activities, but that will just drive them underground. We need to find out more about them. Would you go to the Drag, listen to what these doomsayers are spreading, and gather any literature you can find about their ideas?", objectives = "Listen to a speech given by a Doomsayer in the Drag and obtain copies of the pamphlets \"Elemental Fire for the Soul\", \"What Does 'The End of All Things' Mean for Me?\", and \"Finding Security and Comfort in a Doomed World\".", progress = "Well, did you find out anything?", completion = "<Torek reads over the scrolls you collected.>\n\nWhoever these people are, they really mean to gain a following. It looks like they're having quite a bit of success. They can't be allowed to incite the citizens of Ogrimmar to panic and hysteria. We must discourage interest in this group and learn as much about it as we can." }
WordHunterWoW_QuestEN[25229] = { title = "A Few Good Gnomes", description = "Our engineers have been working on getting our battle machines ready for our assault on Gnomeregan, but we're out of pilots!\n\nWe've developed a device called the Motivate-a-Tron, which prevents distraction from other sources and gives the gnome the courage to enlist.\n\nAfter motivating a few Gnome Citizens, lead them out to Captain Tread Sparknozzle out at Steelgrill's Depot, just south of Ironforge.\n\nOh, and be careful. The device is still a little experimental.\n", objectives = "Recruit Gnome Citizens from Tinker Town using the Motivate-a-Tron and lead them to Captain Tread Sparknozzle at Steelgrill's Depot." }
WordHunterWoW_QuestEN[25230] = { title = "More Than Illness", description = "We've found a brood of dragon whelps gathered off the road to the north, and they show the same illness as the stags.\n\nGreen dragons are not simple beasts of nature, but the very guardians of the wild. They are magical creatures, and to see them ill as well implies this is a dangerous threat.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", objectives = "Kill 10 Noxious Whelps.", completion = "These events disturb me greatly. My study of the antlers while you were gone has revealed little.\n\nWe must find some way to fix this..." }
WordHunterWoW_QuestEN[25231] = { title = "Southseas Scum", description = "Even now, Aggra and Kilag assault the docks to clear the way for Thrall to engage the Trade Prince. The plan is for you to assist in that attack, but first, we must ensure that Gallywix's Southsea mercenaries do not reinforce him.\n\nGo down into the Slave Pits and make certain that they don't!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 6 Southsea Mercenaries." }
WordHunterWoW_QuestEN[25232] = { title = "The Burning Blade", description = "I've been sent to investigate the presence of more Burning Blade agents here in Durotar.  To the northeast, you'll find a cave where the organization trains their new recruits.  I'm interested in what exactly they are teaching these neophytes.\n\nI only tell you this because you seem to be looking for work.  If you're interested in a little coin, sack the cave and return with their spellscrolls.\n\nThe cave is somewhat hidden: exit Razor Hill from the east, and follow the canyon's eastern ridge.", objectives = "Obtain 6 Burning Blade Spellscrolls from members of the Burning Blade in Dustwind Cave.", progress = "The scrolls, <name>, the scrolls!", completion = "This is quite interesting.  These rites aren't all that different from the spells which are taught to Horde warlocks.  This merits further investigation!" }
WordHunterWoW_QuestEN[25233] = { title = "End of the Supply Line", description = "Cho'gall's Twilight Proveditors swear a blood oath that they will get their supplies through to the front, pledging a pound of their own considerable flesh for every pound of supplies they fail to deliver. They would rather die than fail.\n\nSee to it that they do both.", objectives = "Slay 4 Twilight Proveditors at Wolf's Run in Hyjal.", completion = "Well done! The chaos we sow back here will be felt up and down the chain of command." }
WordHunterWoW_QuestEN[25234] = { title = "In the Rear With the Gear", description = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better.\n\nKill the slave drivers along the road to our south and nearby slaves should make a break for it.\n\nSearch the packs they leave behind for anything valuable, and destroy anything you can't carry.", objectives = "Collect 36 Twilight Supplies left behind from freed Twilight Slaves.", progress = "Have you created some havoc down there, <name>?", completion = "<Jadi kicks open one of the crates and picks up a curved dagger within. She immediately winces in pain.>\n\nAugh! Cursed - this metal is cursed - it bites!\n\n<When the dagger falls to the ground, it shatters, as if made of brittle glass.>\n\nWhat demented workmanship is this? <name>, I've never fought any foe like this before." }
WordHunterWoW_QuestEN[25235] = { title = "Vulgar Vul'Gol", description = "Hail, {class}. Care to lend a hand for the people of Darkshire?\n\nThere's a huge ogre mound just down the hill there. The Splinter Fist ogres usually keep to themselves, but they've got a bad habit of attacking travelers. Just the other day I saw one drag off a poor man's horse for food... he was lucky it left him behind!\n\nThe Night Watch wants to only risk its few members in the defense of more immediate threats, me included. But if you kill some of those ogres for me, I'll pay you for your deed.", objectives = "Kill 15 Splinter Fist Ogres of any kind.", progress = "If you'd rather just sit around camp and have a drink or two, that's fine too, I guess.", completion = "I saw you drop a few of them from here. Nice work.\n\nHere's your reward, on behalf of the Night Watch." }
WordHunterWoW_QuestEN[25236] = { title = "Thunder Down Under", description = "Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit.  The water that filled up the canyon to the southwest should do the trick.\n\nUnfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous.  I've got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope.  Are you my man, {name}?", objectives = "Attach a Mageweave Tether to 8 Drowned Thunder Lizards in Thunder Ridge.", completion = "The electricity was only one of the dangers.  If those carcasses rot too long under the water, that entire source becomes undrinkable.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[25237] = { title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nWeeks ago, in the glade to the west, I saw the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to; a source of nature's purity. We must gather them.", objectives = "Collect 7 Stonetears.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "Thank you once again, <name>. I will prepare these for our final task." }
WordHunterWoW_QuestEN[25238] = { title = "Strength Ring Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[25239] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "You seek to continue down the path of might?", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, <name>.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
WordHunterWoW_QuestEN[25240] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "You seek to continue down the path of might?", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, <name>.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
WordHunterWoW_QuestEN[25241] = { title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nIf the corruption has spread to them, they will lash out at the wildlife and their own kind, causing great destruction. You must destroy any corrupted giants you come across.", objectives = "Kill 7 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, <name>. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering." }
WordHunterWoW_QuestEN[25242] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "You seek to continue down the path of might?", progress = "You seek to continue down the path of might?", completion = "You are a true champion of our cause, <name>.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are might incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
WordHunterWoW_QuestEN[25243] = { title = "She Loves Me, She Loves Me NOT!", description = "Oh, sweetie! You're never going to guess who's down in the slave pits to the north.\n\n<Sassy shakes her head sadly at you.>\n\nCandy's down there, and she's working for the Trade Prince. She dropped you like a bad habit and now she's working for the other team. but it gets worse. Since you \"dealt\" with Chip, she's shmoozin' up to the Trade Prince!\n\nI don't know about you, but if she were my absolutely-not-fake girlfriend, I'd rip her fickle heart right out of her chest.", objectives = "Rip the Fickle Heart from out of Candy Cane's chest.", progress = "What did you decide to do, hon?", completion = "I'm sure she deserved it, <name>. She should never have betrayed you like that.\n\nIt gives me the shivers to think that she might have kissed that monster, the Trade Prince!" }
WordHunterWoW_QuestEN[25244] = { title = "What Kind of Name is Candy, Anyway?", description = "Can you believe that Candy Cane! You know up until you \"dealt\" with Chip, she was tryin' to start a partner brand with him. Now she's shmoozin' up to the Trade Prince!\n\nI just can't get over the fact that she betrayed you like that with your absolutely-not-fake boyfriend. Maybe you should head down into the Slave Pits and take care of her once and for all?", objectives = "Slay Candy Cane.", completion = "Serves her right for stealing your man in the first place." }
WordHunterWoW_QuestEN[25245] = { title = "Kill Candy Cane Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[25246] = { title = "A Change of Heart", description = "", objectives = "You seek to change the path you walk, <name>?", progress = "You seek to change the path you walk, <name>?", completion = "May you find what you're looking for, <brother/sister>." }
WordHunterWoW_QuestEN[25247] = { title = "A Change of Heart", description = "", objectives = "You seek to change the path you walk, <name>?", progress = "You seek to change the path you walk, <name>?", completion = "May you find what you're looking for, <brother/sister>." }
WordHunterWoW_QuestEN[25248] = { title = "A Change of Heart", description = "", objectives = "You seek to change the path you walk, <name>?", progress = "You seek to change the path you walk, <name>?", completion = "May you find what you're looking for, <brother/sister>." }
WordHunterWoW_QuestEN[25249] = { title = "A Change of Heart", description = "", objectives = "You seek to change the path you walk, <name>?", progress = "You seek to change the path you walk, <name>?", completion = "May you find what you're looking for, <brother/sister>." }
WordHunterWoW_QuestEN[25250] = { title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the east, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the World Tree itself. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave. May the Earth Mother watch over you.", objectives = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "The corruption has been stemmed! The forest can begin to heal now.\n\nMay you have the blessing of the Earth Mother wherever you go, friend." }
WordHunterWoW_QuestEN[25251] = { title = "Final Confrontation", description = "{name}, this is it! Thrall's down at the Gallywix Docks fighting the Trade Prince right now!\n\nYou gotta jump into your Ultimate Footbomb Uniform and get over there!", objectives = "Get into the Ultimate Footbomb Uniform and then deal with Trade Prince Gallywix.", progress = "<name>, you have to go deal with the Trade Prince before it's too late!", completion = "You did it! You did it!\n\nWe're saved, <name>!" }
WordHunterWoW_QuestEN[25252] = { title = "Rulers of Dire Maul", description = "Now that we've put the hurt on them at the ruins, it's time to attack the ogres in their own territory.\n\nThe Gordok are the \"upper class\" of the Gordunni clan, chosen to defend Dire Maul. They'll know we mean business once we start taking out their strongest members.\n\nNothing fancy here, {name}. Just get out there and crack some Gordok skulls.", objectives = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Excellent! Even these fools will soon know that to stand against the Horde means death." }
WordHunterWoW_QuestEN[25253] = { title = "Prophecies Of Doom", description = "Harbingers of doom are nothing new on the streets of Stormwind, but I'm worried about the most recent ones. They've set up shop all over Old Town and they seem well coordinated.\n\nI've thought about rounding them up or otherwise disrupting their activities, but that will just drive them underground. We need to find out as much as we can about them. Would you go to Old Town, hear what idea these doomsayers are spreading, and see if you can collect any of their leaflets?", objectives = "Listen to a speech given by a Doomsayer in Old Town and obtain copies of the pamphlets \"Elemental Fire for the Soul\", \"What Does 'The End of All Things' Mean for Me?\", and \"Finding Security and Comfort in a Doomed World\".", progress = "What did you encounter in Old Town?", completion = "<Anton reads over the scrolls you collected.>\n\nWhoever put these leaflets together knows how to get attention and from the state of things in Old Town, there's no lack of interest. We must act before they can build a significant following in the city. I fear they'll use their influence to spread panic throughout the city, paralyzing us.\n\nWe've got to get inside the organization and learn as much as possible." }
WordHunterWoW_QuestEN[25254] = { title = "Signs Of The Times", description = "We've got to do something to reduce interest in this doomsday cult, but I'm hesitant to take much action until we know more about who is behind this group.\n\nI've had my men place markers around heavily traveled areas in Orgrimmar. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers, but it's a first step in exposing this cult. The Horde has enough to deal with as it is, without people wilfully spreading lies too.", objectives = "Setup 5 Warning Posters around the Valley of Strength, the Drag, or the Valley of Honor.", completion = "Well done, <name>. Now we must focus our efforts on discovering more about this cult and freeing the people they've conned into joining." }
WordHunterWoW_QuestEN[25255] = { title = "Harrying the Hunters", description = "Twilight's Hammer has revealed itself as more than a mere cult. They're a war machine - a swarm of locusts moving up the mountain, devouring anything in their way.\n\nThe parts of the forest they're not setting ablaze are being scoured of life in order to feed the mortal cultists.\n\nWe've got to put a stop to the hunters canvassing Wolf's Run, not only to preserve what wildlife remains but to force the cult to march on empty stomachs. Look south of here, as well as up the road to the east.", objectives = "Kill 6 Twilight Hunters at Wolf's Run in Mount Hyjal.", completion = "Thank you, <name>. I worry that our actions here may be too little, too late, but nature always has a way of rebuilding itself that never ceases to amaze." }
WordHunterWoW_QuestEN[25256] = { title = "Sent for Help", description = "You, {race}, stop a minute.\n\nMy boss Spiketooth sent me to look for help and supplies.  You don't appear to be a merchant, but you can probably still help him out.  He's just to the southeast of here, next to the crashed cart.  Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", objectives = "Report to Spiketooth at Deadeye Shore in Durotar.", completion = "Vek'nag sent you?  Without telling you that I need wagon wheels, nails, and rations?  That idiot." }
WordHunterWoW_QuestEN[25257] = { title = "Ghislania", description = "I own a couple gladiators that I put into competitions around Kalimdor.  You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down.\n\nGhislania, that naga over there... she's lost her last three fights.  She could use a tune-up, or maybe just a little bit of thrashing.  Go challenge her, I'll bet even YOU are stronger than she is.", objectives = "Defeat Ghislania in combat.", completion = "I watched you fight out there.  How long you been a <class>?\n\nYou're alright, kid." }
WordHunterWoW_QuestEN[25258] = { title = "Griswold Hanniston", description = "Griswold, chained up over there on the cliffs, is my newest gladiator.  We found him just south of here, sniffing around with Northwatch soldiers.  I had my men nab him up, and now he works for me.\n\nHe looks tough enough, but he hasn't really been battle-tested yet.  Go pick a fight with him so I can see if he's worth keeping around.", objectives = "Defeat Griswold Hanniston in combat.", completion = "I'm at a crossroads now, <name>... you defeated him easily in combat, but then again, I did get him for free, and he's pretty cheap to feed.  Maybe we'll keep him around for a bit." }
WordHunterWoW_QuestEN[25259] = { title = "Gaur Icehorn", description = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot.  Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok.  He would have been put to the axe had I not been standing by, wallet in hand.\n\nGaur is my winningest gladiator, {class}.  I'll bet you a fist full of silver that you can't beat him.", objectives = "Defeat Gaur Icehorn in combat.", completion = "Fine, here's the money... but you'd better make yourself scarce before I reconsider my policy on keeping Horde slaves." }
WordHunterWoW_QuestEN[25260] = { title = "Fizzled", description = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar.  This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him.\n\nDarkclaw, however, did possess an orb that the Horde is interested in procuring.  Who knows why... I leave that to the warlocks.  All I know is that I need that orb.", objectives = "Obtain Fizzle's Orb from Fizzle Darkclaw in Thunder Ridge.", progress = "Run into any trouble on the way?", completion = "I ask for an orb, and you bring half of the goblin's arm with you?  I like the way you work.\n\nTell you what... you've already given me a hand.  Allow me to return the favor." }
WordHunterWoW_QuestEN[25261] = { title = "Margoz", description = "One of our more useful shaman, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the southeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", objectives = "Speak with Margoz.", completion = "Welcome, <name>.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a <class> of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed." }
WordHunterWoW_QuestEN[25262] = { title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", objectives = "Gather 6 Searing Collars from the cultists in Skull Rock.", progress = "Have you yet entered Skull Rock, <name>?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret..." }
WordHunterWoW_QuestEN[25263] = { title = "Arnak Fireblade", description = "The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Arnak Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Arnak in Orgrimmar in the Cleft of Shadow.", objectives = "Bring an Example Collar to Arnak Fireblade in Orgrimmar.", progress = "My most humble greetings, <class>.  How might I help my <race> brother today?", completion = "Ah, and where did you get this?  Good Margoz sent you to me, did he?\n\nWell, let me take a closer look..." }
WordHunterWoW_QuestEN[25264] = { title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade.\n\nYour role in this tale is nearly complete, {name}.  Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  Pass on to him this information.", objectives = "Speak with Ak'Zeloth at Far Watch Post in the Northern Barrens.", completion = "This is not news to me.  While I appreciate your efforts, the Burning Blade will have to wait.  We have other matters to which we must attend." }
WordHunterWoW_QuestEN[25265] = { title = "Victory!", description = "We just can't thank you enough for all that you've done. Now we can all get off of this island before it kills us!\n\nThrall is going to want to speak with you first, {name}. I'll rocket you over there.\n\nSee you on the ship!", objectives = "Speak with Thrall at the Gallywix Docks on the Lost Isles.", completion = "Lok'tar! Victory, <name>!" }
WordHunterWoW_QuestEN[25266] = { title = "Warchief's Emissary", description = "The goblins and the Horde have accomplished too much together to part ways now, {class}. I intend for the Bilgewater Cartel to become part of the Horde.\n\nI have something that I want you to deliver to the new warchief. Give this package to my Darkspear friend on the dock at Bladefist Bay in Durotar. She will help you to get into Orgrimmar safely.\n\nSpeak with Sassy Hardwrench on the ship when you are ready to set sail.\n\nUntil we meet again. Aka'Magosh, a blessing on you and yours, {name}!", objectives = "Deliver the Sealed Package to the Darkspear Loyalist on the docks at Bladefist Bay in Durotar.", progress = "What possible business could you have in Orgrimmar, <race>?", completion = "<The orc continues on in hushed tones.>\n\nI know who sent you. Did he give you something to deliver to me?" }
WordHunterWoW_QuestEN[25267] = { title = "Message for Saurfang", description = "<The Darkspear loyalist opens the package and reads the letter within. As she finishes the note from Thrall, a hint of a fanged smile appears on her face.>\n\nYa should take dis directly to Saurfang inside Orgrimmar. Be sure ta let him know dat de package be from Thrall.\n\nTake me raptor. Hurry, little one, dere be no time ta waste!", objectives = "Deliver the SI:7 Emblem to High Overlord Saurfang at Grommash Hold in Orgrimmar.", progress = "What is this, <race>? Your kind are not allowed inside Grommash Hold.\n\nLeave before I have to teach you your place.", completion = "Thrall had you deliver this?\n\n<The Warchief takes a step back, visibly shaken.>\n\nI understand the meaning of this all too well, <race>.\n\n\n\nThis smelly thing was caught unattended in the city and seems to recognize you.\n\nI have already put others of your kind to work in Azshara. Take it with you when you leave.\n\nFrom this day forward, you and your Bilgewater Cartel will serve the Horde!" }
WordHunterWoW_QuestEN[25268] = { title = "The Voice of Goldrinn", description = "Southwest of here lies the shrine of Goldrinn, a memorial erected in honor of the ancient wolf spirit and his contribution during the War of the Ancients.\n\nOur new worgen allies have been drawn to the memory of the wolf god - go figure! - and were in the process of cleaning up the shrine.\n\nI haven't heard anything from my contact, Ian Duran, in days. Can you fly down there and find him? I've got a bad feeling that Goldrinn's shrine is in trouble...", objectives = "Locate Ian Duran near the Shrine of Goldrinn in Hyjal.", completion = "You're here to rescue me, <class>? Thank you!\n\nNo, no, don't worry about the cage for now. My life isn't important. We've got to save the shrine, first." }
WordHunterWoW_QuestEN[25269] = { title = "The Voice of Lo'Gosh", description = "Have you heard of Lo'Gosh, the wolf ancient? In the Alliance tongue, he is known as \"Goldrinn.\"\n\nI don't need to tell you how important the wolf god has been to the Horde - his tenacity under adversity has been an inspiration to all of our disparate races.\n\nSouthwest of here, down in the valley, lies a shrine to Goldrinn. My friend Takrik Ragehowl was refurbishing the shrine when I stopped hearing from him. I fear the worst.\n\nPlease find Takrik and make sure the shrine is okay!", objectives = "Locate Takrik Ragehowl near the Shrine of Goldrinn in Hyjal.", completion = "Lok'tar, <class>! Don't worry about this cage - these animals will come to fear me before long.\n\nMy first priority is to clear this filth away from my beloved shrine." }
WordHunterWoW_QuestEN[25270] = { title = "Howling Mad", description = "The shrine has been taken, {name}. We need the tenacity of Lo'Gosh now more than ever.\n\nThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight's Hammer, howling with their own twisted religion. They seek to corrupt noble Lo'Gosh to fit their own warped pantheon.\n\nKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...", objectives = "Acquire 6 Polluted Incense.", progress = "These animals were once men, but they've turned into mindless beasts under the influence of the Twilight's hammer. Do not hesitate to slay them all.", completion = "<Takrik examines the incense.>\n\nDisgusting. This is like the incense we burn when we wish to commune with the spirits... but it's... befouled." }
WordHunterWoW_QuestEN[25271] = { title = "Goldrinn's Ferocity", description = "The beasts you see here, they're no longer my brothers from Gilneas. They've been corrupted by some kind of madness, and they've taken over the shrine.\n\nThey came when the Twilight's Hammer arrived in Hyjal, and they howl the name of some blasphemous mockery of our beloved Goldrinn. Forget about me - destroy these vandals before they continue to defile the shrine.\n\nAs you destroy them, look for the incense they carry and bring me some samples.", objectives = "Acquire 6 Polluted Incense.", progress = "Worgen like myself were drawn to the story of Goldrinn, his strength and wisdom. But these vandals - they worship a different aspect of the wolf god entirely.", completion = "<Ian examines the incense.>\n\nAs I suspected. These reagents bear the marks of the Twilight's Hammer. And here, the name \"Lycanthoth.\" I believe these are used in a summoning ritual..." }
WordHunterWoW_QuestEN[25272] = { title = "Lycanthoth the Corruptor", description = "The actions of these feral dogs are beginning to make sense. The Twilight's Hammer fears the power of the ancients. They do not want Lo'Gosh to return.\n\nSo they've summoned their own wolf god - a perversion of what once was. \"Lycanthoth,\" the corruptor.\n\n{name}, Lycanthoth is but a shadow of Lo'Gosh's power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo'Gosh!", objectives = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, <class>. Tell me your name.", completion = "You were brave to face down Lycanthoth, <name>. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, <class>. Climb onto my back, and let us show these beasts the true face of ferocity!" }
WordHunterWoW_QuestEN[25273] = { title = "Lycanthoth the Corruptor", description = "I think I understand what's happening here. The Twilight's Hammer fears that the ancients may someday rise up to oppose them. They'll do anything to stop the return of Goldrinn.\n\nThis \"Lycanthoth\" is a twisted version of our beloved wolf god, summoned by the Twilight's Hammer to replace him.\n\nBah! It is but a shadow of Goldrinn's power. {name}, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!", objectives = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, <class>. Tell me your name.", completion = "You were brave to face down Lycanthoth, <name>. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, <class>. Climb onto my back, and let us show these beasts the true face of ferocity!" }
WordHunterWoW_QuestEN[25274] = { title = "Signed in Blood", description = "You're here at last, {name}.  Just in time as well.\n\nNews of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer.\n\nIf you're to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.\n\nIf you're lucky, you'll be able to steal his recruitment papers.  Bring them back to me and we'll do our best to alter them.", objectives = "Lure a Twilight Recruit away from the group and take his Twilight Recruitment Papers.", progress = "Did you get the papers?", completion = "Excellent.  I'll do my best to alter these documents." }
WordHunterWoW_QuestEN[25275] = { title = "Report to the Labor Captain", description = "Your people are working on the terraforming of Azshara. The land will be remade in the image of the Horde so that all will know that Kalimdor belongs to us!\n\nGo north through the city. On the far side of the Valley of Honor you will find the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates.\n\nFor the Horde!!!", objectives = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", completion = "<name>? The <name>?!\n\n\n\nThe rumors are already flying about you. I don't know if I should be thankful or frightened that you're here. At least we don't have any volcanoes in Azshara!\n\nHonestly, I can't believe you're showing your face here... Trade Prince Gallywix has setup shop atop the mountain!" }
WordHunterWoW_QuestEN[25276] = { title = "Your New Identity", description = "There.  Not my best work, but certainly not my worst.  You will be known as \"{name}damus\" among the cultists.\n\nThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.\n\nGo to the proving grounds and show these to Condenna the Pitiless.  She's separating the wheat from the chaff.\n\nShow her what you're made of.", objectives = "Speak to Condenna the Pitiless at the Training Grounds in Hyjal.", progress = "You will address me with the respect I am due, recruit.", completion = "Yshkaldamus?  Let us hope your parents brought you into this world with more than just a ridiculous name." }
WordHunterWoW_QuestEN[25277] = { title = "Cleaning House", description = "We are well on our way to returning the shrine to its former glory, {name}. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar'gol.\n\nKill Gar'gol's minions and see if we can't send him packing.", objectives = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", progress = "How goes the ogre hunting?", completion = "Hah! So you really sent some heads rolling, did you?\n\nIt was said during the War of the Ancients that Lo'Gosh fought demons for ten days solid. Hopefully you weren't fighting that long..." }
WordHunterWoW_QuestEN[25278] = { title = "Cleaning House", description = "Thanks to your efforts, we may soon be able to return this shrine to its former glory. But first we've got to secure this valley. South of here, a group of ogres led by Gar'gol has set up camp in a stinking hovel.\n\nI wouldn't characterize Gar'gol as a 'threat' so much as an enormous fleshy obstacle thrown into our path to distract us from the real danger. Nonetheless, he and his goons will have to be dealt with.\n\nKill Gar'gol's minions in Goldrinn's name!", objectives = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", completion = "You really cleared that place out, didn't you? Well done!\n\nThe night elves once told me a story about how Goldrinn fought and killed a dreadlord, even as three others clung to his flanks, burning his flesh. I wonder if you or I will ever have the strength to do the same?" }
WordHunterWoW_QuestEN[25279] = { title = "The Shrine Reclaimed", description = "Yes, {name}. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.", objectives = "Return to Takrik Ragehowl at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "<name>, it was incredible! For a fleeting moment I saw Lo'Gosh through the trees - a creature of both fury and light. My cage collapsed and the vandals melted like wax under the kiss of his claws, their screams and howls echoing through the valley... Was that your work?" }
WordHunterWoW_QuestEN[25280] = { title = "The Shrine Reclaimed", description = "Yes {name}, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.", objectives = "Return to Ian Duran at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "<name>, it was astounding! Goldrinn himself appeared to free us, his white fur bright like the summer moon. Our cages collapsed and the vandals melted like wax under the kiss of his claws. He was beautiful, <name>. Beautiful!" }
WordHunterWoW_QuestEN[25281] = { title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", objectives = "Use the Enchanted Conch Shell to rescue 6 Drowning Soldiers.", progress = "Were you able to rescue the soldiers, <race>?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen soldiers.\n\nWe'll need every hand if we are to survive here." }
WordHunterWoW_QuestEN[25282] = { title = "Signs Of The Times", description = "We've got to do something to reduce interest in this doomsday cult, but I'm hesitant to take much action until we know more about who is behind this group.\n\nI've had my men place markers around heavily traveled areas of the city. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers, but it's a first step in exposing this cult. The king already has enough enemies without his own people turning against him.", objectives = "Set up 5 Warning Posters in the Trade District, Cathedral Square, Old Town, or Mage Quarter of Stormwind.", completion = "Well done, <name>. Now we must focus our efforts on discovering more about this cult and freeing the people they've conned into joining." }
WordHunterWoW_QuestEN[25283] = { title = "Prepping the Speech", description = "High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I can't tell which draft is good and which ones just stink.\n\nCould you try some of them out on some of the local gnome residents?  This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.\n\nLet me know which one works, okay?", objectives = "Use the Gnomish Playback Device in front of Ozzie Togglevolt north of Kharanos, Milli Featherwhistle at Steelgrill Depot and Tog Rustsprocket outside the Kharanos Inn. Return to Toby Ziegear when all the speeches have been given." }
WordHunterWoW_QuestEN[25284] = { title = "Feeding the Fear", description = "Our resources are limited, {class}, but that doesn't mean we can't make some trouble down below. Use the ropes here to sneak down the hillside, then slay the human prison wardens.\n\nKilling a couple scrawny guards won't turn the tide of battle, but  imagine the fear and chaos we'll reap as the humans discover the mutilated bodies...\n\n<Holgom grins a yellowed grin, his eyes glinting.>", objectives = "Kill 5 Tower Wardens. Use the ropes beside Holgom to quickly move in and out of Honor's Stand.", completion = "Good, good. It'll take them many sleepless nights to figure out where we came from and where we disappeared to after the kills..." }
WordHunterWoW_QuestEN[25285] = { title = "In and Out", description = "We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!\n\nFirst, we need to make sure that once you're in, you can get out.  In battle, if you think your tank is going to explode, get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up, and them along with it.\n\nWell, I've upgraded this tank with an ejection seat.  Try it out for me, will ya?", objectives = "Test out the ejection system in the Ejector Mechano-Tank." }
WordHunterWoW_QuestEN[25286] = { title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!", objectives = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.\n\nProvided item:" }
WordHunterWoW_QuestEN[25287] = { title = "Words for Delivery", description = "All right, soldier. Time to prove your worth!\n\nTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.\n\nGo! Now!", objectives = "Ride 'Thunderflash' from Steelgrill Depot to High Tinker Mekkatorque and deliver Toby's speech." }
WordHunterWoW_QuestEN[25288] = { title = "Infiltrating The Cult", description = "The streets of Orgrimmar are wild with rumors about the cult's origins and practices. There's only one way to know the truth about this group, <name>. You're going to join them.\n\nApproach one of the Doomsayers in the Drag and tell them you wish to join their group. With any luck, they will give you instructions to introduce yourself to one of the group's leaders and tell you where the group is hiding. Don any clothing given to you by the doomsayer; you'll need it to gain entry to the group's hideout.", objectives = "Go to Orgrimmar's Drag and speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the cult, then put on your Recruit's Robe.", completion = "Welcome, friend. We are honored that you have decided to embrace the truth and join us. Come, there will be more time to talk later and you have much to learn." }
WordHunterWoW_QuestEN[25289] = { title = "One Step Forward...", description = "With the ejection system working, I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!\n\nI want you to check out the servos on the left leg, the right leg and the Automatic Evasive Maneuver system.\n\nThis is easy stuff, so it shouldn't take too long.", objectives = "Test the Scuttling Mechano-Tank's maneuverability." }
WordHunterWoW_QuestEN[25290] = { title = "Infiltrating the Cult", description = "It's getting difficult to keep the cultists out of the public eye and rumors are spreading across the city. I want you to join the cult and learn as much as you can.\n\nApproach one of the doomsayers in Old Town and tell them you wish to join their group. The doomsayer will likely give you clothing and instructions to meet with other cultists in one of the group's hideouts. Follow those instructions, <name>. It's the only way to gain their confidence.", objectives = "Go to Stormwind's Old Town and either speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the doomsday cult, then equip the Doomsday Recruit's Robe you receive.", completion = "Welcome, friend. We are honored that you have decided to embrace the truth and join us. Come, there will be more time to talk later and you have much to learn." }
WordHunterWoW_QuestEN[25291] = { title = "Twilight Training", description = "You've proven you're worthy of at least participating in our most basic training.\n\nYou'll find one of our settlements east of here.  Speak to instructor Mylva there.", objectives = "Speak to Instructor Mylva in Hyjal.", completion = "You think you're ready for the next step then, Yshkaldamus?\n\nLet's see what you're capable of." }
WordHunterWoW_QuestEN[25292] = { title = "Next of Kin", description = "<Nato pulls you aside and speaks in a whisper.>\n\n{name}, I have removed the bullet from Gann's chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.\n\nTake this. It's the bullet that killed him. His family will want to know what became of their youngest warrior.\n\nSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.", objectives = "Take the Dwarven Slug to Alto Stonespire at Brackenwall Village in Dustwallow Marsh.", progress = "Hello, <class>. You look to be caked in dust instead of mud. I take it you've ventured here from the Barrens?", completion = "<Alto clenches the bullet in his palm as you tell your story.>\n\nGann? Dead? I ... I should've known. His temper... his recklessness. I knew someday it would get the better of him.\n\nBut it sounds as though you've already gifted him with vengeance. Thank you, <name>!\n\nTurn your attention now to Dustwallow. If the Alliance finishes their cursed road through here, all your victories in the Barrens may have been for nothing." }
WordHunterWoW_QuestEN[25293] = { title = "The Missing", description = "Aside from the disturbances and the paranoia spread by the cult, we've been inundated with reports of missing people. Mothers, fathers, brothers, and sisters have seemingly disappeared, but I have a feeling that they can be found in one of the cult's compounds outside the city. If I give you the names of some of the missing people, would you try to locate them in the cultist camp at the Jaggedswine Farm south of Orgrimmar? To blend in, you'll need to get a robe from one of the doomsayers in the Drag.", objectives = "While wearing your Cult Disguise, speak to Cultist Kagarn, Cultist Agtar, Cultist Tokka, and Cultist Rokaga at the Jaggedswine Farm in Durotar.", completion = "So you found them? Why did the missing men and women not return with you?\n\n<You tell the blood guard about the responses you received.>\n\nWe cannot compel them to change their minds and return to their families. I will let the families know that the relatives have been found and that they are safe. After this cult is broken up, they will likely return to their normal lives." }
WordHunterWoW_QuestEN[25294] = { title = "Walking the Dog", description = "Hmmmphh.... it seems they'll let anyone in these days.\n\nVery well.  You doubtlessly became acquainted with Smolderos in the proving grounds.\n\nWell, I've been entrusted with the care of one of his pups.  Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.\n\nCollect meat from the basilisks around the area and feed them to him.", objectives = "Collect and feed 5 pieces of Charred Basilisk Meat to the Spawn of Smolderos.", completion = "Excellent.  This little pup will grow to be strong and merciless like his father." }
WordHunterWoW_QuestEN[25295] = { title = "Press Fire", description = "Safety systems, online!  Motor functions, functioning!  Now all we need is to make sure that the guns will fire.\n\nThis shouldn't be too hard, {name}.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.", objectives = "Test out the Shooting Mechano-Tank weapon systems on the nearby targets." }
WordHunterWoW_QuestEN[25296] = { title = "Gather the Intelligence", description = "It's me, {name}, Ortell!\n\nDon't look directly at the outhouse... you'll give away my position.\n\nEverything's going according to plan then?  Excellent!\n\nI'm going to need you to obtain some intelligence while you're here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.", objectives = "Obtain the Twilight Communique and the Hyjal Battleplans.", progress = "Did you get the documents, <name>?", completion = "Excellent job, <name>.  Or should I say: \"<name>\"damus?\n\nGive me a minute to read these." }
WordHunterWoW_QuestEN[25297] = { title = "From the Mouth of Madness", description = "I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel.\n\nOne sip of that draught should knock some sense into the brainwashed slaves!", objectives = "Gather up Stonebloom, Bitterblossom, and a Darkflame Ember.", progress = "<The cauldron burbles, filled with a disgusting liquid.>", completion = "<You dump out the current contents of the cauldron, instantly killing the surrounding plant life.>\n\n<The draught you brew in its place boils chunky and reeks of rotted cabbage. You turn your head aside and bottle it up.>" }
WordHunterWoW_QuestEN[25298] = { title = "Free Your Mind, the Rest Follows", description = "<Rio said that the draught would not remain effective for long.>\n\n<You'd better hurry into the hovel and administer it to as many Twilight Servitors as you can find.>", objectives = "Speak with 8 Twilight Servitors to administer the draught and rescue them.", progress = "Did the draught work?", completion = "Excellent! Let's hope the damage wasn't permanent.\n\nJudging by the poor victims still in camp here, the Twilight's Hammer really messed with their heads." }
WordHunterWoW_QuestEN[25299] = { title = "Mental Training: Speaking the Truth to Power", description = "You might think you're ready to receive the knowledge we're to impart on you.  But you are not.\n\nThink of your mind as a box inside a series of other boxes.\n\nEach step of our training will open one of those boxes, until you are ready to achieve direct communion with the elements.\n\nTake the Core of Ascension and answer all questions it asks of you, truthfully.  Failing to do so could be... fatal.", objectives = "Use the Orb of Ascension and answer 10 answers correctly.", progress = "You've returned.", completion = "You've succeeded, Yshkaldamus.  You're ready for the next step." }
WordHunterWoW_QuestEN[25300] = { title = "The Eye of Twilight", description = "The ogre clan across the lake is led by Gar'gol. I use the term loosely; Gar'gol has the intelligence of raw beef.\n\nSo far as I can tell, Gar'gol is taking orders from a magical instrument: \"The Eye of Twilight.\" He follows its commands unquestioningly.\n\nIf we can sabotage the eye, we can cause unimaginable havoc.\n\nGo to Gar'gol's hovel and seek out the Eye of Twilight near the entrance. Study it. Find a way to subvert it. Ah, marvelous chaos...", objectives = "Seek out the Eye of Twilight near the entrance to Gar'gol's Hovel in Hyjal.", completion = "<You approach the Eye of Twilight. As your fingertips graze its luminescent surface, you are aware of a malignant presence peering back at you, searching your soul.>\n\n<Instinctively, you draw back.>" }
WordHunterWoW_QuestEN[25301] = { title = "Mastering Puppets", description = "<During your brief communion with the Eye, you felt that its power source lay deep within the hovel. You felt the weight of a powerful tome, binding together four elements.>\n\n<Mastering the Eye will require you to search the hovel for this tome.>", objectives = "Locate the Twilight Apocrypha inside of Gar'gol's Hovel in Hyjal.", completion = "<A heavy tome, bound in flesh, lies open on the table.>\n\n<The language - pictographic and scrawled in rust-colored ink - is undecipherable, but notes and translations are tucked within several pages. This must be what you're looking for.>" }
WordHunterWoW_QuestEN[25302] = { title = "Remnants of Battle", description = "A great battle took place here. Mixed with the naga skeletons are that of some sort of large humanoids. This might be interesting news to XXX.", objectives = "Bring the Broken Shard to XXX at XXX.A great battle took place here. Mixed with the naga skeletons are that of some sort of large humanoids. This might be interesting news to XXX." }
WordHunterWoW_QuestEN[25303] = { title = "Elementary!", description = "<You can't read the text, but diagrams seem to indicate that the devices around you should be activated in a set order.>\n\n<One passage of the Apocrypha has been translated to modern text:>\n\n   In the beginning was shadow eternal.\n   Hate blazed forth, and FIRE was born.\n   Wounds scabbed, and so begat EARTH.\n   Cries of anguish birthed howling WIND.\n   Wherein the skies wept seas of TEARS.\n      We live in the shadow,\n      The world we know\n   Built of rage, hurt, anguish and sorrow.", objectives = "Activate the four nearby elemental crucibles in the correct order to take control of the Eye of Twilight.", progress = "<You pour over the Apocrypha, trying to make sense of it all.>", completion = "<Flush with the energies of the captured elementals, you stand before the Twilight Apocrypha. The pages turn of their own accord.>\n\n<Suddenly, you see what the Eye sees. It is yours to command!>" }
WordHunterWoW_QuestEN[25304] = { title = "The Battle of Sardor", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Find our Ancient of War along the shore. He will take you to the front lines, where Tambre leads the offensive.", objectives = "Speak with Tambre on Sardor Isle.", completion = "These foul things will be driven back into the sea. I hope you're ready." }
WordHunterWoW_QuestEN[25305] = { title = "Never Look Back", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Speak with Sentinel Ranadae to join our forces at Sardor. Slay the naga, and make sure whichever foul snake they take orders from is killed as well.", objectives = "Kill 10 Hatecrest Naga and slay their leader." }
WordHunterWoW_QuestEN[25306] = { title = "You're In The Army Gnow!", description = "[ph] War!", objectives = "[ph] Log Description" }
WordHunterWoW_QuestEN[25307] = { title = "Eavesdropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[25308] = { title = "Seeds of Discord", description = "According to the intelligence you acquired, there is major friction between the ogres and non-ogres in the cult.\n\nHigh Cultist Azennios and the ogre mage Karr'gonn are meeting at the Seat of the Chosen in an attempt to ease the conflict.\n\nThere is an outhouse like this one at the Seat of the Chosen.  Go there and put on this ogre disguise.  Find a way to kill Azennios while he's in this mission of peace.\n\nWe must exploit this division as much as we can!", objectives = "Distract Karr'gonn and slay Dark Cultist Azennios at the Seat of the Chosen in Hyjal.", progress = "Is it done yet, <name>?", completion = "Excellent job, <name>!  You've outdone yourself this time." }
WordHunterWoW_QuestEN[25309] = { title = "Spiritual Training: Mercy is for the Weak", description = "You've made it this far.  Others haven't.\n\nGo to Doom's  Vigil, just north of here.  We've rounded up all the... failures.  I want you to help take care of them.  It'll be good for your spiritual growth.\n\nIf this cold-blooded act gives you trouble, think of it as their second chance.  Should any of them manage to kill you... well, they'll take your spot.", objectives = "Slay 5 Failed Supplicants at Doom's Vigil.", completion = "You're on the fast-track to success.  Let us hope you don't ruin your track record with such silly notions as compassion and humaneness.\n\nCome, then.  Let us discuss your future." }
WordHunterWoW_QuestEN[25310] = { title = "The Greater of Two Evils", description = "We took Darkwhisper Gorge from the demons of the Burning Legion by force.  We've held on to our territory pretty well so far, with one exception.\n\nWe recently lost the Gates of Sothann to a pit lord and his army.  We cannot allow this to stand.\n\nUse this talisman when you're near him.  You'll gain the powers of a flame ascendant temporarily.  Make it count.", objectives = "Use the Talisman of Flame Ascendancy and slay Garnoth, Fist of the Legion, at the Gates of Sothann in Hyjal.", completion = "Excellent work, Yshkaldamus.  We must show all would-be competitors that we are not ones to give up easily." }
WordHunterWoW_QuestEN[25311] = { title = "Twilight Territory", description = "The demons of the Burning Legion think they can just walk up here and take whatever territory they want.  Sure -- the territory was previously theirs, but that's beside the point.\n\nWe'll teach them not to cross the Twilight's Hammer.\n\nHead to the Gates of Sothann and wipe out the contingent of Horrorguards that roam the area.", objectives = "Slay 10 Horrorguards at the Gates of Sothann in Hyjal.", completion = "Sharp as always.  You do not disappoint me." }
WordHunterWoW_QuestEN[25312] = { title = "Return to Duskwhisper", description = "<You force your own image into the Eye, manipulating it to give the ogres different orders. As you do so, you feel another presence within the Eye, probing you, seeking out a weakness. A distant being fumes with rage. You've made some enemies today!>\n\n<Your work here is done, and the ogres will be friendly to you. Return to Royce Duskwhisper at the Shrine of Goldrinn and let him know what you've accomplished.>", objectives = "Return to Royce Duskwhisper at the Shrine of Goldrinn in Hyjal.", completion = "Hello, yes? What? You? Oh, you're one of the ones I sent after the Eye of Twilight, aren't you?\n\nGood work, very good. I suppose that's a valuable lesson:\n\nNever to take orders from a big purple ball." }
WordHunterWoW_QuestEN[25313] = { title = "The Defector", description = "Stay your hand!  Please, I beg you!\n\nI'm only here because of a girl.  Her words were so sweet... but now I realize the madness behind them.\n\nTake this envelope.  It has information that'll score you some points with your superiors.\n\nThe guards are distracted... I can make a run for it.  Please.  I don't want to die!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Incriminating Envelope to Elementalist Ortell at the Outhouse at the Forge of Supplication in Hyjal.Stay your hand!  Please, I beg you!\n\nI'm only here because of a girl. Her words were so sweet... but now I realize the madness behind them.\n\nTake this envelope. It has information that'll score you some points with your superiors.\n\nThe guards are distracted... I can make a run for it. Please. I don't want to die!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25314] = { title = "Speech Writing for Dummies", description = "Listen, {name}.  I found out what they're doing with Jarod Shadowsong.  He's scheduled to be sacrificed by the ogres of the Twilight's Hammer as part of this year's initiation.\n\nI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.\n\nWe need you to deliver that speech if we're to free Jarod.  Don't worry -- I'll write you some cue cards -- just make sure Okrog has an \"accident\" as he leaves the Seat of the Chosen.", objectives = "Kill Okrog outside the Seat of the Chosen in Hyjal.", progress = "Well, <name>?", completion = "Excellent work, <name>.  Our plan's almost come together." }
WordHunterWoW_QuestEN[25315] = { title = "Graduation Speech", description = "You're finally ready, {name}damus.\n\nI am so proud of you and all you've accomplished.\n\nToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.\n\nRemember, {name}damus.  It'll be important to read your audience's emotions and use words that best address those emotions.", objectives = "Use the Initiation Podium at Doom's Vigil to successfully deliver the Graduation Speech.", progress = "Have you come to finish me off?\n\nNo... you appear to be... sane.", completion = "You.  You're clearly not with them.\n\nAn ally then?" }
WordHunterWoW_QuestEN[25316] = { title = "As Hyjal Burns", description = "{name}!  We've heard much about you and your previous accomplishments.\n\nIt is good that you've come here just as Azeroth finds itself in a time of great need.\n\nDeathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.\n\nAronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", objectives = "Fly to Hyjal using Aronus and speak to Ysera once you're there.", completion = "<Ysera appears to be in some sort of trance.>" }
WordHunterWoW_QuestEN[25317] = { title = "Protect the World Tree", description = "<Ysera's eyes look distant, as if not fully acknowledging you.>\n\nI feel it as well, {class}. Ragnaros has arrived.\n\nWe must defeat his minions before he can join them and lend them his strength.\n\nSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.\n\nI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.", objectives = "Speak to Malfurion Stormrage at the Tranquil Grove in Mount Hyjal.", completion = "You've arrived just in time, <name>." }
WordHunterWoW_QuestEN[25318] = { title = "Twilight Battle Plans", description = "", objectives = "" }
WordHunterWoW_QuestEN[25319] = { title = "War on the Twilight's Hammer", description = "Make no mistake about this, {name}.  The outcome of this war will determine the very survival of our world as we know it.\n\nThe Twilight's Hammer has become more powerful than ever with Deathwing's return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.\n\nIt is time we beat back the enemy.  It is time we crushed the Twilight's Hammer.", objectives = "Kill 4 Twilight Flamecallers and 10 Twilight Vanquishers.", completion = "You've done well, <name>.  But I fear the battle is far from over." }
WordHunterWoW_QuestEN[25320] = { title = "The Captured Scout", description = "I've heard about you, {name}, and the news you brought from the south.  The battle has reached a stalemate.\n\nOne that I fear is about to be broken by the Firelord's reawakening.\n\nThat is unless we tip the scales in our favor in some way.\n\nThere is a scout that was captured by the Twilight's Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.", objectives = "Find Scout Larandia at the Twilight Command Post in Mount Hyjal.", completion = "Help has arrived at last!" }
WordHunterWoW_QuestEN[25321] = { title = "Twilight Captivity", description = "I'd been scouting behind enemy lines for nearly a day when they caught me.\n\nThis attack on our frontlines is not what it appears, {name}.\n\nI'll give you all the details, but first let's find a way to get me out of here.\n\nOnly the overseers carry keys to these cages.\n\nFrom what I recall, they're in the middle of the crater, in the thick of it.\n\nSee if you can get a key off of one of them.", objectives = "Obtain a Twilight Overseer's Key at the Twilight Command Post in Hyjal.", progress = "The key, <name>.  Did you get it?", completion = "I am thankful, <name>.  I will deliver my findings to our people." }
WordHunterWoW_QuestEN[25322] = { title = "Fiery Inscriptions", description = "The medallion is unlike any you've seen before.  Its runes appear to glow in conjunction with the near fire elementals.\n\nPerhaps you should tell Hamuul Runetotem about this.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Hamuul Runetotem in Hyjal." }
WordHunterWoW_QuestEN[25323] = { title = "Flamebreaker", description = "The large elementals that besiege us are not a singular entity.\n\nThey are an amalgamation of lesser spirits bound together by the Twilight's Hammer cultists' magic.\n\nThe rebuilt flameseer's staff will give us enough power to shatter its bonds.\n\nDestroy the smaller elementals once you've broken up the more dangerous large ones.", objectives = "Kill 30 Unbound Flame Spirits.", progress = "Is it done, <name>?", completion = "Well done, <name>.  This will help us turn the tide against the enemy." }
WordHunterWoW_QuestEN[25324] = { title = "A Prisoner of Interest", description = "The Twilight's Hammer wants to free Fandral Staghelm?\n\nMalfurion suspected his corruption ran deep... this just cements it.\n\nAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.\n\nI've a plan, {name}.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.\n\nSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.  ", objectives = "Speak to Captain Saynna Stormrunner at the Barrow Dens in Hyjal.", completion = "The dragon might be right.  The Twilight's Hammer has breached our security and this is our most dangerous prisoner." }
WordHunterWoW_QuestEN[25325] = { title = "Through the Dream", description = "Alysra's plan might be necessary, {name}.  I don't know how much longer we can hold off the cultists.\n\nFandral Staghelm is bound by powerful spells.  He won't be able to escape you, even inside the Emerald Dream.\n\nBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.\n\nTake Fandral to the surface and hand him to Alysra.  Let us hope he's more secure in Moonglade than he is here.", objectives = "Deliver Arch Druid Fandral Staghelm to Alysra at the entrance of the Barrow Dens in Hyjal.", progress = "Is Staghelm with you, <name>?", completion = "You did well, <name>.  I will take Fandral to Moonglade myself.\n\nHis prison will be far enough from the battlefront there." }
WordHunterWoW_QuestEN[25326] = { title = "Block Their Retreat", description = "", objectives = "" }
WordHunterWoW_QuestEN[25327] = { title = "Awakening", description = "", objectives = "" }
WordHunterWoW_QuestEN[25328] = { title = "Gar'gol's Gotta Go", description = "<Kristoff cranes his neck, trying to look you in the eye.>\n\nListen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both.\n\nThey've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!\n\n<Kristoff flails his limbs, helplessly.>", objectives = "Get the Rusted Skull Key from Gar'gol's Personal Treasure Chest.", progress = "Key? Now? Please?", completion = "<Kristoff reaches down to snatch the key.>\n\nIt's about time!\n\n<He squirms in his bonds, trying to reach the padlock behind his back.>\n\n...Can I get a little help here?" }
WordHunterWoW_QuestEN[25329] = { title = "Might of the Stonemaul", description = "So the Twilight's Hammer thinks it can just raise its own army of ogres here? In the middle of Horde territory? \n\nWe'll see about that.\n\nOgres only respect one thing: strength. I want you to lead the assault on Cho'gall's sermon, {name}. Throw wide the doors of Dire Maul, leap into the arena, and cut down his attendants.", objectives = "Disrupt Cho'Gall's Twilight Sermon.", completion = "We've done it! Cho'gall himself has been utterly humiliated by you. His minions are dead, the Gordok are scattered, and now all will know the might of the Horde! Lok'tar, <name>. You've more than earned your reward." }
WordHunterWoW_QuestEN[25330] = { title = "Waste of Flesh", description = "Look at these fools.  Half of them won't even make it past this trial.\n\nThey are not worthy of ascending into our inner circles.  But perhaps... perhaps they are worthy of menial service.\n\nTake this gem and utilize its power to save some of the less competent supplicants.  Those who have no chance of succeeding.  Those already on fire, preferably.", objectives = "Use the Frostgale Crystal to extinguish the flames on 4 Immolated Supplicants.", progress = "Did you find suitable servants for me, Growlnardamus?", completion = "Excellent work, Yshkaldamus.  I'm having the servants you chose for me briefed on their new duties." }
WordHunterWoW_QuestEN[25331] = { title = "Grandma's Cat", description = "Right!  About the evacuation, dear.\n\nI just cannot leave without my cat.  He's an adorable orange tabby.\n\nChance's favorite spot to play is a broken down cart near an arbor northeast of here.\n\nBring him here and we'll be on our way.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Grandma Wahl at the Wahl cottage wants you to retrieve Chance the Cat." }
WordHunterWoW_QuestEN[25332] = { title = "Get Me Outta Here!", description = "<You reach up to unfasten Kristoff's bonds.>\n\nGood! Make a break for the exit, and I'll follow.\n\nIf we get separated, check back here to make sure I haven't been recaptured.", objectives = "Escort Kristoff out of Gar'gol's Hovel.", completion = "Kristoff, Kristoff... Oh yes, I remember now. I recall sending him on what amounted to a suicide mission.\n\nHe survived? I suppose that means he failed.\n\nStill, you deserve at least some coin for the trouble." }
WordHunterWoW_QuestEN[25333] = { title = "Might of the Sentinels", description = "The Twilight's Hammer? Here?\n\nThis is far more serious than I expected. We've got to put a stop to this. I don't know if I'm ready to lead such an offensive, but I'm not about to let my fears get in the way of what needs to be done!\n\nI will rally our forces from Feathermoon Stronghold. Head to Dire Maul, make your way to the arena, and disrupt Cho'gall's activities; we will launch our attack during the confusion.", objectives = "Disrupt Cho'Gall's Twilight Sermon.", completion = "Welcome back from the battle! The Twilight's Hammer have been disgraced in the eyes of the Gordunni, and driven from Feralas.\n\nWe've shown the glory of the Alliance in full force today! Be proud!" }
WordHunterWoW_QuestEN[25334] = { title = "The Looming Threat", description = "Can ya feel how angry the elements be? They be wantin' to attack us and consume us even as we just arrive. We need ta calm dem, but that kinda wisdom only comes from knowin' what's riling them up in da first place.\n\nCome sit with me by da fire. Let yaself get lost in da flames... let ya spirit peer into the true threat.", objectives = "Speak to Farseer Gadra to enter your Spirit Trance.", progress = "Lose yaself in the dancin' flames. Come with me, deeper into Vashj'ir, so that we be knowin' the face of our enemy.", completion = "We'd all suspected da naga, but I knew nothin' of the Twilight Cult bein' beneath the waves. Somehow dey are corruptin' and pervertin' the elements, makin' demselves into dese horrors.\n\nWe goin' ta have to be fightin' both of dese threats to stand a chance of bringin' peace ta Vashj'ir. We don't have da men ta do that yet.\n\nCome, <class>, we got much ta do." }
WordHunterWoW_QuestEN[25335] = { title = "Natural Materials", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache." }
WordHunterWoW_QuestEN[25336] = { title = "Testing the Vessel", description = "Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft.\n\nThis vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", objectives = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.", progress = "Did you get the beast muisek?", completion = "As my master told me...\n\nUpon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, <name>, prevents the muisek from escaping. Now we may use it as we please!" }
WordHunterWoW_QuestEN[25337] = { title = "Hippogryph Muisek", description = "The next step is hippogryphs.\n\nAs Master Uzer'i always said, hippogryphs have been loyal companions to the night elves for many years, an' their spirits are loyal and steadfast.\n\nI don't think they'll miss a few, and I don't care if they do. We need the muisek of 10 frayfeather hippogyphs in the wilderness to the south.", objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", progress = "Were you able to capture the hippogryphs?", completion = "Master always said \"after killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature.\" This is dangerous stuff. Thanks for helping me with my studies." }
WordHunterWoW_QuestEN[25338] = { title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, <name>. This is my first time working with treant muisek..." }
WordHunterWoW_QuestEN[25339] = { title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge. ", objectives = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", completion = "Thank you, <name>. You have put an old tauren's mind at peace." }
WordHunterWoW_QuestEN[25340] = { title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", objectives = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart, I will keep it in memory of what you did here for me, <name>. Thank you." }
WordHunterWoW_QuestEN[25341] = { title = "The Gordunni Orb", description = "While you're down there cracking skulls...\n\nI've gotten reports that make me think these ogres may be more than the usual lumbering threat. The Warlocks among them have been seen carrying orbs, possibly items of empowerment.\n\nIt would be easy to dismiss them as crude trinkets, but I need to make sure we're not surprised. Bring me back one of these orbs.", objectives = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Well done. Let me have a look at this." }
WordHunterWoW_QuestEN[25342] = { title = "Talk to Swar'jan", description = "We're lucky and unlucky here, grunt. Lucky that I had you bother to bring this back, and unlucky that my suspicions turned out to hold water. This thing's full of corrupted stench.\n\nIt's far too new to be something fished out of the ruins, either. Someone is supplying these ogres, and we need to know who before this becomes a situation.\n\nGet that filthy thing upstairs to Swar'jan, the warlock on top of the guard tower. He's good for a few ideas; I'd listen to his suggestions, if I were you.", objectives = "Deliver the Gordunni Orb to Swar'jan in Stonemaul Hold.", progress = "Yes?", completion = "What've you got for me here? You said the Gordunni had this?\n\nDisgusting..." }
WordHunterWoW_QuestEN[25343] = { title = "The Master's Plan", description = "You're fitting in well here, <name>, but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.\n\nAs you know, this world is ending and the unprepared will die painful deaths.\n\nWe have been given a gift, an opportunity to become something greater and more powerful. Overseer Golbaz is preparing a ritual before the altar at the eastern end of the farm. Wait there for him, and learn more of your new brothers and sisters.", objectives = "Learn more about the cult's plans at the altar in the eastern part of the Jaggedswine Farm.", completion = "Now that you understand the master's plan, you must prepare yourself to play your part." }
WordHunterWoW_QuestEN[25344] = { title = "Ogre Abduction", description = "There's no way the Gordunni made these. They're being supplied. Someone is giving them gifts of power, and we need to find out who.\n\nThe upper-class Gordok that guard Dire Maul will know more about this. Orhan is no doubt having you thin their numbers, but I'll need one alive.\n\nTake the orb back. It's similar to a Soulstone, so I've made some...adjustments. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", objectives = "Use the Modified Soulstone to capture a Gordok ogre.", completion = "Ahh, I can feel the whelp in there. Let's get him out and ask him some questions..." }
WordHunterWoW_QuestEN[25345] = { title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, <name>. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me." }
WordHunterWoW_QuestEN[25346] = { title = "Mountain Giant Muisek", description = "The mountain giants left the mountains to aid the night elves when the Burning Legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", objectives = "Kill 7 Mountain Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, <name>. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish." }
WordHunterWoW_QuestEN[25347] = { title = "The Doomsday Plan", description = "The first batch of elemental devices are ready. Your task will be to conceal them inside the city of Orgrimmar. The devices will unleash their fire elementals at the proper time. Don't worry, <name>, you'll be safely away before that happens.\n\nDo not do anything that would draw attention to yourself.\n\n<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Blood Guard Torek was hoping you'd uncover. You should probably bring the devices to him.>", objectives = "Take the Elemental Devices to Blood Guard Torek in Orgrimmar's Valley of Strength.", progress = "You've returned at last. I was beginning to think that you'd taken up with the cultists for good.", completion = "<You hand Blood Guard Torek the devices that the overseer gave you, explaining the cult's plans. Torek's eyes go wide.>\n\nCho'Gall is in charge of the cult? There can be no question then, this is the work of the Twilight's Hammer! You won't be the only one they've sent into the city to deploy these devices." }
WordHunterWoW_QuestEN[25348] = { title = "Thwarting Twilight's Hammer", description = "You can't have been the only person sent into Orgrimmar to deploy those devices containing fire elementals. We have to find and disable the rest of the devices before they set their captive elementals free and burn down the city.\n\nAre you familiar enough with the devices to destroy them? You need to break them open before the fire elementals inside have had time to reach full strength. They should be easy to defeat if you open the devices early. The cultists have probably put them all over the city.", objectives = "Break Elemental Devices to release their elementals. You must defeat 5 Raging Fire Elementals.", completion = "Excellent work, <name>. Twilight's Hammer will think twice before trying to turn our own people against us again. I'm sure I'm not the only one troubled by just how many citizens were taken in by their message. Times aren't exactly easy, but if you have no honor or loyalty, you have nothing." }
WordHunterWoW_QuestEN[25349] = { title = "Twisted Sisters", description = "I have heard of your battle against the corrupted dragons, {name}, and I thank you for your courage... but I have disturbing news.\n\nThe dryads of the forest, though allies of the Night Elves, have always passed us by in peace. But they have become cruel and twisted, attacking any who wander the eastern wilds.\n\nI fear for the safety of the refugees here, {name}. Please, put a stop to these twisted dryads.", objectives = "Kill 7 Corrupted Dryads.", completion = "I thank you, <name>, but the tale of your hunt troubles me. There should not be so many.\n\nThe sickness is still spreading..." }
WordHunterWoW_QuestEN[25350] = { title = "The Lost Apprentice", description = "If you have a moment, {class}...\n\nOne of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen.  I had spoken with him earlier about an amulet that is concealed within those ruins.  Now, I fear that he may have run off in search of it, because of me...\n\nEstulan has forbidden us to pursue him. If you go there, could you please look for him?", objectives = "Look for the Lost Apprentice in the Darkmist Ruins.", completion = "<The apprentice's body is cold. He has been dead for a while.>" }
WordHunterWoW_QuestEN[25351] = { title = "Alert Our Leaders", description = "You have successfully defended Orgrimmar from the threat posed by this Twilight's Hammer cult, <name>, and without shedding the blood of our own people. Our enemy will not rest for long. I cannot imagine that Cho'Gall will accept defeat so easily.\n\nGarrosh Hellscream is a well-known hero of the Horde and he will know how to deal with this matter. Go to the Valley of Wisdom and speak to him in Grommash Hold. Tell young Hellscream that our enemies have shown themselves and we must be prepared for their return.", objectives = "Speak with Garrosh Hellscream at Grommash Hold in Orgrimmar's Valley of Wisdom.", completion = "<The warchief listens as you tell of your investigation into the Twilight's Hammer plot to destroy Orgrimmar.>\n\nYou are a dutiful member of the Horde, <name>. You have done well in bringing this news to me. I will personally see to it that our enemies get what they deserve!" }
WordHunterWoW_QuestEN[25352] = { title = "Sweeping the Shelf", description = "Wonderful work in the hovel, {name}. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.\n\nBut we've been on the defensive too long: it's time to foil the Twilight's Hammer directly.\n\nFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they're preparing to unleash!", objectives = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", completion = "You should've seen the battle from here! Bodies were falling off of the cliff! Spectacular!" }
WordHunterWoW_QuestEN[25353] = { title = "Lightning in a Bottle", description = "When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don't understand what the ancient has planned...\n\n{name}, go to the Lightning Ledge. Twilight's Hammer has been running experiments with something called a \"Lightning Channel.\" Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind... ", objectives = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, <class>. You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, <name>. You will be my champion, and carry my vengeance to realms where I cannot tread..." }
WordHunterWoW_QuestEN[25354] = { title = "Sweeping the Shelf", description = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.\n\nSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!\n\nFly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, {name}, slay their creations and hurl their bodies from the mountainside!", objectives = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", completion = "Impressive, <name>. Very impressive.\n\nYou embody all of the strength of the Wolf Ancient, and possess the wisdom to use your powers well. I salute you." }
WordHunterWoW_QuestEN[25355] = { title = "Lightning in a Bottle", description = "Lo'Gosh granted me a vision while you were in the hovel, {name}. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo'Gosh feels this is of utmost importance. We must not fail the ancient.\n\nUpon the Lightning Ledge, Twilight's Hammer has been experimenting with devices they call \"Lightning Channels.\"\n\nInvestigate one of these channels, then use this totem to summon the Spirit of Lo'Gosh and learn what the ancient is planning...", objectives = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, <class>. You fight well! You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, <name>. You will be my champion, and carry my vengeance to realms where I cannot tread..." }
WordHunterWoW_QuestEN[25356] = { title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. Shyn will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "Borrow a wind rider from Shyn and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", completion = "Jawn sent you? Good! We need your help, now!" }
WordHunterWoW_QuestEN[25357] = { title = "Buy Us Some Time", description = "So many good men have been lost today. Without you, that number would be even higher.\n\nYou have our gratitude.\n\nIf what the shaman says is true, then there is no time to spare. The naga are scouring these waters looking for survivors.\n\nWe are not yet ready to fight. You must buy us time to make preparations. Find the naga that hunt us and delay their efforts.", objectives = "Slay 8 Zin'jatar Raiders.", progress = "Have you given the naga something to think about, <class>?", completion = "Let's hope your efforts prove to be enough of a diversion..." }
WordHunterWoW_QuestEN[25358] = { title = "Nerve Tonic", description = "How am I feelin', you ask?\n\nWell, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good!\n\nMy nerves are gettin' the best of me, to be honest.\n\nIf you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", objectives = "Mack wants you to collect 5 Sunken Cargo in Kelp'thar Forest.", progress = "Were ya able to grab some supplies, <race>?", completion = "I trust we both know what's been going on inside these crates...\n\nThat's right... ferrrmenntation! Here y'are. My personal secret recipe.\n\nYou wouldn't get this from any other guy!" }
WordHunterWoW_QuestEN[25359] = { title = "Toshe's Vengeance", description = "You met Toshe back in Damplight Cavern, didn't you? He followed some of the fleeing naga to a set of ruins to the east and then sent for help.\n\nFind Toshe at the ruins as soon as you can. If you find out anything about what the naga want, please let us know.", objectives = "Speak to Toshe Chaosrender at the Ruins of Thelserai Temple.", completion = "I remember you. You were there when they attacked us back in the cave.\n\nGood to have you with me, <class>. Ready for a little vengeance?" }
WordHunterWoW_QuestEN[25360] = { title = "Crabby Patrons", description = "These crabs are not friendly. Not. Friendly.\n\nSam's endless drilling is riling them up. I know from experience that there's no stopping Sam, so let's look into the other side of things, shall we?", objectives = "Kill 10 Green Sand Crabs.", progress = "Careful. They pinch.", completion = "Does everything down here only come in jumbo size? Oooh! That's a thought. Maybe there are some hunky sea goblins around here somewhere.\n\nThanks, by the way." }
WordHunterWoW_QuestEN[25361] = { title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with the gorgeous wings I want are west of Camp Mojache.", objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, <class>. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, <class>! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, <class>." }
WordHunterWoW_QuestEN[25362] = { title = "A Grim Discovery", description = "The Grimtotem clan! Those gutless traitors are still lurking around here, eh...\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", progress = "Take my words seriously, <class>, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "Traitors to the Horde and traitors to their own people...\n\nI guess they're not all bad. They'll make fine drinking flasks." }
WordHunterWoW_QuestEN[25363] = { title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh <name>?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, <name>.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, <name>, that might settle things once and for all against them..." }
WordHunterWoW_QuestEN[25364] = { title = "Alpha Strike", description = "Gnolls are unfortunately as resilient as they are brutish and stupid. I have driven back the gnolls time after time from our camp, and it is only our chieftain's mercy that prevents them from being wiped out entirely.\n\nOver the years, it has fallen into a dance of strength and dominance. When their numbers surge and they threaten the camp, the alphas, the strongest gnolls, must be slain.\n\nThis will drive them back into the forest, and leave us is peace until they forget their lessons.", objectives = "Kill 5 Woodpaw Alphas.", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, <name>.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup, I want to find out what is causing it." }
WordHunterWoW_QuestEN[25365] = { title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity. If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans. They have to have something--their attacks have been too coordinated to be done without them. Find them, and return to me when you have them.", objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs..." }
WordHunterWoW_QuestEN[25366] = { title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", progress = "Welcome back <name> - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is." }
WordHunterWoW_QuestEN[25367] = { title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", objectives = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "How goes the hunt, <name>?  Are you here to report your success?", completion = "Well done, <class>.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated." }
WordHunterWoW_QuestEN[25368] = { title = "Verinias the Twisted", description = "The other spirits and I are bound here by a cruel demon named Verinias. He is our captor, a twisted, mindless beast who devours our souls over millennia.\n\nThe lure of the souls and arcane magic you've brought me should let you draw him out. Take this condensed essence to the dead tree at the far north of the ruins. Use it to lure Verinias and slay him, that I may finally be free...", objectives = "Defeat Verinias the Twisted.", progress = "You must free me from Verinias's grasp! I can grant the amulet to you if you do...", completion = "I'm free...finally! Oh, it feels so good to be free...\n\nOh, you saw, didn't you?" }
WordHunterWoW_QuestEN[25369] = { title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", objectives = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, <class>... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, <name>.  Well done." }
WordHunterWoW_QuestEN[25370] = { title = "Inciting the Elements", description = "This is no mere natural occurrence, {name}.  There must be a twilight presence behind our lines that we haven't accounted for.\n\nIt's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.\n\nSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions.\n\nFeed them the juniper berries that grow nearby to gain their trust.", objectives = "Feed Juniper Berries to the Faerie Dragons and slay 4 Twilight Inciters.", progress = "Back already, <name>?", completion = "You've done well, <name>.  We cannot allow the Twilight's Hammer spies this close to the world tree!" }
WordHunterWoW_QuestEN[25371] = { title = "The Abyssal Ride", description = "If you are going to be making it anywhere in this kelp forest, we need to get you a reliable mount. I think I've come up with a better plan than the sea turtle, and it's not far.\n\nTie off a lure at the rope just west of us, and then mount the seahorse that it will attract.\n\nBe warned, you may need to work hard to break the beast.", objectives = "Lure and subdue an Abyssal Seahorse.", progress = "The grace of these creatures is astounding. They will make the perfect mounts.", completion = "Amazing! You look exhausted. She must have really made you work for it.\n\nLife should be a lot easier down here going forward with a mount that swift at your beckoning. Congratulations, <name>!" }
WordHunterWoW_QuestEN[25372] = { title = "Aessina's Miracle", description = "<The finger-like branches of one of Nordu's burning limbs part, revealing an untouched, glimmering seed.>\n\nThis is the Heart of the Forest. The seed of life.\n\nTake this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old.\n\nThank you, {race}. My time is done.", objectives = "Take the Heart of the Forest to Hamuul Runetotem at the Grove of Aessina in Mount Hyjal.", progress = "I am at my wit's end, <name>! Aessina is silent.\n\nHave you found something? What is this?", completion = "This is the key, <name>! With the seedlings you collected for me earlier, the animals you've saved from around Hyjal, and the Heart of the Forest you've just discovered, we can rejuvenate this land right from under the feet of Twilight's Hammer. Imagine their astonishment to see their work undone, as life triumphs over chaos...\n\nI will begin the ceremony at once!" }
WordHunterWoW_QuestEN[25373] = { title = "The Hilltop Threat", description = "I am proud of Mojache's reputation as a safe haven in the wilds of Feralas, but the camp faces many threats. The Gordunni ogres gather nearby in the northern foothills, claiming their territory and despoiling the wildlife.\n\nWith the arrival of our brothers and sisters seeking shelter, I cannot let them linger any more. Go north and drive the ogres out.", objectives = "Kill 5 Gordunni Hillguards.", completion = "I thank you, <name>, but there is more work to be done to keep the camp safe. Listen further." }
WordHunterWoW_QuestEN[25374] = { title = "Sasquatch Sighting", description = "You may have seen this with your own eyes, but my longrunners have reported something disturbing to me. The gordunni in the hills have captured an enormous sasquatch from the wilds.\n\nI don't know how long it's been held, but ogres are not ones for hobbies. I fear they plan to unleash the tortured beast on Camp Mojache.\n\nReturn to the deepest corner of the Gordunni Outpost and slay the sasquatch, {name}.", objectives = "Kill Bigfist.", completion = "I will be able to rest easy now, <name>. You've saved our camp from a terrible menace." }
WordHunterWoW_QuestEN[25375] = { title = "Taming The Tamers", description = "The gordunni are not known to tame animals. If they're learning, this is cause for alarm. While the sasquatch they've tamed may be the major threat to our camp, the gordunni who captured him should be dealt with as well. If left, they may simply capture another.\n\nKill the gordunni tamers, and make sure the ogres know their efforts will not be tolerated!", objectives = "Kill 6 Gordunni Tamers.", completion = "Good, good. Let's hope the ogres are at least smart enough to realize we're sending a message!" }
WordHunterWoW_QuestEN[25376] = { title = "Gordunni Cobalt", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 12 samples of Gordunni Cobalt." }
WordHunterWoW_QuestEN[25377] = { title = "The Horde's Hoard", description = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks.\n\nScanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck.\n\nYou cannot help but wonder what the scaly, serpentine figure on the map might represent....", objectives = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest.", progress = "This slightly encrusted lock might still be functional.", completion = "You've discovered lost treasure!\n\nYour mind reels at the thought of what else might be hidden in the depths of the sea." }
WordHunterWoW_QuestEN[25378] = { title = "Ysondre's Call", description = "The dragons of nature... Heed her call, {name}. Do not linger here. Her request for your aid is both a great honor and an omen of terrible danger.\n\nThe place she spoke of is called the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; you will find a small shrine at the top.\n\nAll of Feralas may rest upon your shoulders. May the Earth Mother watch over you.", objectives = "Speak with Ysondre at the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, <class>, but I've ran from him long enough. Taerar must be stopped." }
WordHunterWoW_QuestEN[25379] = { title = "Taerar's Fall", description = "Emeriss and Lethon are gone. It's only us left now. I can hide from this no longer. All I did while a part of that brood...all the suffering I've caused...must be repaid today.\n\nI am still weak, {name}. I cannot assume my true form even if I dare try. But I will still stand beside you in battle.\n\nIf you are prepared, I will call Taerar to us. He will be unable to resist the temptation of revisiting corruption upon me.", objectives = "Defeat Taerar.", completion = "It is done.\n\nThis land that has suffered so much can rest now." }
WordHunterWoW_QuestEN[25380] = { title = "Spreading The Word", description = "Welcome to the farm, <name>. Everyone here works to earn <his/her> keep. For some, that means caring for the animals. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.\n\nTake this board. It bears a short message about our beliefs. While wearing the board, visit the eastern and western zeppelin towers outside Orgrimmar's gates, as well as the town square of Razor Hill, to the south.", objectives = "While wearing your Doomsday Message, visit the East Zeppelin Tower, the West Zeppelin Tower, and the town square of Razor Hill.", completion = "Well done, <name>. It might be awkward at first, but you will get used to advocating our beliefs in public. It is one way of remembering our obligation to bring the truth to others. We must save as many as we can." }
WordHunterWoW_QuestEN[25381] = { title = "Fighting Fire With ... Anything", description = "The inferno raging up ahead marks the front line between us and the forces of the Fire Lord. The fire elementals unleashed here are unlike any I've ever encountered.\n\nCan you help us stem the tide of destruction? Slay the raging firestorms... before they engulf Aessina's Grove and erase all hope of someday reclaiming this mountain!", objectives = "Slay 10 Raging Firestorms within the Inferno.", completion = "Thank you, <name>. You've given us the opportunity to try to reclaim the upper hand." }
WordHunterWoW_QuestEN[25382] = { title = "Disrupting the Rituals", description = "The firestorms up ahead are unbound elementals in the purest form - something I didn't think could exist outside their own plane. Only very skilled summoners could unleash something like this.\n\n{name}, head into the Inferno and seek out Twilight Inferno Lords. They've got to be summoning in reinforcements as we speak. Silence them... For good!", objectives = "Slay 6 Twilight Inferno Lords within the Inferno.", completion = "Dead? Good!\n\nBut it seems there's still so much to be done... fires to quench... and the soil to heal...\n\nI hope you'll stay close and help us reclaim Hyjal!" }
WordHunterWoW_QuestEN[25383] = { title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", objectives = "Speak to Chief Spirithorn in Camp Mojache.", completion = "You are truly blessed by the Earth Mother, <name>, to have the honor of fighting with the guardians of nature, and to also survive it.\n\nKnow that you have kept safe every living soul in this camp, and possibly this entire forest. Take these gifts with my deepest thanks." }
WordHunterWoW_QuestEN[25384] = { title = "Raw Materials", description = "Thank you, {class}. We owe you our lives.\n\nBut if we're ever to see the surface again, we'll have to fight our way out of here. That means I'm going to need to craft some weapons and armor.\n\nBefore you found me, I saw a soldier eaten by one of those orca up there.\n\nI'll wager that if you cut a few of them open, you'll find plenty of scrap metal for me to work with.\n\nIf you don't want to swim up to them, I bet you could lure one down to you with some entrails...", objectives = "Samir wants you to collect 3 Rent Scrap Metal from Frenzied Orca in the Kelp Forest.\n\nYou can lure an orca using Pincer Entrails from Clacksnap Pincers." }
WordHunterWoW_QuestEN[25385] = { title = "Save the Wee Animals", description = "Help us, {class}! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet.\n\nThey have wet little noses!\n\nIf you don't save them, I don't want to even THINK about it.\n\n<She slaps her palms over her eyes.>\n\nI'm not thinking!", objectives = "Go into the Inferno and rescue any combination of 10 Panicked Bunnies or Terrified Squirrels.", progress = "Did you save the wee animals? And their wee little friends?", completion = "Squueeeee!\n\nDid the nice Mr. <class> pull you from the flames, little friend? You're safe now!\n\nHooray!" }
WordHunterWoW_QuestEN[25386] = { title = "To Stonemaul Hold", description = "You must send word of what has happened here, {name}. To the south is Stonemaul Hold. There, our allies have gathered the few ogres of the horde to fight against those despoiling these forests.\n\nSpeak with Orhan Ogreblade. She leads the Stonemaul clan here, and will need to know of all that has occured. And be wary, lest some of this corruption remain...", objectives = "Speak with Orhan Ogreblade in Stonemaul Hold.", completion = "You've been tussling with drakes, eh?\n\nI like it. We need someone who can pull their own weight around here. Are you ready to fight for the Horde?" }
WordHunterWoW_QuestEN[25387] = { title = "To Camp Mojache", description = "You've done a hell of a job here, {name}. With the Twilight's Hammer shamed and the Gordunni left bleeding and broken, we'll be able to set our sights on the true battle with the Alliance here.\n\nIt'll take time to build our forces enough to match the night elves infesting this place. I'm sending you ahead to Camp Mojache to the east; they've got problems of their own, and we can't let any Horde territory fall here.\n\nLok'tar!", objectives = "Speak with Chief Spirithorn in Camp Mojache.", completion = "I am thankful you've come, <class>. Our camp is beset by many perils, and yet we must tend to those fleeing the devastation of the cataclysm.\n\nIf there is to be any refuge here, you must help us." }
WordHunterWoW_QuestEN[25388] = { title = "Crate of Crab Meat", description = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship.\n\nAdarrah would surely welcome such a find, considering the ordeal she's had to endure.", objectives = "Take the Crate of Crab Meat to Adarrah in Smuggler's Scar.", progress = "What have you got there, <name>?", completion = "Why, <name>! What a surprise!\n\nIf anyone ever calls your character into question you be sure to send them my way.\n\nI'll tell anyone who'll listen that in my moment of need, you gave me a case of crabs..." }
WordHunterWoW_QuestEN[25389] = { title = "A Taste For Tail", description = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry.\n\nI hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach.\n\nIf you come across any lobster types, I would happily pay you what coin I have with me for their tails.", objectives = "Adarrah wants you to bring her 4 Clacksnap Tails.", progress = "Oh, please tell me you were able to find me some food, <class>.", completion = "Oh, my!\n\nThat's some of the biggest, juiciest tail I've ever seen!" }
WordHunterWoW_QuestEN[25390] = { title = "A Girl's Best Friend", description = "Let's just get it out in the open. I'm no stranger to love, {name}.\n\nOver the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion.\n\nI've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.\n\nAt least I used to...\n\nWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", objectives = "Adarrah wants you to recover 6 Adarrah's Keepsakes.", progress = "Well, <race>?\n\nWere you able to recover my valuables?", completion = "Oh, you've found them! I was sure they were lost forever...\n\nHere you are, <name>. I hope this is ample payment." }
WordHunterWoW_QuestEN[25391] = { title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", completion = "As promised, you have your choice, <name>. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well." }
WordHunterWoW_QuestEN[25392] = { title = "Oh, Deer!", description = "Do you speak deer? It's all in the nose.\n\n<She points to her nose.>\n\nThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!\n\nGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.\n\nPlease save the little fawns, or I'll give you the big eyes!\n\n<Her eyes grow big and dewy.>", objectives = "Rescue three Injured Fawns from The Inferno and escort them back to Mylune at the Grove of Aessina.", progress = "Hurry! I can smell the smoke!", completion = "Oh yay! Happy little deer!\n\nNow they can grow up and have ADVENTURES.\n\nYou're swell." }
WordHunterWoW_QuestEN[25393] = { title = "Operation: Gnomeregan", description = "Momentarily, the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home, defended by a corrupt and irradiated army.\n\nThe assault begins in but a moment! Be ready recruit, this fight will not be for the faint-hearted.", objectives = "Help King Mekkatorque with the assault on Gnomeregan." }
WordHunterWoW_QuestEN[25394] = { title = "More Than Illness", description = "I've discovered a brood of dragon whelps gathered off the road to the north with a similar affliction. Green dragons are sacred custodians of nature. The fact that this disease is capable of spreading to them is cause for great alarm.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", objectives = "Kill 10 Noxious Whelps.", completion = "This development worries me greatly. This has happened before..." }
WordHunterWoW_QuestEN[25395] = { title = "The Stolen Keg", description = "You've got to help us, lad. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!\n\nUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they're hiding.\n\nThis can't stand! Now, while I stay here and try to convince this idiot that it was his fault, I'd like you to go in there and get our keg back. For Khaz Modan!", objectives = "Retrieve the Mountaineer's Ale from Dun Algaz.", progress = "Do you have it? Is the poor thing intact?", completion = "Thank the Makers! It's downright pristine. Those orcs couldn't figure out the tap-lock, it seems...and couldn't hack through the mastercraft work of Ironforge's keg-crafters with their crude weapons!" }
WordHunterWoW_QuestEN[25396] = { title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.", objectives = "Collect 7 Stonetears.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "The mountain giants are precious allies of our race. We must stop this corruption before it claims any more creatures of the forest." }
WordHunterWoW_QuestEN[25397] = { title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nShould they be corrupted by this malady, they will lash out in violence against trees, wildlife, and the very boulders they were shaped from.\n\nBe wary in your tasks. Should you find any corrupted giants, destroy them, for the sake of those still spared.", objectives = "Kill 6 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, <name>. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering." }
WordHunterWoW_QuestEN[25398] = { title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the north, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the very World Tree. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave.", objectives = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "Your bravery has seen us through! The Emerald Nightmare has been shut out from this land.\n\nThe fate of the dragon Taerar worries me...but there is much work still to be done. I cannot afford to dwell on it." }
WordHunterWoW_QuestEN[25399] = { title = "Hatecrest Forces", description = "The Hatecrest are fighting fiercely! Their leader is a priority, but we need to kill as many of them as we can.\n\nGo ahead of me, I'll meet you on the battlefield. Show them no mercy!", objectives = "Kill 10 Hatecrest Naga.", completion = "Your valor was mentioned in my briefings, <name>. I commend you." }
WordHunterWoW_QuestEN[25400] = { title = "The Gordunni Threat", description = "Estulan, the Highborne up in the tower, is reclusive. I haven't been able to speak to him very much. He has, however, told me that the ruins of the High Wilderness to the south are full of Gordunni ogres.\n\nThe ogres are not only a threat, they're destroying any forest and wildlife nearby. Estulan has also warned me of what might happen if they discover any artifacts of Highborne power among the ruins...\n\nHead south, {name}, and slay any Gordunni you find!", objectives = "Kill 16 Gordunni ogres in the High Wilderness.", completion = "It sounds like there were more than we thought! Thank you for your brave work, <name>." }
WordHunterWoW_QuestEN[25401] = { title = "The Gordunni Orb", description = "In addition to clearing out the ogres...\n\nEstulan mentioned something else about the ogres. He said the ogre warlocks may have some sort of orb, or other item of power\n\nHe was terse about it, but seemed upset...he said there was \"no way they could be Highborne\", so I think he wants to know just where they got them. Bring me back one of these orbs.", objectives = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Is that it? Let me see here..." }
WordHunterWoW_QuestEN[25402] = { title = "Estulan's Examination", description = "He's right. I haven't been among the night elves long, but I can tell these markings are completely unlike any kaldorei decorations...\n\nEstulan needs to see this. Take this up the tower to him. He may be surly, but don't be dissuaded; once he sees the orb, he'll realize it's an important issue.", objectives = "Deliver the Gordunni Orb to Estulan.", progress = "What is that you're holding?", completion = "Ahh, the orb I mentioned before. A decent reason to disturb me." }
WordHunterWoW_QuestEN[25403] = { title = "Ogre Abduction", description = "This is neither a crude ogre trinket, nor an ancient relic made by my kind. Its specific construction is new to me...and this fact disturbs me greatly.\n\nThe wolf-girl will be sending you to Dire Maul soon, to fight the Gordok elite. They are the leaders of the Gordunni, and would know who is supplying these.\n\nTake the orb back, I've cast a few enchantments on it. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", objectives = "Use the Modified Soulstone to capture a Gordok ogre.", completion = "Ah, you've brought him. Now I merely have to suffer the fate of speaking to him." }
WordHunterWoW_QuestEN[25404] = { title = "If You're Not Against Us...", description = "South of here you'll find a solitary tower, known as \"Blackhorn's Penance.\" Upon it is bound a demon: Tyrus Blackhorn.\n\nYou may think me mad for turning to an old foe for help, but Blackhorn was once a mortal, and I can't imagine he wants to watch Twilight's Hammer triumph.\n\nSpeak with Blackhorn, and see if you can convince him to help us in our fight. He may yet redeem himself.\n\n...Just don't set him free!", objectives = "Speak with Tyrus Blackhorn and convince him to help in the fight against the Twilight's Hammer.", progress = "You were sent here to talk, <race>. So. Talk.", completion = "Very well, <race>. I will help you mortals, even from within my bonds.\n\nBut don't sicken me by claiming it's my redemption. I do this for my own ends." }
WordHunterWoW_QuestEN[25405] = { title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", objectives = "Speak with Captain Taylor.", completion = "I hear you, <race>.\n\nI understand the urgency, but these men are in no condition to fight." }
WordHunterWoW_QuestEN[25406] = { title = "Gordok Guards", description = "With the nearby ogres dealt with, we should take the offensive and press our attack into their territory.\n\nThe Gordok ogres are the head of the Gordunni clan, ruling them from the ruins now called Dire Maul. They are stronger than the lesser Gordunni, but I have no doubt you can handle them, {name}. They won't know what hit them.", objectives = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Wonderful! Everything's going according to plan. Lady Shandris will be pleased." }
WordHunterWoW_QuestEN[25407] = { title = "Forces of Nature: Wisps", description = "The Sentinels make up the bulk of our forces here, but a well-rounded night elf army requires more than just night elves. The creatures of this forest, our ancestral home, have protected us for centuries. We simply need to rally them.\n\nTake this whistle. Our allies know this sound, and you'll be using it to recall them.\n\nBefore you start gathering creatures, I'd like you to recall a few of our wisps, just for practice. You can find them just outside the fortress, among the trees.", objectives = "Use Tessina's Whistle to recall 3 Feathermoon Wisps.", completion = "Wisps have always lived in harmony with night elves, and we depend on them for many things. These little guys you sent back, for example, will be helping us with some new construction and repairs.\n\nReady for more?" }
WordHunterWoW_QuestEN[25408] = { title = "Seeds of Their Demise", description = "We will decimate the Twilight's Hammer by corrupting and subverting them. \n\nSeeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower.\n\nMy little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", objectives = "Collect 8 Bileberries.", progress = "Has the local flora been giving you a hard time?\n\n<Blackhorn grins disturbingly.>", completion = "Very good. Please crush the berries into a pulpy liquid. That's quite an aroma isn't it?\n\nNow now, don't gag. It's beneath you." }
WordHunterWoW_QuestEN[25409] = { title = "Forces of Nature: Hippogryphs", description = "Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They're wary of other races, but they're intelligent enough to recognize a friend of a friend.\n\nI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.", objectives = "Use Tessina's Whistle to rally 10 Frayfeather Hippogryphs.", completion = "A properly trained squadron of hippogryph riders can take on nearly any opposing force. Feathermoon Stronghold will be much safer with these noble beasts on our side." }
WordHunterWoW_QuestEN[25410] = { title = "Forces of Nature: Treants", description = "Some people think treants are good for little more than fetching drinks in a war. Most of them haven't seen an entire defensive line scattered by what they thought was cover.\n\nAnd have you ever seen a peon try to chop one down and get surprised? I was in tears...\n\nAt any rate, they're immensely valuable allies. You'll find some wandering just outside  the Tower of Estulan and more in forest to the east, just southeast of Dire Maul. Be on the lookout for the Horde!", objectives = "Use Tessina's Whistle to rally 6 Wandering Forest Walkers.", completion = "They may not look it, but some treants grow to be ancient protectors. We could use a few more of those around here..." }
WordHunterWoW_QuestEN[25411] = { title = "A New Master", description = "The potion you created is vile enough to wake the dead. Which is its intended purpose.\n\nSlay a Twilight Inferno Lord and force the brew down his throat. He will revive, if only briefly, and be completely under your dominance.\n\nSpeak with him and learn the true name of the fire elemental he is channeling into the world to burn down your precious forest.", objectives = "Use the Bottled Bileberry Brew on the corpse of a Twilight Inferno Lord, then speak with him.", completion = "<The wretched creature before you speaks in a wavering voice, its body broken but briefly animated by Blackhorn's vile potion.>\n\nYes, master?" }
WordHunterWoW_QuestEN[25412] = { title = "The Name Never Spoken", description = "We called upon the fury and flame of the One, my former master.\n\nThe Inferno is by His design.\n\nHis true name is never uttered, it holds His power.\n\nEach of us was told but a piece. Each piece engraved on a firestone.\n\nThe One's true name is here, in the Inferno. Seek the three stones...", objectives = "Assemble the true name by examining the three Firestones.", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him." }
WordHunterWoW_QuestEN[25413] = { title = "Change of Plans", description = "Alright, kid. Slight change of plans...\n\nI think I've figured out a way to finish off that monster and you're going to assist me.\n\nThe way I see it, you owe me until my work is done here, and I ain't leaving without that artifact.\n\nFirst I need you to search those old wrecks for some good rope and a serviceable harpoon.\n\nThen... well, I'll fill you in on the rest later.", objectives = "Get the Rusty Harpoon and 3 Coils of Rope." }
WordHunterWoW_QuestEN[25414] = { title = "The Missing", description = "The cult isn't just spreading fear and paranoia anymore. Now, I'm receiving reports of missing people. Mothers, fathers, brothers, and sisters have seemingly disappeared, but I have a feeling they can be found in one of the cult's camps outside the city. If I give you the names of some of the missing people, would you try to locate them in the cultist camp at Mirror Lake Orchard? It's southwest of the city gates. To blend in, you'll need join the cult and get a robe from one of the doomsayers in Old Town.", objectives = "While wearing your Doomdsay Recruit's Robe, speak to Cultist Lethelyn, Cultist Kaima, Cultist Wyman, and Cultist Orlunn at Mirror Lake Orchard in Elywnn Forest.", completion = "So you found them? Why did the missing men and women not return with you?\n\n<You tell the captain that they seemed determined to stay for various reasons.>\n\nThen we cannot force them to come home. I can only hope that in time, the cultists will realize the harm their actions have caused and decide to return to their normal lives.\n\nThank you for your efforts, <name>. I will tell the families what you found." }
WordHunterWoW_QuestEN[25415] = { title = "Spreading The Word", description = "Welcome to our orchard, <name>. Everyone here works to earn <his/her> keep. For some, that means tending the fruit trees. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.\n\nTake this board. It bears a short message about our beliefs. While wearing it, visit the Westbrook Garrison, southwest of here, the town square of Goldshire just to the east, and the Valley of Heroes in Stormwind.", objectives = "While wearing your Doomsday Message, visit the Westbrook Garrison, the Valley of Heroes in Stormwind, and the town square of Goldshire.", completion = "Well done, <name>. It might be awkward at first, but you will grow accustomed to advocating our beliefs in public. It is one way of remembering our obligation to bring the truth to others. We must offer hope to everyone, for we all face the end of this world together." }
WordHunterWoW_QuestEN[25416] = { title = "The Master's Plan", description = "You're fitting in well here, <name>, but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.\n\nAs you know, this world is ending and the unprepared will die painful deaths.\n\nWe have been given a gift, an opportunity to become something greater and more powerful. Overseer Talathor is preparing for a ritual at the altar just west of the orchard. Wait there for him, and learn more of your new brothers and sisters.", objectives = "Learn more about the cult's plans at the altar in the westerm part of Mirror Lake Orchard.", completion = "Now that you understand the master's plan, you must prepare to play your part in making it a reality." }
WordHunterWoW_QuestEN[25417] = { title = "The Doomsday Plan", description = "The first batch of elemental devices are ready. Your task will be to conceal them inside populated areas of Stormwind. The devices will unleash their elementals at the proper time. Don't worry, <name>, you'll be safely away before that happens.\n\nDo not do anything that would draw attention to yourself.\n\n<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Captain Anton was hoping you'd uncover. You should probably bring the devices to him.>", objectives = "Take the Elemental Devices to Captain Anton in Stormwind Keep.", progress = "You've returned at last. I was beginning to think that you'd taken up with the cultists for good.", completion = "<You hand Captain Anton the devices that the overseer gave you, explaining the cult's plans.>\n\nCho'Gall is in charge of the cult? Then, it has to be Twilight's Hammer! We suspected that they would try to strike again, but no one knew what form the attack would take.\n\nYou've done an excellent job uncovering this plot. Unfortunately, you won't be the only one they've sent into the city to deploy these devices." }
WordHunterWoW_QuestEN[25418] = { title = "Thwarting Twilight's Hammer", description = "You can't have been the only person sent into Stormwind to deploy those devices containing wind elementals. We have to find and disable the rest of the devices before they set their captive elementals free to create storms in the city.\n\nAre you familiar enough with the devices to destroy them? Our best chance is to break the devices before the elementals inside can reach full strength. Look for the devices in the Trade District, Cathedral Square and the Mage Quarter. Hurry!", objectives = "Destroy Elemental Devices to release their captive elementals. Defeat 5 Raging Wind Elementals.", completion = "Excellent work, <name>. Twilight's Hammer will think twice before trying to turn our own people against us again.\n\nWhat worries me is how many citizens joined their movement without thinking about the cult's empty promises. Are times so dire that people will abandon the Light for promises of power and immortality?" }
WordHunterWoW_QuestEN[25419] = { title = "Lady La-La's Medallion", description = "Dozens of crude gold links make up this heavy chain.\n\nDangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion.\n\nYou wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.", objectives = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion." }
WordHunterWoW_QuestEN[25420] = { title = "Ancient Obstacles", description = "I've studied the gate here for years, trying to find a way of entry that wouldn't disturb any of the ancient architecture just behind it. It figures a few overgrown earthquakes decided to muck the whole thing up! But what's done is done, and the entrance to Uldum is revealed.\n\nI wasn't expecting anything to come out of the ruins before we went in, though. A whole mess of golems are running amok in the valley now, let loose from inside. Someone needs to clean them up if we're gonna get in there!", objectives = "Destroy 6 Sandstone Golems.", progress = "Make sure you decomission enough of those stony buggers.", completion = "Good work, <class>. We're that much closer to the secrets of Uldum." }
WordHunterWoW_QuestEN[25421] = { title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Gunstan would probably like to see this.", objectives = "Take the Grand Tablet to Gunstan.", progress = "You're back! What have you found?", completion = "This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we'll learn.\n\nI'd like to grant you a fine reward, <name>. We've made the find of the century!" }
WordHunterWoW_QuestEN[25422] = { title = "The Darkmist Legacy", description = "I am chained to this place...it takes so much effort just to speak to you. I can barely maintain this shape.\n\nI could help you, but please, help me pull myself together first. Once I'm more focused on this plane, I should be able to do it...\n\nIf I could just leave this tomb, the soil itself outside is full of ancient arcane deposits, laying forgotten for centuries. Could you bring me some?", objectives = "Collect 6 piles of Glowing Soil.", progress = "Do you have the soil? I'm having trouble staying together...hurry...", completion = "Thank you! Thank you...\n\nI feel much better. With just a bit more..." }
WordHunterWoW_QuestEN[25423] = { title = "Ancient Suffering", description = "You must be careful when you venture forth. Other spirits are bound to this place, malevolent and hateful ones. They've all suffered so much.\n\nNone of what they used to be remains, only suffering and a will to live. We will need that will to summon the overlord that keeps me bound here. Please, gather the essence of the spirits, and bring it back to me.", objectives = "Collect 6 Soul Essences.", progress = "Have you gathered it?", completion = "You can feel their anguish, can't you?\n\nMy poor friends. At least we can use you to fix things..." }
WordHunterWoW_QuestEN[25424] = { title = "Return to Alysra", description = "I thank you for freeing me, {name}.  I will tell our allies of my findings.\n\nI suggest that you return to the emerald dragon that sent you.\n\nThe Twilight's Hammer does not just seek to gain territory with this particular attack.  They're also after a prisoner.\n\nFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.", objectives = "Return to Alysra at the Ruins of Lar'donir in Hyjal.", completion = "This development is troubling, <name>.  We must act swiftly." }
WordHunterWoW_QuestEN[25425] = { title = "Warn King Wrynn", description = "You have successfully defended Stormwind from the threat posed by this Twilight's Hammer cult, <name>, and without harming our own citizens. Our enemy will not rest for long. Indeed, Cho'Gall must already be busy planning his next move.\n\nYou must take word to King Varian Wrynn. Go directly to him in the throne room of Stormwind Keep. Tell the king that our enemies have shown themselves and we must be prepared for their return.", objectives = "Speak with King Varian Wrynn in Stormwind Keep.", completion = "<The king's face takes on a look of concern, and then anger as you describe the Twilight's Hammer plot to destroy Stormwind.>\n\nHow dare they strike Stormwind? How dare they try to manipulate the people of this city against us and the Alliance! If not for your valor this day, <name>, our city would not have discovered this Twilight's Hammer scheme. You are a true hero of Stormwind and the Alliance." }
WordHunterWoW_QuestEN[25426] = { title = "War on the Woodpaw", description = "The first of Shandris's direct orders is to deal with the Woodpaw gnolls here. They've been spreading too far, too fast, and are becoming a threat to both the forest and our war effort.\n\nThey know we're here. After we took this camp, we've been leading covert strikes against them. It's time to make a major blow; bring back ten of their manes, and we'll be ready for the next phase.", objectives = "Collect 10 Woodpaw Gnoll Manes.", progress = "The manes aren't just for trophies. If there's to be slaughter, we may as well not let it be a total waste.", completion = "Excellent work, <name>. I didn't think those gnolls would give you much trouble." }
WordHunterWoW_QuestEN[25427] = { title = "Alpha Strike", description = "Never underestimate a threat. These gnolls may seem like simple brutes, but there's animal cunning even among them.\n\nThe gnolls run as a pack, and every pack has Alphas: The biggest, strongest, and most ruthless members that claw their way to dominance. They're the ones giving orders, so they're the ones we're going to slay now.\n\nThey reside mostly around the Woodpaw Den, pushing the others around. Get out there and push harder.", objectives = "Kill 5 Woodpaw Alphas.", completion = "Perfect. Any gnolls left will be simple prey, lost in the woods.\n\nHeh...here, soldier, take your reward before I get distracted. We've got other threats to deal with." }
WordHunterWoW_QuestEN[25428] = { title = "Black Heart of Flame", description = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him.\n\nThe ritual is simple: take this charred branch, tap it on the ground three times, and utter his name aloud.\n\nYou must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", objectives = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar.", progress = "Tell me! Have you fought Thol'embaar yet?\n\nI am living vicariously through you, <race>. Do not disappoint!", completion = "There it is! Such a trophy! Born in the fires of another plane...\n\nGo ahead, <race>. Crush it. Crush his charcoal heart in your hands and let the winds scatter the ashes... yes, yes." }
WordHunterWoW_QuestEN[25429] = { title = "Zukk'ash Infestation", description = "With the gnolls out of the way, we're ready to take care of other foes. Our scouts have discovered what appears to be a hive nearby, extending deep beneath the ground.\n\nThe insects of the hive are large and ferocious, and most likely pose an even greater threat than the gnolls. I want you to proceed to the hive with caution. Cut down a good portion of the bugs and bring back their carapaces for further study.", objectives = "Collect 20 Zukk'ash Carapaces.", progress = "How goes the hunt, <name>?  Are you here to report your success?", completion = "These are silithid after all...I wasn't sure, having never seen one in person. Gilneas had its problems, but at least we didn't have these monstrosities running around!" }
WordHunterWoW_QuestEN[25430] = { title = "Emerald Allies", description = "The druids of Hyjal are not the only ones sworn to defend this land.  The emerald dragons have once again become a powerful ally to our cause.\n\nSpeak to Alysra at the Ruins of Lar'donir, to the north, and see what you can do to help.", objectives = "Speak to Alysra at the Ruins of Lar'donir in Mount Hyjal.", completion = "My duties are here, viewing the enemy's movement from above, commanding our armies where they're needed.\n\nYour aid would be most welcome." }
WordHunterWoW_QuestEN[25431] = { title = "Stinglasher", description = "Most of the insects we've seen wandering the hive have been enormous enough, but my scouts reported an especially huge one. It's supposedly a massive wasp, and it seemed to be directing the workers on the surface.\n\nI don't know much about these things, but if they're starting to wander beyond that pit in the ground, we need to put a stop to it. Kill this giant wasp and return to me.", objectives = "Kill Stinglasher in the Writhing Deep.", completion = "Well done, <name>! You're proving very valuable to securing this area for the Alliance." }
WordHunterWoW_QuestEN[25432] = { title = "It's Not \"Ogre\" Yet", description = "We dealt the Gordunni ogres a large blow at Dire Maul, but we haven't quite finished the job. My scouts have reported a group of them amassed in the hills to the north, gathering for some reason.\n\nIt's possible they're interested in the Horde settlement nearby, but I don't want to take any chances. Scout the area, kill any ogres you come across, and report back.", objectives = "Kill 5 Gordunni Hillguards.", progress = "Be sure to strike a few down during your scouting. We should be efficient.", completion = "It's good to see you back. We've learned more about the ogre situation." }
WordHunterWoW_QuestEN[25433] = { title = "Sasquatch Sighting", description = "You may have seen it yourself, but other scouts have discovered an enormous beast being held by the ogres. Reports say it looks like a sasquatch, but if it is, it's the biggest ever seen in Feralas.\n\nThe ogres are most likely trying to teach it to obey them. While that's almost comical, I'm not going to sit by and let them train that thing to roll over at their command. Return to the hills and slay it.", objectives = "Kill Bigfist.", completion = "Well done once again, <name>. Yet another threat removed from Feralas." }
WordHunterWoW_QuestEN[25434] = { title = "Taming The Tamers", description = "The sasquatch may be a larger threat, but we also need to wipe out the ogres. The Gordunni have been a nuisance to us for too long, and Lady Shandris wants them completely gone.  Let's hope these are the last ones.\n\nKill the Gordunni tamers that keep the beast chained, and make sure they know the price of their meddling.", objectives = "Kill 6 Gordunni Tamers.", completion = "Good work, and good riddance. I hope we never have to see another ogre here again!" }
WordHunterWoW_QuestEN[25435] = { title = "Pressure is Mounting", description = "G'day, laddie.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nWhile he's tryin' to find us a safe place to hole up, I'm gunna take a stab at securin' you a critter to ride.\n\nNow, I may not be up on all the ins an' outs of life in the sea, but it looked to me like them naga know how to get around down here.\n\nYou round up a few widgets for a bridle and I'll work up an enchantment.", objectives = "Collect 3 Shark Sinews from Ravenous Threshers and 2 Sharpened Crab Claws from Sabreclaw Skitterers.\n\nRavenous Threshers can also be summoned to you by using Crab Entrails." }
WordHunterWoW_QuestEN[25436] = { title = "Spiteful Sisters", description = "Something truly disturbing has occured. While on patrol, several of my scouts were ambushed by dryads.\n\nThe dryads are close allies of the night elves and guardians of the forest. I assumed they were just frightened by the sight of worgen, but the sentinels I sent out afterwards were also attacked.\n\nWhatever is going on, I don't like it. I want you to go investigate as well. If even the dryads have been corrupted...put them to the sword.", objectives = "Kill 8 Corrupted Dryads.", completion = "I didn't want to scare you, but this is a grave situation. If the portal at Dream Bough was sealed, and the corruption is still spreading..." }
WordHunterWoW_QuestEN[25437] = { title = "Ysondre's Call", description = "A dragon of the emerald dream... what have you gotten yourself involved in, {name}?\n\nI wouldn't keep her waiting if I were you. The place she spoke of is what we call the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; there's a small shrine at the top.\n\nGood luck, {name}. I hope to see you back safe.", objectives = "Speak with Ysondre atop the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, <class>, but I've ran from him long enough. Taerar must be stopped." }
WordHunterWoW_QuestEN[25438] = { title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", objectives = "Speak to Adella at Shadebough.", completion = "To be drawn into a fight between dragons...I don't know if you're blessed or cursed.\n\nLady Shandris has heard of all you've done, and has personally sent this reward for your bravery. I'm glad you came back in one piece to receive it." }
WordHunterWoW_QuestEN[25439] = { title = "Vengeful Heart", description = "These are the naga that took our people. I only need one to interrogate, kill the rest.\n\nShow no mercy, {class}, for they would surely show us none.", objectives = "Kill 10 Zin'jatar Ravagers.", completion = "Good to have a real warrior at my side. Too often, my shaman brethren can't seem to stomach the work." }
WordHunterWoW_QuestEN[25440] = { title = "Fathom-Lord Zin'jatar", description = "The Fathom-Lord is here, at the far side of the ruins. He's still injured from our last battle.\n\nI'll leave this pleasure to you. Make sure he doesn't get away this time.", objectives = "Kill Fathom-Lord Zin'jatar.", completion = "And with this, hopefully their attacks on us will calm for a while." }
WordHunterWoW_QuestEN[25441] = { title = "Vortex", description = "I have no fondness for snakes, and even less so down here. Fortunately for us, the watery elements still bend to my will for now.\n\nTake these globes and throw them at the ground to send the nearby water into a vortex, pulling in all the nearby serpents. The naga will most certainly turn the snakes against us, so keep the orbs close at hand.", objectives = "Use the Globes of Tumultuous Water to trap 30 swarming serpents.", completion = "Too often, we are mistaken for druidic types. Perhaps that's true for some shaman, but do not let yourself be plagued by the ignorant belief that we are always peaceful.\n\nNothing about what I do is harmonious. I command the elements to my will. There is nothing offered in return. I would have it no other way." }
WordHunterWoW_QuestEN[25442] = { title = "A Pearl of Wisdom", description = "This pearl is unlike anything you've ever seen before. It radiates light, and if you are not mistaken, it radiates powerful magic as well.\n\nEarthmender Duarn back in Silver Tide Hollow will surely be interested in this.", objectives = "Bring the Luminescent Pearl to Earthmender Duarn in Silvertide Hollow.", progress = "Yes, <class>? Have you found something?", completion = "What is this? A pearl? Much more I think.\n\nThis is exactly what I was looking for, thank you for bringing it to me." }
WordHunterWoW_QuestEN[25443] = { title = "The Name Never Spoken", description = "Did my drought work? You spoke with one of them?\n\nThen you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need.\n\nHurry! Your precious forest burns!", objectives = "Assemble the true name by examining the three Firestones in the Inferno.", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him." }
WordHunterWoW_QuestEN[25444] = { title = "Da Perfect Spies", description = "Now, it would be foolish to go in blind 'ere, so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.\n\nI could use da help, if you be feelin' up to it. I tell ya how it's done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.\n\nOnce ya have de frogs, bring 'em over here to my sentry totem an' attune dem to me sight.", objectives = "Capture 5 Sen'jin Frogs and attune them to Vanira's sight at her Sentry Totem." }
WordHunterWoW_QuestEN[25445] = { title = "Zalazane's Fall", description = "De time for battle is now!  We'd be headin' ova to da islands soon, so you'd betta be ready.\n\nZalazane doesn't have much time left.", objectives = "Help Vol'jin take back the Echo Isles and kill Zalazane." }
WordHunterWoW_QuestEN[25446] = { title = "Frogs Away!", description = "Wit de frogs ready to go, I be needin' ya to help me send 'em out to the isles.\n\nOn de eastern side of Sen'jin Village, ya can find Handler Marnlek. He be handlin' all the bats for Vol'jin's scouts and he can loan ya a bat to get ya out to de isles.\n\nTake dis sack' o frogs with ya. I been askin' de spirits for guidance. Dey've sent smoke to show ya where I need de eyes most. While ridin' de bat, reach into de sack and toss de frogs toward de white smoke.", objectives = "While riding a bat, use the Sack o' Frogs to place 12 attuned frogs on the markers in the Echo Isles." }
WordHunterWoW_QuestEN[25447] = { title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", objectives = "Collect 8 Infected Stag Antlers.", progress = "This is a sad task, <name>, but necessary.", completion = "At the very least, these creatures' suffering has ended. Let us hope their sacrifice will bring a stop to further pain." }
WordHunterWoW_QuestEN[25448] = { title = "The Northspring Menace", description = "My duty here is to watch over Telaron. Even without his meditation leaving him vulnerable, there's enough threats in this forest to keep both of us on our toes.\n\nThat's why it maddens me so much that I don't have the opportunity to leave camp. More harpies than I've ever seen infest the northwest...foul creatures, spreading their filth across the ancient ruins uncaringly.\n\nThey're a threat to this camp, and have no place in these lands. I'll pay you well if you get rid of them.", objectives = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", completion = "Thank you, <class>. That's one less distraction for me." }
WordHunterWoW_QuestEN[25449] = { title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides. The Yeti are native to Feralas, with many found in Rage Scar Hold to the northeast. I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair, then we're in business.", objectives = "Collect 10 Thick Yeti Hides.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!" }
WordHunterWoW_QuestEN[25450] = { title = "Improved Quality", description = "It's funny how things change. The northern yetis used to yield the best hides, but these...there's been a decline in quality, it seems. Maybe something nearby is making them sick.\n\nLuckily, the Feral Scar yetis to the southeast have flourished. I bet their hides are even better than they used to be!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", objectives = "Collect 10 Feral Scar Yeti Hides.", progress = "These hides may not be as resilient as thorium, but they're nice and supple.", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your help <name>.  Here - please take one of my latest creations." }
WordHunterWoW_QuestEN[25451] = { title = "Pristine Yeti Hide", description = "You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.", objectives = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.", progress = "What's this, <name> - you've got something special for me?", completion = "Incredible!  You may have found the granddaddy of all yeti hides with this!\n\nYou better believe I'll pay you for it.  I normally don't pay that much for a single hide, but I'm pretty sure I can make something special from it.  Thanks for thinking of me on this, <name>!" }
WordHunterWoW_QuestEN[25452] = { title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found north of here in Rage Scar Hold.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", objectives = "Collect 10 Thick Yeti Hides.", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, <name>... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted." }
WordHunterWoW_QuestEN[25453] = { title = "Improved Quality", description = "I'm a bit confused. The Rage Scar yeti used to be the finest source of leather in these lands... but these pelts are weak and even rotted in spots. Some sort of illness must be plaguing the creatures.\n\nI'll have to rely on a different source. The yeti of Feral Scar Vale to the south have hides nearly as strong. They are also a great deal fiercer; do not hunt them without caution, {class}.", objectives = "Collect 10 Feral Scar Yeti Hides from Feral Scar Yeti.", progress = "Are the Feral Scar yeti still there? Did you get the leather?", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your aid, <name>.  Here - please take one of my latest creations." }
WordHunterWoW_QuestEN[25454] = { title = "Perfect Yeti Hide", description = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Stonemaul Hold is in the market for yeti hides, this particular one may be of considerable interest to him.", objectives = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Stonemaul Hold in Feralas.", progress = "What's this, <name> - you've got something special for me?", completion = "This is an incredible find!  I believe this is the finest yeti hide specimen I have ever seen!\n\nIndeed, this is certainly worthy of an appropriate bounty.  I normally don't pay that much for a single hide, but I'm confident I can make something special from it.  Thanks for thinking of me on this, <name>!" }
WordHunterWoW_QuestEN[25455] = { title = "A Test of Wills", description = "Arright, laddie here we go.\n\nYou just need to sneak up on one 'a them naga while they ain't lookin' and use this bridle on 'em.\n\nDon't get too close, now! Ya gotta surprise 'em.\n\nDo it right an' get 'em under your control, and it'll be time ta show 'em who's boss!\n\nJust keep yankin' the reins 'til their will is broken, and you'll have yerself a fancy ride!\n\nGo on, now. Go git you one! I think I can see one just north 'a here...", objectives = "Use Erunak's Bridle to captivate a Zin'jatar Raider, then yank its reins until it submits." }
WordHunterWoW_QuestEN[25456] = { title = "Back in One Piece", description = "Yeah yeah, I'm sure Felora wants you back. That woman has no respect for innovation. When I told her about the modifications I was making for my Earth Elemental, she nearly threw a fit.\n\nGo tell her everything's all well and dandy. And tell her she's not getting a share of my inevitable fortune either.\n\nShe probably likes sleeping on the rock anyway.", objectives = "Return to Felora Firewreath in Silver Tide Hollow.", completion = "Sam's in one piece then? And his poor assistant Felice? Good to hear.\n\nI hope that one day he'll learn to respect the elements as more than just a tool." }
WordHunterWoW_QuestEN[25457] = { title = "Ron Targetting Test", description = "Complete this quest.", objectives = "Complete this quest." }
WordHunterWoW_QuestEN[25458] = { title = "General Skessesh", description = "The leader of these forces must fall! The naga's offensive will be broken with no one to command them.\n\nI saw the coward retreat into one of the abandoned buildings here. Cut your way through the others and take his head! Lady Shandris will want to see it for herself.", objectives = "Slay General Skessesh and take his head.", progress = "Has the general fallen?", completion = "Good riddance to foul creatures. May the naga slither back into the sea and never return.\n\nYou've proven yourself on the battlefield, <name>. I would ask more assistance of you in defending our lands here." }
WordHunterWoW_QuestEN[25459] = { title = "Ophidophobia", description = "If there's one thing I can't stand, it's snakes. Any kind of snake - doesn't matter.\n\nWhile I was out searching for salvage, I saw a nest of sea serpents surrounding the nearby wreckage.\n\nI simply can't relax knowing that those awful creatures could slither up in here at any moment.\n\nPlease, {class}! Do something about them!", objectives = "Kill 4 Brinescale Serpents at Gorrok's Lament.", completion = "Well that's a load off my mind.\n\nThank you again, <class>." }
WordHunterWoW_QuestEN[25460] = { title = "The Earth Rises", description = "The effects of the Twilight's Hammer attack can be felt even here, this close to the world tree.\n\nAs our forests burn, the very earth turns against us in a crazed frenzy.\n\nWe can't allow the elementals to go unchecked.  Go and help our men take care of them.", objectives = "Slay 8 Scalding Rock Elementals.", completion = "I thank you, <name>.  Your fighting prowess is admirable.  You will be crucial to putting a halt to the elemental onslaught." }
WordHunterWoW_QuestEN[25461] = { title = "Trollin' For Volunteers", description = "Vol'jin has given me his war drums and put  me in charge of trainin' da new recruits here. Only problem is we be short on new recruits.\n\nSupposin' I loaned ya dis drum, would ya use it to sound de call to war on Vol'jin's behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause, it would make a difference. Once ya've convinced dem to volunteer, bring dem back to me for trainin'. Go over an' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.", objectives = "Use Vol'jin's War Drums to recruit 5 Troll Citizens in Razor Hill.\n\nYou can speak to Handler Marnlek for a bat ride to Razor Hill." }
WordHunterWoW_QuestEN[25462] = { title = "The Bears Up There", description = "Do not fear the bears in this grove, {class} - I have pacified them for the moment.\n\nMy concern at present is for the welfare of the bear cubs. The fires drove the little ones up the trees, where they've gotten stuck. We've got to get those bears safely to the ground!\n\nFlying creatures frighten them, so you'll have to climb the trees yourself. Look for footholds at the trunks. Climb the trees, grab the bear cubs, and toss them - GENTLY! - onto the target here.\n\nNothing can go wrong with this plan.", objectives = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", progress = "Please don't hurt the trees. Or the bears.\n\nOr yourself.", completion = "I thank you, <name>. Those little bears are shaken up but they'll survive.\n\nAt least the ones that hit the mat." }
WordHunterWoW_QuestEN[25463] = { title = "Report to Silvia", description = "A Highborne mage named Estulan, estranged from his surviving brothers, has built a tower to the east where he trains young night elves in arcane magic.\n\nWere it not for Lady Tyrande's recent mercy towards his kind, his execution would be my duty under the law. He will be watched closely, but I will not deny aid to my Sentinels simply out of pride.\n\nI've sent Silvia ahead to the Tower of Estulan to begin an offensive against the ogres infesting the nearby forest. Report to her for further orders.", objectives = "Report to Silvia at the Tower of Estulan.", completion = "Good to see you here. Estulan is being...difficult. We're going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us." }
WordHunterWoW_QuestEN[25464] = { title = "The Return of Baron Geddon", description = "Ragnaros is not the only powerful elemental that has re-emerged into our world.\n\nThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.\n\nThe Flameseer's Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.\n\nGo, {name} and be careful.  Baron Geddon is a vengeful and treacherous being.", objectives = "Channel the Flameseer's Staff to weaken Baron Geddon.", progress = "Is it done yet, <name>?", completion = "Well done, <name>.  We cannot afford to lose any further ground in Hyjal.\n\nBy stopping Baron Geddon we will have dealt a huge blow to the enemy." }
WordHunterWoW_QuestEN[25465] = { title = "Still With The Zapped Giants", description = "Hey pal! I'm still working on a variant of a gnomish shrinking ray, using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on some of the sea giants along the coast here.  You should find miniaturization residue on them after you shrink them - bring me back some!", objectives = "Use Zorbin's Ultra-Shrinker to zap Shore Striders and collect 6 Miniaturization Residues.", progress = "I had to tweak the thing to stop working on mountain giants. Even though I wasn't the one running around zapping things, those night elves beat the copper out of me after they found those guys shrunk.", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, <name>.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!" }
WordHunterWoW_QuestEN[25466] = { title = "Even More Fuel for the Zapping", description = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!", objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays.", progress = "While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?", completion = "Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!\n\nThank you, <name>, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!" }
WordHunterWoW_QuestEN[25467] = { title = "Kliklak's Craw", description = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible.\n\nIt clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk.\n\nA well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", objectives = "Obtain the Corroded Key from Kliklak to unlock the Half-buried Footlocker in the Kelp'thar Forest.", progress = "The footlocker's keyhole is encrusted with barnacles, but may still be operable.", completion = "The satisfying sound of a chest unlocking is followed by the sight of once-hidden treasure." }
WordHunterWoW_QuestEN[25468] = { title = "Forces of Nature: Faerie Dragons", description = "You wouldn't know it from looking at them, but the lovely faerie dragons that inhabit this forest can be truly fearsome if trained properly. They can do amazing things to magical energy...absorb it, redirect it, even nullify it entirely.\n\nThey're nearly harmless alone, but in large numbers, they can have a stunning effect on a battle. You can find some in the fields to the northwest, but be careful, the Horde is nearby.", objectives = "Use Jesana's Faerie Dragon Call to rally 10 Sprite Dragons or Sprite Darters.", completion = "Aren't they adorable? The babies are even cuter." }
WordHunterWoW_QuestEN[25469] = { title = "Forces of Nature: Mountain Giants", description = "The mountain giants are our most powerful allies of the forest. They're carved from the land itself.\n\nNot many of our enemies are willing to fight off a walking hillside. It only takes a few of these to turn the tide of a battle completely.\n\nThe mountain giants here have been afflicted by some illness lately, but I've seen a healthy group of them to the southwest.", objectives = "Use Jesana's Giant Call to rally 5 Mountain Giants.", completion = "Excellent!\n\n<name>, you've helped bolster our forces here, and you've saved many of these forest creatures from the Horde as well. With our army now ready, Feathermoon will stand against all threats, Horde or otherwise!\n\nOn behalf of Lady Feathermoon, I'd like to award you with this weapon, fit for a Sentinel." }
WordHunterWoW_QuestEN[25470] = { title = "Lady Of Da Tigers", description = "Remember de frogs ya made into me eyes and ears? Well, dey've found somethin' interestin'.\n\nOn an island to de southeast, dey've spied a tiger even de other cats seem to fear. Dis tiger, I've never seen anythin' like it.\n\nIt hunts wit' da instincts of a cat, but de mind of a person. It could be a powerful spirit and a strong ally.\n\nI'll be callin' down the spirit o' the tiger upon ya. Use its gifts to locate this cat and challenge it. See if ya can win its aid in our battle for the isles.", objectives = "While imbued with the Spirit of the Tiger, lure the Tiger Matriarch out of hiding and use your new abilities to best it in combat." }
WordHunterWoW_QuestEN[25471] = { title = "Across the Great Divide", description = "We will need to press deeper into Vashj'ir if we want to uncover what the naga are doing here.\n\nGo to the Lightless Reaches, the giant chasm bordering the Kelp'thar Forest to the west.  If you look across it, you should see a cluster of plant-life surrounding the entrance to Damplight Chamber.\n\nOnce you're inside the cave, it's a bit of a ride up until you break surface, but I have friends there that should provide you a warm welcome.", objectives = "Speak to Farseer Gadra in the Damplight Chamber.", completion = "Ello, mon! You look a bit more capable then most of dem coming through here.\n\nCome rest a bit. Make yaself at home." }
WordHunterWoW_QuestEN[25472] = { title = "The Flameseer's Staff", description = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces.  It was an ancient bone staff that granted its wielder power over the elements of fire.\n\nIts fragments litter the area around us.  Find them and bring them to Malfurion.  Perhaps the artifact's power will still be of use.", objectives = "Obtain 8 Bone Staff Fragments.", progress = "Yes, <name>?", completion = "Excellent, <name>.  This will be a great weapon against the enemy forces." }
WordHunterWoW_QuestEN[25473] = { title = "Kaja'Cola", description = "Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today.\n\nOops, was it supposed to be a surprise? You didn't hear it from me!\n\nAnywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?", objectives = "Deliver the Six-Pack of Kaja'Cola to Sassy Hardwrench at KTC Headquarters on Kezan.", progress = "<Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.>\n\nWe need more Kaja'Cola than this!\n\nI swear I'm going to fire Dampwick if I don't kill him first!", completion = "Just so you know, you'll find Kaja'Cola all over town. It's the Bilgewater Cartel's best-selling product of all time!\n\nJust remember, image is everything if we're going to get you promoted to Trade Prince! No, wait, profits are everything! Explosions are a close second! Then, image!" }
WordHunterWoW_QuestEN[25474] = { title = "Once More, With Eeling [DEPRICATED]", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", objectives = "Kill 15 of any Eel in the Kelp Forest." }
WordHunterWoW_QuestEN[25475] = { title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" }
WordHunterWoW_QuestEN[25476] = { title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance <name>, my robots and I are in your debt!" }
WordHunterWoW_QuestEN[25477] = { title = "Better Late Than Dead", description = "Greetings, friend.\n\nIt is good to see that you survived your battle in one piece.\n\nWhile Erunak tries to scry a place of safety for us all, I shall assist you in securing a less strenuous means of transport.\n\nI have prepared this baitstick to use near a sea turtle. It is crude, but it should serve to bring one under your control.\n\nOnce you've become comfortable with the animal, simply guide it back here to me.", objectives = "Use Moanah's Baitstick on a Speckled Sea Turtle and ride it back to her.", progress = "Were you able to tame a sea turtle, <name>?", completion = "How unfortunate...\n\nWell, all things considered, it is good to see that you made it back unharmed." }
WordHunterWoW_QuestEN[25478] = { title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "Borrow a wind rider from Dyslix Silvergrub and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", completion = "Nyse sent you? Good! We need your help, now!" }
WordHunterWoW_QuestEN[25479] = { title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "Borrow a hippogryph from Dyslix Silvergrub and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", completion = "Thyssiana sent you? Good! We need your help, now!" }
WordHunterWoW_QuestEN[25480] = { title = "Dance Of De Spirits", description = "De time has come to start thinkin' about when to make our move. Champion Uru'zin tells me his men be ready. You and Vanira done good work gatherin' information on de enemy and findin' us new allies.\n\nNow, we read de omens. We find out when to launch de attack.\n\nFind Witch Doctor Hez'tok near the circle of ritual dancers. He be startin' de ritual as soon as ya be ready.", objectives = "Talk to Witch Doctor Hez'tok near the circle of ritual dancers outside Sen'jin Village when you're ready to consult the omens." }
WordHunterWoW_QuestEN[25481] = { title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. Seyala Nightwisp will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "Borrow a hippogryph from Seyala Nightwisp and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", completion = "Falfindel Waywarder sent you? Good! We need your help, now!" }
WordHunterWoW_QuestEN[25482] = { title = "LFGDungeons - Holiday Dungeon - Headless Horseman - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25483] = { title = "LFGDungeons - Holiday Dungeon - Coren Direbrew - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25484] = { title = "LFGDungeons - Holiday Dungeon - Ahune - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25485] = { title = "LFGDungeons - Holiday Dungeon - Crown Chemical - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25486] = { title = "The Grimtotem are Coming", description = "This is going to take a while, but I'm sure we'll beat them back.\n\nYou're more good to Thousand Needles elsewhere. We have reports that the gnomes and goblins out on the flooded salt flats somehow survived on a giant barge! Rendow is on the dock. She'll get you a boat to go there.\n\nMind helping us out a little on your way to her?", objectives = "Slay 7 Grimtotem Marauders.", completion = "A boat? Yes, you can have this last one." }
WordHunterWoW_QuestEN[25487] = { title = "The Grimtotem are Coming", description = "The cowardly Grimtotem have attacked us by surprise when we were least prepared!\n\nYou will be of most help to Thousand Needles elsewhere, {class}. We have heard rumors that the goblins and gnomes somehow survived in a giant barge out on the salt flats.\n\nMotega Firemane is at the base of the summit. He can get you a canoe to take you there.\n\nDo you mind helping us fight off the Grimtotem on your way to him?", objectives = "Slay 7 Grimtotem Pillagers.", completion = "You want a canoe to go out to the salt flats? But, surely the race track has been destroyed?!\n\nNonetheless, for your bravery, you will have the last one!" }
WordHunterWoW_QuestEN[25488] = { title = "Two If By Boat", description = "Are you ready to go, {class}? One of the sentinels will take you out to the Mirage Raceway.\n\nIf there's anyone left alive out there, please help them.\n\nGoddess watch over you!", objectives = "Speak with Fizzle Brassbolts at Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "YES?! Do you see me interrupting your fascinating argument?\n\nNo... no, please, go ahead. I'm sure that your interruption is about something very important. More important than dealing with the survival of everyone here, in fact.\n\n<Fizzle taps his foot impatiently.>" }
WordHunterWoW_QuestEN[25489] = { title = "Two If By Boat", description = "Are you ready to go, {class}?\n\nOne of our braves will row you out to the Mirage Raceway. If anyone has survived out there, they'll desperately need your help.\n\nMay the Earth Mother smile upon you.", objectives = "Speak with Pozzik at Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Heya, kid, I'll be right with ya. Just gotta shut this gnome twerp up first." }
WordHunterWoW_QuestEN[25490] = { title = "Smashing Through Ashes", description = "{name}, these fiends from the Twilight's Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.\n\nArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it's blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.\n\nOn your way there, clear the roads by killing any Charbringers that you find.", objectives = "Slay 8 Charbringers.", progress = "Have you made any progress clearing the road to this shrine?", completion = "Very good. The Twilight's Hammer must be sent the message that we will never give up." }
WordHunterWoW_QuestEN[25491] = { title = "Durable Seeds", description = "This land has been scourged by fire, but it may yet renew itself.\n\nSome seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", objectives = "Gather 10 Hyjal Seedlings from piles of Scorched Soil.", progress = "I suspect life still struggles beneath the ash. What were you able to find?", completion = "<The Arch Druid inspects the seedlings.>\n\nThese seedlings have survived an apocalypse. Even a handful hold great power. Life always replenishes itself, often stronger than before.\n\nOnce the way is clear, we will use these to perform a miracle on this mountain, <name>. You will see." }
WordHunterWoW_QuestEN[25492] = { title = "Firebreak", description = "In their efforts to decimate Hyjal, Twilight's Hammer has elementals scouring the earth in the wake of the fire.\n\nThey're pulverizing the soil, rooting around in the ash, digging up any scrap of plantlife that survived and destroying it. It's like they're paving the way for... I don't even want to imagine.\n\nStop them before Hyjal is devoid of life. Kill the lava surgers!", objectives = "Slay 10 Lava Surgers.", completion = "Good work, <name>. There's a chance the forest will recover from this yet.\n\nNow, there's something else I need you to take care of for me..." }
WordHunterWoW_QuestEN[25493] = { title = "Fresh Bait", description = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake.\n\nFreeing Tortolla from his bonds will not be easy. But we will take it one step at a time.\n\nHead into the Flamewake and collect for me heaps of core hound entrails. I will explain why later.\n\nAnd beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", objectives = "Collect 4 heaps of Core Hound Entrails.", progress = "Have you collected the innards?\n\nCore hounds are not native to this part of the world, they accompanied Twilight's Hammer from the nether regions of the earth. Do not trouble yourself over their elimination.", completion = "Very good. We will need these to act as bait while they are still warm.\n\nHere is my plan..." }
WordHunterWoW_QuestEN[25494] = { title = "A Champion's Collar", description = "This little guy is a true menace now, isn't he?\n\nWe're going to have to give him a nice spiked collar if he's going to be a fighting pup.\n\nThe basilisk matriarch has made her lair off of the road to Winterspring.  Bring me her spiked hide and we'll fashion a collar for our little killer here.", objectives = "Obtain the Spiked Basilisk Hide from the Spinescale Matriarch.", progress = "Did you get it?", completion = "Excellent!  Our pup is ready for a fight." }
WordHunterWoW_QuestEN[25495] = { title = "Preparin' For Battle", description = "Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.\n\nFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you, {name}. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an' he give you a bat to fly out to de stagin' area.", objectives = "Speak to Handler Marnlek for a flight to the staging area. Meet Vol'jin on the island east of the war camp.Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.\n\nFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you, <name>. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an' he give you a bat to fly out to de stagin' area.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25496] = { title = "Grudge Match", description = "I don't know if you've picked up on this, but there's a bit of a rivalry between the ogre members of the Twilight's Hammer and the rest of us.\n\nFor me... it's personal.\n\nThis one ogre called Gromm'ko has a pet raptor named \"Butcher.\"  He's taken out the last three of my corehound pups.\n\nI think this last one will fare differently.  He's got a real killer's instinct.\n\nGo to the Seat of the Chosen and challenge Gromm'ko to a match between our two beasts.  Humiliate him for me, {name}damus.", objectives = "Challenge Gromm'ko at the Seat of the Chosen in Hyjal.", completion = "That's how it's done!" }
WordHunterWoW_QuestEN[25497] = { title = "Back in the Saddle", description = "Our situation is growing a bit desperate, {race}.\n\nWe must focus our attention on the naga and their prisoners, but it would be folly to do so without being prepared, and down here that means finding a way to travel more quickly.\n\nThese sharks are clearly fond of sea turtle. Let's see if we can turn that into our advantage.", objectives = "Use 6 Turtle Meat to create shark bait." }
WordHunterWoW_QuestEN[25498] = { title = "Shark Bait", description = "<Erunak speaks as he places the turtle meat into a porous sack.>\n\nReady yourself, {name}. There's no telling how this might end up, but we don't have much choice if we are to rescue your friends.\n\nTake this sack and use it at the sunken anchor southeast of here. Once you've attracted a shark, do your best to ride it back to me here.\n\nIf you can do that, you will have a most intimidating means of transportation.", objectives = "Use the Shark Bait at the Sunken Anchor and ride the shark to Erunak." }
WordHunterWoW_QuestEN[25499] = { title = "Agility Training: Run Like Hell!", description = "Before we go any further, we're going to have to get you into shape.\n\nDevotion to the Old Gods is not going to save you when some emerald dragon comes chasing after you.  You need to be fleet of foot, if you catch my drift.\n\nEnough said.  We'll summon your trainer... your job is to run away from him without leaving this camp.\n\nGo!", objectives = "Run away from the Blazing Trainer within the Forge of Supplication for 1 minute.", completion = "Oh.  You're still alive.\n\nNot bad." }
WordHunterWoW_QuestEN[25500] = { title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and see if there's anything else he needs of you.", objectives = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot." }
WordHunterWoW_QuestEN[25501] = { title = "Poaching for Dummies", description = "A new face around here, huh? You're in luck, making coin's easy thanks to my butcherbots. You go out and hunt some scorpids, some hyenas, maybe a few basilisks, set the butcherbot down, and let him do his thing! I've programmed him to extract all the valuable parts and place it safely in his hopper.\n\nIf you're interested, take him out to the northwest near Sandsorrow Watch first. Just bring him back once he's full and I'll pay you for the contents.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Butcherbot on the corpse of 20 Glasshide Basilisks, Scorpid Tail Lashers, or Blisterpaw Hyenas." }
WordHunterWoW_QuestEN[25502] = { title = "Prepping the Soil", description = "The Arch Druid has tasked me with setting up a series of flamewards around the perimeter of the area. Once these are active, we can prevent further attacks from the fire elementals that left this valley in ruins.\n\nThese will also protect and nourish the soil for whatever Hamuul has planned.\n\nIt's time to begin. Find one of the five flamewards I've marked on your map, activate it, and defend it from counterattack until its magic kicks in. It won't take more than a minute.", objectives = "Activate and defend a Flameward.", completion = "That's good! Between your work and the work of a few others, that valley is secure from a counter-attack.\n\nI've done all I can. It's all up to you and the Arch Druid now." }
WordHunterWoW_QuestEN[25503] = { title = "Blackfin's Booty", description = "<A torn page precedes the latest entry, which reads:>\n\nOur self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end.\n\nI can't take it anymore!\n\nI've buried the treasure and fed the map to Blackfin.\n\nThat should keep my cousin's grubby little mitts off of our precious heirlooms!", objectives = "You must slay the orca, Blackfin, to retrieve Gilblingle's Map.", progress = "You've discovered Gilblingle's family treasure!", completion = "This item was highly prized by the local gilblin population - even coveted by King Gurboggle, himself!" }
WordHunterWoW_QuestEN[25504] = { title = "Do Me a Favor?", description = "Hello there. Pleased to meet you! I'm Fizzle Brassbolts. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Jinky Twizzlefixxit in her shop, you'll be well on your way.", objectives = "Deliver the List of Parts to Jinky Twizzlefixxit at Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Is that the list of parts, finally? I've been waiting all day for that!", completion = "<Jinky eyes the list of parts and spits!>\n\nI don't have even half of that stuff!" }
WordHunterWoW_QuestEN[25505] = { title = "Do Me a Favor?", description = "Hey there, {name}. I'm Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Razzeric in his shop, you'll be well on your way.", objectives = "Deliver the List of Parts to Razzeric at Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Is that my list of parts from Pozzik?", completion = "Heya, pal, mind if I take a look at that list?\n\n<Razzeric nearly spits!>\n\nWhat's Pozzik thinking? He knows that I don't have even half of that stuff!" }
WordHunterWoW_QuestEN[25506] = { title = "Sea-Food Chain", description = "Our time here draws to a close.\n\nI must find my way across the chasm and discover the purpose behind the naga activities here.\n\nIf you are to follow me, you would be wise to conclude your search for a suitable mount first.\n\nSearch the area north of here and find a puffer hatchling. Once you've caught one, bring it to the trench to the west. I will prepare everything you need there.", objectives = "Find a Puffer Hatchling in Gnaws' Boneyard and bring it to the Abyss near the Holding Pens." }
WordHunterWoW_QuestEN[25507] = { title = "Hell's Shells", description = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer.\n\nNemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient.\n\nGo into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", objectives = "Use the Heap of Core Hound Innards near Nemesis to distract him. Collect a Nemesis Shell Fragment.", progress = "Nemesis is a molten ball of fury protected by a stony shell of pure hatred.\n\nHis time will come.", completion = "<The Arch Druid takes the shell from you with surprising reverence.>\n\nNemesis is an instrument of evil, but he was forged from a shell fragment of the true Ancient.\n\nWe will exploit this connection." }
WordHunterWoW_QuestEN[25508] = { title = "A Brilliant Idea", description = "I have a brilliant idea!\n\nLets stop the playthrough here.  There's not much more to see at the moment anyway.\n\nThanks for helping!", objectives = "I have a brilliant idea!\n\nLets stop the playthrough here. There's not much more to see at the moment anyway.\n\nThanks for helping!" }
WordHunterWoW_QuestEN[25509] = { title = "Physical Training: Forced Labor", description = "Training to join our ranks is not pleasant.  Why should it be?\n\nThe path to serve the Old Gods is long, painful, and soul-harrowing.  Consider this your first step.\n\nTake this pick and break the lodestone deposits found in the gorge.\n\nNo, we don't need any of the ore.  This is purely for your benefit.", objectives = "Break 5 Darkwhisper Lodestones.", completion = "Very well.  You're at least competent enough to figure out which way the pointy end of the pick goes." }
WordHunterWoW_QuestEN[25510] = { title = "Tortolla Speaks", description = "<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>\n\n{name}, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.\n\nDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient's trust. The fate of Hyjal hinges on this. ", objectives = "Go to Tortolla, the turtle ancient, at the Ashen Lake in Mount Hyjal.", completion = "<race>.\n\nThis tongue. Is not yours.\n\nWhat do you want ... tormentor?" }
WordHunterWoW_QuestEN[25513] = { title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Kelsey Steelspark, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", objectives = "Defeat Megs Dreadshredder.", progress = "Stop wasting my time. Enter and fight!", completion = "Fantastic. I might challenge you to a duel myself someday." }
WordHunterWoW_QuestEN[25514] = { title = "Breaking the Bonds", description = "From the deep...\nA realm of darkness and fire.\nGrasping in my slumber.\n\nI am ensnared, {race}.\n\nShadows lurk in the rods of fire beside me.\nSlay them.\nThat I may be free again.", objectives = "Disable the two Rods of Subjugation that bind Tortolla.", progress = "They are not of this world.\n\nThey know neither pity nor fear.", completion = "<Tortolla quivers and shakes debris free from his great back.>\n\nYou...\nAre not like the others.\n\nI am free once again.\n\nThe others...\nWill pay." }
WordHunterWoW_QuestEN[25515] = { title = "Down in the Deeps", description = "<Jinky rolls up her sleeves and slicks back her hair while eyeing you up and down.>\n\nFine, if Fizzle wants you to have your own boat, the first thing we'll need is parts. Guess who gets to go get them?\n\n<Jinky smiles as she points downward and then grabs you a spare diving helm and flippers.>\n\nThat's right, brother. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", objectives = "Collect 10 Rocket Car Parts.", progress = "I'm not punching the timecard on this one until you get me everything that's on that parts list.", completion = "This'll do for a start." }
WordHunterWoW_QuestEN[25516] = { title = "Down in the Deeps", description = "Well, friend, if Pozzik wants you to have your own boat, the first thing we're going to need is parts. Now guess who gets to go get them?\n\n<Razzeric smiles as he points downward and then grabs you a spare diving helm and flippers.>\n\nI'm afraid so, {name}. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", objectives = "Collect 10 Rocket Car Parts.", progress = "We can get started as soon as you get everything that's on the list.", completion = "This is a great start!" }
WordHunterWoW_QuestEN[25517] = { title = "Bar Fight!", description = "Those no-good, smelly, green in the gills goblins have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their insolence, {name}!", objectives = "Start a bar fight!", completion = "That's the spirit! You're a real credit to the Alliance!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!" }
WordHunterWoW_QuestEN[25518] = { title = "Bar Fight!", description = "Those pint-sized, goober-looking, no-explosion gnomes have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their arrogance, {name}!", objectives = "Start a bar fight!", completion = "Yes! You're a real credit to the Horde!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!" }
WordHunterWoW_QuestEN[25519] = { title = "Children of Tortolla", description = "My children.\nThey lie below.\nIn silt and sand.\n\nThe others corrupt them.\nDarken them within their shells.\n\nSlay the others.\nDestroy the corruptors.\nSave them...", objectives = "Slay 6 Deep Corruptors attacking Tortolla's Eggs in the Ashen Lake.", progress = "My children.\nTell me they will be born free...", completion = "<race>.\nYou are not like the others.\n\nBraver. Stronger.\nA part of this world...\n    and not the shadow that came before.\n\nThank you." }
WordHunterWoW_QuestEN[25520] = { title = "An Ancient Awakens", description = "I slumbered in the healing silt of Hyjal.\nI slept until the world broke open.\nWhen the others came, I was not ready.\n\nI am ready now, {race}.\n\nMy children and I. Slow to anger.\nBut our wrath is final.\n\nTell those who sent you that we are prepared for war.\n\nThe others will be cast from the mountain.", objectives = "Return to Arch Druid Hamuul Runetotem at the Sanctuary of Malorne in Hyjal.", completion = "<name>!\n\nYou were able to earn the ancient's trust?\n\nWonderful! We are one step closer to taking back this mountain..." }
WordHunterWoW_QuestEN[25521] = { title = "I'm With Scorpid", description = "You gotta help me, you just gotta! Chelsea and I came out here to make a bit of money, just sell some supplies, legit work. Next thing I know she's on her deathbed! She's got a fever that'd shock a blacksmith, and she's hallucinating...\n\nShe must've been stung by the scorpids near here! I've seen it happen, it's not pretty. I gotta get some poison glands to make an antidote but I can't leave her side!\n\nPlease, help me! Get me those glands!", objectives = "Collect 6 Duneclaw Stingers from Duneclaw Scorpids.", progress = "Do you have them? Oh, please...", completion = "Oh thank you, thank you! I know a bit of alchemy, I'm not totally useless. Here goes..." }
WordHunterWoW_QuestEN[25522] = { title = "Gargantapid", description = "No! It didn't work! I don't know what to do, unless...\n\nOh gosh, it's worse than I thought! She must've been stung by the one lurking in the cave. I saw it the first night we arrived. Claws the size of a goblin. A tail as tall as a tree! We shared hushed whispers of it around the campfire... we called it... GARGANTAPID!\n\n ...hey, are you laughing? Stop that! This is serious! Chelsea's life is on the line! Please, I'll make it worth your while...just bring me Gargantapid's poison gland!", objectives = "Collect Gargantapid's Stinger.", progress = "You're back! Do you have it?", completion = "I can't believe it! You're amazing! Here, please, take your reward, take anything you want! I've gotta save Chelsea!" }
WordHunterWoW_QuestEN[25523] = { title = "Flight in the Firelands", description = "{name}, our enemy is using this grotto in the Firelands to prepare an invasion. We're going to hit them hard right where they live.\n\nBut first, you'll need to get your wings. Flight in the Firelands does not work as it does in the outside world. Something about the dense, superheated air. You'll need some practice!\n\nGet a Twilight Firelance from the rack behind me, equip it, then mount one of Aviana's Guardians. Practice flying - flap your wings! Visit a flag placed on the ledge below and return. ", objectives = "Get and equip a Twilight Firelance using the rack behind Farden. Mount one of Aviana's Guardians and fly her to the Guardian Flag on the ledge below. Press the flap button to flap your mount's wings!", progress = "Do you feel comfortable flying yet?", completion = "Well done! How does it feel?\n\nIt is challenging to master flight in this burning wasteland, but it is the only way.\n\nI hope you're ready for battle, <name>..." }
WordHunterWoW_QuestEN[25524] = { title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those Southsea treasure hunters has got to have a crowbar!", objectives = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", progress = "Oh, for the love of the Light, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove...." }
WordHunterWoW_QuestEN[25525] = { title = "Wave One", description = "Here they come, {name}! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!\n\nTake wing once more, {class}, and slay them.\n\nRun into enemy riders with your lance to destroy them.\n\nGo forth. Fly, fool. Fly!", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Knight Riders by flying into them. Press the flap button to flap your mount's wings!", progress = "Flap! Flap I say... FLAP!", completion = "Spectacular flying, <name>! Their screeches of anguish echoed about this light-forsaken cavern.\n\nBut our work is not yet finished..." }
WordHunterWoW_QuestEN[25526] = { title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those filthy Southsea treasure hunters has got to have a crowbar!", objectives = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", progress = "Oh, for the love of profit, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove...." }
WordHunterWoW_QuestEN[25527] = { title = "A Replacement Diving Helm", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[25528] = { title = "A Replacement Diving Helm", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[25529] = { title = "A Replacement Diving Helm", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[25530] = { title = "A Replacement Diving Helm", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[25531] = { title = "Twilight Riot", description = "I thank you for freeing me.  Let us take advantage of the distraction you've created and get out of here.\n\nWe must hurry before the cultists catch on.\n\nMeet me again when we've left this place.", objectives = "Speak to Jarod Shadowsong at the Gates of Sothann in Hyjal.", completion = "You have my thanks, <name>." }
WordHunterWoW_QuestEN[25532] = { title = "Pirate Accuracy Increasing", description = "I don't know if you've noticed, but the cannonballs are hitting us. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Go talk to Mazzer Stripscrew.\n\nPut those fires out!", objectives = "Get a River Boat from Mazzer Stripscrew and then use the Frost Cannon to extinguish 15 fires." }
WordHunterWoW_QuestEN[25533] = { title = "Pirate Accuracy Increasing", description = "Oh no, {name}, the cannonballs are hitting the Speedbarge. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Please, go speak with Griznak.\n\nExtinguish those fires!", objectives = "Get a River Boat from Griznak and then use the Frost Cannon to extinguish 15 fires." }
WordHunterWoW_QuestEN[25534] = { title = "Going Off-Task", description = "As you may have seen, the ship docked to the north has its cannons blazing. While it's pretty fun watching the gnomes run face-first into a hail of iron, my bruisers keep doing it too, and it's absolutely killing my overhead expenses.\n\nI'd like you to try and dance through the cannonfire, get on that ship, and kill the taskmaster leading the cannoneers. The rest of the crew is probably a bunch of spineless prats; once he's down, we should be good.", objectives = "Kill the Southsea Taskmaster.", completion = "Nice work, kid. Any close calls? Did you get grazed?\n\nNo? Good, because we've got more fish to fry here." }
WordHunterWoW_QuestEN[25535] = { title = "A Powerful Need To Eat", description = "Poor things. They're starving.\n\nWe've many matters to attend to, not the least of them the naga, but first we need to get some food in these bellies. I'm not sure what the naga fed them up in that shell, if anything, but they're definitely worse for the wear.\n\nQuite a few of the survivors have made their way into Glimmerdeep Gorge, to the northwest. Go join them and help out. With a bit of clam meat, we can get these survivors back on their feet.", objectives = "Speak to Divemaster Birmingham in Glimmerdeep Gorge.", completion = "More help! Superb! We can certainly use it, I'll tell you that much." }
WordHunterWoW_QuestEN[25536] = { title = "Cold Welcome", description = "Many of the survivors made their way down into Glimmerdeep Gorge to help with the clam diving. We've been receiving reports back of deliberate attacks from some kind of murlocs down there.\n\nThe Admiral has to stay here as more men report in from the shell, so I'm having trouble convincing him to get any significant muscle to help the divers. If you'd be up for it, I'm certain they could use your help.\n\nCome back and let me know if you get the situation under control.", objectives = "Kill 10 Glimmerdeep Tidehunters.", completion = "Thank you for stepping up to take care of this, <class>. I know there are a lot of concerns swarming us right now, but maintaining the safety of the survivors is paramount." }
WordHunterWoW_QuestEN[25537] = { title = "Art of Attraction", description = "I have an idea. A brilliant idea! Those clown-looking fish have developed a symbiotic defensive relationship with the anemones. Having dismissed anemone disguise plausibilities, I've uncovered the chemical attractor that lures the fish.\n\nI have a gyrocoptic thermascrub extractor that I've brought down to take samples. Use it to extract the chemical attractor from several of the anemones, then bring the samples back to me for rapid synthesis and deployment.\n\nGo with haste! Brilliance is waiting!", objectives = "Use the Anemone Chemical Extraction Device to gather 8 Anemone Chemical Samples from the red anemones along the walls of Glimmerdeep Gorge.", completion = "Superb! Chemicals abound!\n\nMy instantaneous chemical synthesizer is already pre-tested and prepared. Your deployment compound shall be ready in the blink of an eye!" }
WordHunterWoW_QuestEN[25538] = { title = "Odor Coater", description = "Marvelous creation if I do say so myself. Ready for deployment.\n\nSimply spray the clam divers with a bit of the chemical and they shall soon be accompanied by a protective aquatic companion. You can even spray yourself to similar effect if you so desire.\n\nSpeaking of desire, I would highly recommend that you moderate deployment of the chemical attractor to minimal applications. Large doses could result in undesirable effects...\n\nUndesirable for you anyway. Likely very desirable for the fish.\n\nAway!", objectives = "Apply the Anemone Chemical Application Device to 8 Clam Divers.", progress = "Fishy companions for all!", completion = "Well done my odorific associate. You are both swift and assiduous, if I do say so myself. May your future travels be rampant with inspiration and opulence." }
WordHunterWoW_QuestEN[25539] = { title = "Clamming Up", description = "Here to help with the clam diving?\n\nGet to it then. There are clams about everywhere just waiting to be dived.", objectives = "Gather 16 Glimmerdeep Clams.", progress = "Has your clam-laden frolic proved fruitful?", completion = "Well done, indeed. This is an entirely unshameful amount of clams to have gathered. The survivors back at the cave will surely be grateful." }
WordHunterWoW_QuestEN[25540] = { title = "Bellies Await", description = "We have quite a stock of gathered clams to tote back to the cave, I was simply awaiting someone to do the toting. You've proven dangerous enough to be the sort.\n\nI highly expect that such a fine meal shall not pass uncontested by predators on the way back, so I'd make your trip as swift as possible.\n\nThank you for your help, friend. It's been a pleasure.", objectives = "Bring the Hefty Sack Of Clams back to the Tranquil Wash.", progress = "You look to have come back to us with purpose. Was your trip successful?", completion = "This is wonderful. I will begin cooking them immediately. It is good to know that of our many fears, starvation shall no longer need to be one of them.\n\nI imagine the Admiral will have much work for you. Let me trouble you no further for a while." }
WordHunterWoW_QuestEN[25541] = { title = "Filling Our Pockets", description = "We've looted everything that isn't bolted down around here, but I'm not done yet. If we're bothering to do the Steamwheedle Cartel's dirty work for them, we're going to make as much cash as we can while we're here.\n\nI haven't seen many earrings on these pirates, so the gold must be in the next best place...their teeth. The Southsea musketeers and strongarms to the south are the higher-ups here; they'll be the ones with the adornment. Bring me back a good fistful of gold fillings.", objectives = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", progress = "Don't get squeamish on me now.", completion = "Nice!  Remember, gold is gold, no matter who's mouth, nose, or otherwise it's been in.\n\nIt's all perfectly sanitary after being melted down anyway. Or at least wiped off." }
WordHunterWoW_QuestEN[25542] = { title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", objectives = "Sink 15 Southsea Rowboats.", completion = "You did it! You did it!\n\n<Jinky grabs you and gives you a big smooch on the cheek! She then regains her dignity and smooths her clothes.>\n\nThanks for saving my Speedbarge, Captain <name>." }
WordHunterWoW_QuestEN[25543] = { title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", objectives = "Sink 15 Southsea Rowboats.", completion = "You saved my Speedbarge!\n\n<Razzeric embraces you in a manly hug!>\n\nI can't begin to tell you how relieved I am, Captain <name>!" }
WordHunterWoW_QuestEN[25544] = { title = "Wave Two", description = "You've stirred up the hornets, {name}. The ceiling is coming down on us! And their strongest fighters are taking wing on creatures warped and twisted by this world of flame.\n\nGet back out there and take them down! Watch out for flaming boulders.", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings!", progress = "FLAP! For the love of all things merciful, flap. Flap harder!", completion = "By the wings of Aviana - you were born to fly, <name>!\n\nQuickly, let's get back out there and hit them again..." }
WordHunterWoW_QuestEN[25545] = { title = "To Arms!", description = "As we struggled not to drown, my men and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I'm inclined to believe him.\n\nIf we're going to stand a chance, we'll need your help to recover our lost armaments. They should be lying on the sea floor near our shipwrecks.\n\nHurry, {race}, we're defenseless here.", objectives = "Gather 4 Stormwind Spears, 4 Stormwind Breastplates, 4 Stormwind Shields and 4 Stormwind Helms.\n\nThe equipment may also be collected from Gliblin Scavengers.", progress = "Have you recovered our gear, <race>?", completion = "Well done, <class>!\n\nThanks to you, my men will be ready to confront the enemy when they attack." }
WordHunterWoW_QuestEN[25546] = { title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these men ready for battle.\n\nAny decent leader knows that his men travel and fight on their stomachs. No food, no victory.\n\nThese soldiers are weak from their recent ordeal. They'll need sustenance if they're to put up any kind of fight when the need arises.\n\nSpeaking of traveling on stomachs, I've seen several crabs out there on the sea floor....", objectives = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", progress = "Were you able to find anything for my men and I to eat, <class>?", completion = "This should help relieve our exhaustion.\n\nAgain, we thank you." }
WordHunterWoW_QuestEN[25547] = { title = "On Our Own Terms", description = "We're as ready as we'll ever be. No sense waiting around for the naga to find us.\n\nI'll address the men, then we'll meet the enemy on our own terms and let fate decide the outcome.", objectives = "Speak to Captain Taylor in the Briny Cutter.", completion = "No time to address the troops now.\n\nJust as well. They know what must be done." }
WordHunterWoW_QuestEN[25548] = { title = "Might of the Firelord", description = "I've been charged with leading our military operations against the enemy.  A humbling task when you consider there are demigods walking among us.\n\nI'm going to have you carry out a series of hit-and-run attacks behind enemy lines.  It will be important that you keep the enemy off guard and weaken their numbers ahead of our main force's attack.\n\nYour first target will be the Ascendant's Rise, where the most highly trained Twilight's Hammer devotees have achieved a partial elemental state.", objectives = "Slay 4 Flame Ascendants and 5 Twilight Subjugators at the Ascendant's Rise in Hyjal.", completion = "You did well, <name>.  I've a new target for you." }
WordHunterWoW_QuestEN[25549] = { title = "The Sanctum of the Prophets", description = "The mad prophets of the Twilight's Hammer congregate in the area just north of the Ascendant's Rise.\n\nIt is said that their dark visions are granted to them directly by the Old Gods.  Whether or not that is true, they provide tremendous spiritual guidance to the cult.  Attacking the Sanctum of the Prophets will deal a devastating blow to the enemy's morale and if we're lucky you might run into one of the Firelord's own emissaries while you're there.", objectives = "Slay 4 Twilight Augurs, 4 Twilight Retainers and 1 Emissary of Flame at the Sanctum of the Prophets.", completion = "You continue to prove your prowess, <name>.  At this rate Hyjal might survive this ordeal after all." }
WordHunterWoW_QuestEN[25550] = { title = "Magma Monarch", description = "The magma giants who serve Ragnaros are kept in line by their king's heavy-handed rule.  Were we to take care of him, the rest will surely fall into disarray.\n\nWithout the giants, the fight on the ground will get a lot more even.  Perhaps even tilt to our favor.\n\nBut felling the magma monarch will be no easy task.  Use these drums to enlist the help of the great Tortolla who is capable of holding off King Moltron for an eternity.  But holding him off won't be enough -- and that's where you come in.", objectives = "Use the Drums of the Turtle God to help you defeat King Moltron.", completion = "Excellent work, <name>.  We shall soon claim victory in Hyjal.\n\nIt has been an honor to fight along your side." }
WordHunterWoW_QuestEN[25551] = { title = "The Firelord", description = "With his gatekeeper gone, you've given the Guardians of Hyjal access to Sulfuron Spire.\n\nRagnaros will have no choice but to defend the main entryway to the Firelands himself.\n\nGo through the Twilight's Hammer portal at the Sanctum of the Prophets and meet me inside.  Malfurion and Hamuul will also aid us while the others continue to fight the enemy outside.", objectives = "Go through the portal at the Sanctum of the Prophets and aid Cenarius in defeating Ragnaros.", progress = "Yes, <name>?", completion = "Hyjal has been saved, <name>.  And it's all thanks to you." }
WordHunterWoW_QuestEN[25552] = { title = "Brood of Evil", description = "This egg you recovered is an alarming sign, {name}.  The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic.\n\nThis \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother.  We must destroy her before her brood spreads.\n\nGo to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes.  We will use its skull to lure out its mother.", objectives = "Obtain a Young Twilight Drake's Skull at the Ascendant's Rise in Hyjal.", progress = "You've returned, <race>.", completion = "You've done well, <name>.  We will use this to draw out the Twilight matriarch." }
WordHunterWoW_QuestEN[25553] = { title = "Death to the Broodmother", description = "We've located the matriarch's feeding grounds south of the Ascendant's Rise.\n\nShe will be extremely angry to have lost one of her drakes.  Place the skull there near the carcasses she devours.  If she's anywhere in the vicinity, she will come out and attempt to exact revenge.\n\nWe will have a surprise waiting for her.", objectives = "Place the Twilight Drake Skull at the feeding grounds south of the Ascendant's Rise and slay Desperiona.", completion = "That went... better than expected." }
WordHunterWoW_QuestEN[25554] = { title = "Secrets of the Flame", description = "If we are to banish Ragnaros back into the Firelands, we will need to gain access to Sulfuron Spire.\n\nOnly the most trusted members of the Twilight's Hammer will have been entrusted with such valuable information.\n\nGo search the Ascendant's Rise for any written tomes you might find.  Foul as they are, we cannot waste the opportunity to learn about our enemy's weaknesses.", objectives = "Obtain the Ascendant's Codex, the Burning Litanies and the Tome of Flame at the Ascendant's Rise in Hyjal.", progress = "Did you succeed in your task, <name>?", completion = "These foul books should not be allowed to exist.  Yet the information inside them is of vital importance." }
WordHunterWoW_QuestEN[25555] = { title = "The Gatekeeper", description = "According to these tomes, one of Ragnaros' most powerful lieutenants serves as the sole gatekeeper to Sulfuron Spire.\n\nYou won't be able to defeat him alone.\n\nSound this horn when you engage in combat with Azralon and any of our forces in the vicinity will come to your aid.\n\nYou must hurry, {name}.  It won't be long before the Firelord realizes what we're up to.", objectives = "Use the Horn of Cenarius to help you slay Azralon the Gatekeeper.", progress = "You've returned, <name>?", completion = "It is done.  Only the final step in your mission remains." }
WordHunterWoW_QuestEN[25556] = { title = "Into Zul'Farrak", description = "That foul traitor...I should've known better than to trust his kind. My hunt for Sul'thraze has blinded me.\n\nForgive me, {name}. Mazoga has fled inside of Zul'Farrak, the heart of the Sandfury civilization.\n\nIf you truly seek the sword, you must pursue him. Do not go alone; the entirety of the Sandfury tribe lies in wait behind those walls, and they will not welcome you.\n\nI will stay here. My search for the blade must end. Should you find it, keep it; I must give up before I am consumed.", objectives = "Find Mazoga within Zul'Farrak.", completion = "<Mazoga's ghost gives you a blood-smeared grin.>\n\nHow you doin', mon?" }
WordHunterWoW_QuestEN[25557] = { title = "Chief Ukorz", description = "Take a good look, mon. This is how it goes, betrayal after betrayal. I backstab you for the sword, and then Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in there anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of us in here deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?You will receive:", objectives = "Kill Chief Ukorz Sandscalp." }
WordHunterWoW_QuestEN[25558] = { title = "All or Nothing", description = "This is it.\n\nThis is where we make our stand.\n\nWe must defend this ship to our last breath, and make these cretins think twice before approaching it again!\n\nMay our blades strike fear in their hearts!", objectives = "Assist Captain Taylor in the defense of The Briny Cutter.", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many." }
WordHunterWoW_QuestEN[25559] = { title = "Laying Claim", description = "We're not the only ones interested in these ruins, it seem. Of all things, we've got blood elves after our dig sites.\n\nI'd expect them to wilt in the heat without all their fancy fountains and cushy pillows, but they're surprisingly scrappy, and they're trying to drive us out of the Southmoon Ruins by force.\n\nIt's time to crack a few heads. Head over there and teach those elves not to mess with us!", objectives = "Kill 10 Blood Elf Ruins Hunters.", completion = "That'll teach the Horde twofold! Don't mess with dwarven history, and don't send a bunch of frail couch-dwellers to do your fighting!" }
WordHunterWoW_QuestEN[25560] = { title = "Egg Wave", description = "Without any defenders, the Firelands eggs are vulnerable.\n\nTake wing once more and smash those eggs! Simply rush over them to crush them. Search all the nooks, crannies, and side-caves. Hurry! ", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Smash 40 Firelands Eggs by running over them. Press the flap button to flap your mount's wings!", completion = "A decisive blow!" }
WordHunterWoW_QuestEN[25561] = { title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Mazzer Stripscrew and get on your boat. Use the cannon to sink them before it's too late!", objectives = "Sink 15 Southsea Rowboats.", completion = "You did it! You did it!\n\n<Jinky grabs you and gives you a big smooch on the cheek! She then regains her dignity and smooths her clothes.>\n\nThanks for saving my Speedbarge, Captain <name>." }
WordHunterWoW_QuestEN[25562] = { title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Griznak and get on your boat. Use the cannon to sink them before it's too late!", objectives = "Sink 15 Southsea Rowboats.", completion = "You saved my Speedbarge!\n\n<Razzeric embraces you in a manly hug!>\n\nI can't begin to tell you how relieved I am, Captain <name>!" }
WordHunterWoW_QuestEN[25563] = { title = "Hammering It Out", description = "The rift that was here left behind this strange device, but why?\n\nSomeone in a capital city may have more information.", objectives = "Take the Mysterious Device to Stormwind, Ironforge, Exodar or Darnassus and show it to an Earthen Ring Representative.\n\nProvided item:", progress = "What's this then?  Another device?", completion = "Not another one! <name>, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
WordHunterWoW_QuestEN[25564] = { title = "Stormwind Elite Aquatic and Land Forces", description = "You've done us a great service, {class}, so I'm going to let you in on a little secret. The men you've saved today aren't your everyday Stormwind troops.\n\nWe belong to a special detachment of elite soldiers sent here not only to contend with the Horde, but to investigate the massive geological disturbances originating from the nearby sea floor.\n\nI tell you this because our top secret equipment lies in the bottom of some of our wrecked ships here.\n\nThat gear must be retrieved!", objectives = "Find 6 Stormwind SEAL Equipment.", progress = "Were you able to secure that equipment, <class>?", completion = "Everything here seems to be in working order." }
WordHunterWoW_QuestEN[25565] = { title = "Fragments of Language", description = "We've had our first big find in years here at the Southmoon ruins. My lads have dug up stone tablets, engraved with ancient writings.\n\nThe glyphs on the tablets are like nothing we've ever seen, but I have a hunch we can connect them with titanic scripts found at other digsites. Imagine what a breakthrough like that could mean!\n\n I need you to go to the Southmoon ruins and help us collect the tablets; the other lads can't leave, lest the blood elves take our site!", objectives = "Collect 5 Ancient Hieroglyphs.", progress = "Do you have the tablets?", completion = "Would you take a look at these...not troll, not qiraji, just pure mystery waiting to be unlocked.\n\nThese aren't going anywhere now that they're safely in our hands. It's time to make our way into the ruins!" }
WordHunterWoW_QuestEN[25566] = { title = "The Secrets of Uldum", description = "I studied these ruins for years trying to find a way in. We even took a good chunk out of the gate, only to find impenetrable walls beneath. Now the cataclysm may've wrecked everything in there something fierce, but it's done what we couldn't and opened a way in!\n\nI'd like you to have the honor, lad. Head on in there and see if anything's been left uncracked. Be careful though... there's no telling what, or who, might be stirring in there.", objectives = "Search the Antechamber of Uldum for an intact artifact.", completion = "This chest lies undisturbed, sealed for thousands of years." }
WordHunterWoW_QuestEN[25567] = { title = "Hammering It Out", description = "", objectives = "What's this then?  Another device?\n\nProvided item:", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! <name>, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
WordHunterWoW_QuestEN[25568] = { title = "Hammering It Out", description = "", objectives = "What's this then?  Another device?\n\nProvided item:", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! <name>, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
