WordHunterWoW_QuestEN[25788] = { title = "Hammering It Out", description = "", objectives = "Provided item:" }
WordHunterWoW_QuestEN[25789] = { title = "Hammering It Out", description = "The rift that was here left behind this strange device, but why?\n\nSomeone in a capital city may have more information.", objectives = "Take the Mysterious Device to Orgrimmar, Undercity, Silvermoon City or Thunder Bluff and show it to an Earthen Ring Representative.", progress = "What's this then?  Another device?", completion = "Not another one! <name>, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, bring them to me or one of my associates. We need to learn more about what's behind this attack." }
WordHunterWoW_QuestEN[25790] = { title = "Back to Crazzle", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", objectives = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!" }
WordHunterWoW_QuestEN[25791] = { title = "Back to Riznek", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", objectives = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!" }
WordHunterWoW_QuestEN[25792] = { title = "Pushing Forward", description = "Most of the mountaineers and steam tanks in Dun Morogh are battling along the Frostmane Front, which is approaching us from the southeast. We can barely hold the trolls back, let alone advance into their village and take on their leader.\n\nThey've blocked our path of approach with mysterious totems that choke mountaineers who come in range, leaving the victims helpless against their enemies. This stone is inscribed with a rune of fire; it should be able to destroy the totems and free our mountaineers.", objectives = "Use the Rune of Fire to destroy 4 Constriction Totems in the Frostmane Front.", progress = "Was the rune able to destroy the totems? Were we too late?", completion = "Finally, some good news from the Frostmane Front. I'll have the mountaineers press their attack immediately. Now, we must signal our gnomish allies at Steelgrill to start their advance." }
WordHunterWoW_QuestEN[25793] = { title = "The Deep Reaches", description = "The purpose of this base was to establish a foothold in Stonetalon for Theramore and to open up a supply line to the night elves. The Horde, unfortunately, has given us one hell of a fight. Hellscream's armies are mighty and unrelenting. I haven't seen this type of ferocity from the Horde since the second war.\n\nNow it would appear that the mine the Explorers' League dug out is being used by the Horde to \"backdoor\" us. We need to seal that thing off!", objectives = "Speak to Steeltoe McGee at the Deep Reaches in Stonetalon Mountains.", completion = "Seal it off? That's gonna take some work, friend." }
WordHunterWoW_QuestEN[25794] = { title = "Undersea Sanctuary", description = "I believe I've located the author of your note, friend.\n\nIt would seem that he is in desperate need of attention if he is to survive.\n\nI shall attune one of my scrying orbs, that you might see him for yourself.", objectives = "Use Erunak's Scrying Orb to view the location of Deepmist Grotto.", progress = "Have you familiarized yourself with the cavern's location, <name>?", completion = "We must make haste!\n\nAs you can surely see, his time is not long." }
WordHunterWoW_QuestEN[25795] = { title = "Return to the Shrine", description = "Aviana's Egg should have arrived safely back at the Shrine. You should go check on it! Choluna should know how to handle this.\n\nI'll finish the last of our business here and catch up with you later.", objectives = "Return to Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "<name>! Is it true you led an assault against a twilight dragon?\n\nYou are truly a herald of the ancients!" }
WordHunterWoW_QuestEN[25796] = { title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", objectives = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader." }
WordHunterWoW_QuestEN[25797] = { title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", objectives = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader." }
WordHunterWoW_QuestEN[25798] = { title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", objectives = "Defend the Oil Drilling Rig.", progress = "How much oil did you get?", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff." }
WordHunterWoW_QuestEN[25799] = { title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", objectives = "Defend the Oil Drilling Rig.", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff." }
WordHunterWoW_QuestEN[25800] = { title = "When Life Gives You Crabs", description = "There's a lot to do here, {class}, but we need to keep an eye out for the gifts of fate.\n\nWhen the flood rolled in, right over our houses, it swept a good number of ocean dwellers with it. Menethil Bay's full of crabs now, large and ripe for the picking.\n\nWhen life gives you crabs, go crab fishing, I say. Bring me back the largest, meatiest claws you can find and I'll pay you.", objectives = "Collect 5 Meaty Crawler Claws from Harbor Crawlers.", progress = "Don't bother with the smaller claws, they're more work to shell than the meat's worth.", completion = "A hearty seafood dinner will lift everyone's spirits and help us get the town back in shape again. Thanks for the help, <name>." }
WordHunterWoW_QuestEN[25801] = { title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", objectives = "Collect Gobbler's Head from Gobbler and slay 12 Bluegill Murlocs of any kind.", progress = "Our merchants will not be safe until we are rid of Gobbler and those murlocs.", completion = "Ah, well done <name>.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines." }
WordHunterWoW_QuestEN[25802] = { title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil statuette and return it to me.", objectives = "Search the crates and barrels at the coastal Murloc camps.", completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles." }
WordHunterWoW_QuestEN[25803] = { title = "The Search Continues", description = "You thoroughly search this cluster of murloc hovels, and find no trace of the Menethil statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", objectives = "Search for the Menethil Statuette.", completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!" }
WordHunterWoW_QuestEN[25804] = { title = "Search More Hovels", description = "This grouping of murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil statuette!", objectives = "Continue searching the Murloc hovels for the Menethil Statuette.", completion = "This barrel is halfway buried amidst the mud and grass ..." }
WordHunterWoW_QuestEN[25805] = { title = "Return the Statuette", description = "<After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired paladin with hammer upraised.\n\nThis must be the Menethil statuette! You must now return it to Karl Boran in Menethil Harbor.>", objectives = "Bring the Menethil Statuette to Karl Boran at Menethil Harbor.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You've well earned this payment for services rendered.\n\nIt's good to see dependable folk like you, especially in trying times such as these." }
WordHunterWoW_QuestEN[25806] = { title = "They Put the Assass in... Never Mind", description = "Ah, the Explorers' League - such a profound group of morons. Not only do we have tauren ghosts up our butts, the Explorers' League has also managed to open up a backdoor to the primary Horde base in Stonetalon, Krom'gar Fortress.\n\nNow we've got Krom'gar assassins silently executing everyone in the mine.\n\nI need you to head in there and clean house.\n\nI almost forgot to give you these goggles. Put them on immediately. They'll make all the stealthed assassins in the mine plainly visible.", objectives = "Kill 12 Krom'gar Assassins.", completion = "<The Gnomecorder buzzes and whirs.>\n\nHey, this thing on?\n\n<You hear a tapping sound.>\n\nAnybody there?" }
WordHunterWoW_QuestEN[25807] = { title = "An Ancient Reborn", description = "I'm convinced that YOU are the herald of Aviana, {name}. It was you who first saw her and rescued her essence from the claws of a dragon.\n\nYes, I believe Aviana is to be reborn into our world. And you shall have the honor of ushering her over the threshold.\n\nTake this incense and burn it before Aviana's egg in the room just above me.\n\nThe ancient awaits, {name}. Our deliverance is here!", objectives = "Use the Herald's Incense before Aviana's Egg at the Shrine of Aviana.", completion = "I ... live.\n\nThose that tried to corrupt me and kidnap my children will soon feel the rake of my talons, <class>. Believe it.\n\nContinue to push forward across Hyjal. I will collect myself and assemble with the other Ancients." }
WordHunterWoW_QuestEN[25808] = { title = "Is This Thing On?", description = "<The Gnomecorder crackles with energy. You can hear Lieutenant Paulson on the other end.>\n\nStupid gnome junk... Is ANYBODY there? {name}, are you there?\n\nMaybe he's dead.\n\nListen, if you can still hear me, we just got word that a Horde master assassin is in the mines, directing the other assassins. Find her, kill her, report back to me.\n\nPaulson, out.", objectives = "Kill Master Assassin Kel'istra.", completion = "Nicely done, <name>! You worked the mines like a pro. Now how about returning my goggles." }
WordHunterWoW_QuestEN[25809] = { title = "Leave No Man Behind!", description = "Horde monsters!\n\n<Corporal Wocard spits.>\n\nLook at this place! They've wiped out innocents! Civilians!\n\nListen, {name}, you've got to help us. Go into the Deep Reaches and look for surviving miners. If any are still alive they're probably scared witless! Check in the nooks and crannies of the mine. Maybe in mine carts! There are bound to be some left alive and in hiding.", objectives = "Rescue 8 Frightened Miners.", completion = "Thank the Light! You truly are a righteous instrument of power! The Alliance is lucky to you have, <name>." }
WordHunterWoW_QuestEN[25810] = { title = "The Hatchery Must Burn", description = "{name}! Choluna spoke true: the goddess has returned! A miracle in our midst.\n\nWhile you were able to kill the twilight dragon Sethria, we have not yet located all of the eggs that the harpies had delivered to her. Thisalee and I have tracked them to a great hatchery constructed within the Firelands. It is not of this realm, so Aviana cannot accompany you.\n\nFly south and enter the flamegate in the center of the valley. Farden Talonshrike has been sent ahead and will be waiting for you within.", objectives = "Travel through the flamegate in the center of the Flamewake in Mount Hyjal. Speak with Farden Talonshrike once you are inside.", completion = "So it's true - Aviana has returned, with you as her herald.\n\nThere's much to be done here. We are deep in the heart of the Firelands. Sethria smuggled stolen eggs from Mount Hyjal here to hatch her own hideous creations - birds of prey, trained for war.\n\nI hope you're ready to fight back!" }
WordHunterWoW_QuestEN[25811] = { title = "Shuttin Her Down", description = "To bring this mine down you're gonna need to blow up her support beams. I can provide you with the explosives you'll need, but you're gonna have to trudge through Krom'gar assassins to get to all of the beams.\n\nThe good news, if any exists, is that we always mark our support beams with a big 'X.' Look for the markers and plant this dynamite near 'em. Once you've planted all the dynamite come on back up here and I'll activate the explosives.\n\nKaboom!", objectives = "Plant the Dynamite Bundle at the First Beam, Second Beam, Third Beam and Fourth Beam.", completion = "Here goes nothin'!" }
WordHunterWoW_QuestEN[25812] = { title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", objectives = "Speak to Private Pollard in Deepmist Grotto.", completion = "A... a <race>? Here?\n\nI must be mad..." }
WordHunterWoW_QuestEN[25813] = { title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", objectives = "Slay Whrrrl.", progress = "It's simple really... you blow the horn, their elemental leader shows up, and you kill it.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!" }
WordHunterWoW_QuestEN[25814] = { title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", objectives = "Slay Whrrrl.", progress = "It's simple really... you blow the horn, their elemental leader shows up, and you kill it.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!" }
WordHunterWoW_QuestEN[25815] = { title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked by red dragons.  Dragons controlled by orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Bring me my mead, {class}. It's down in the cellar of the inn. As far away as I put it from me, I can't go without it in the end.", objectives = "Obtain Fitzsimmons' Mead from the cellar of the inn in Menethil Harbor.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!" }
WordHunterWoW_QuestEN[25816] = { title = "Cursed to Roam", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north. On one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nI'm haunted by them day and night. First Mate Snellig calls for me! He's supposed to be dead! Please, {name}, look for him near the shipwrecks and just...tell him to leave me alone!", objectives = "Talk to the ghost of First Mate Snellig.", completion = "Fitzsimmons sent you, didn't he? It's been so long..." }
WordHunterWoW_QuestEN[25817] = { title = "The Cursed Crew", description = "The sailors of the Third Fleet are damned, forever cursed to wander these shores in agony. Fitzsimmons' anguish is tied to us; so long as we suffer, there can be no rest for him, either.\n\nYou must end the suffering of my crewmates' spirits. Purge their ghosts from this plane, and return to me.", objectives = "Kill 5 Cursed Sailors and 5 Cursed Marines in The Lost Fleet.", progress = "Be thorough in your task, lest the curse take hold of ye as well.", completion = "The cries of anguish have been stifled...but the source of the curse still lurks." }
WordHunterWoW_QuestEN[25818] = { title = "Lifting the Curse", description = "To break the curse, there must be a reckoning. Captain Halyndor damned us all to covet a forbidden artifact; the Eye of Paleth. His spirit still covets it, standing guard over the strongbox of his old ship, the Intrepid.\n\nVanquish the soul of the one who cursed us so, {class}. Defeat the Captain, claim his key, and spirit the Eye of Paleth far from this place.", objectives = "Get the Intrepid Strongbox Key from Captain Halyndor.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly." }
WordHunterWoW_QuestEN[25819] = { title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light. This must be the foul Eye of Paleth that damned these sailors' souls.\n\nSuch corruption should be purged. Perhaps a priest in Menethil Harbor could help you.", objectives = "Bring the Cursed Eye of Paleth to Glorin Steelbrow at Menethil Harbor in Wetlands.", progress = "How can I help you, lad?", completion = "The Eye of Paleth? You say Fitzsimmons sent you out?\n\nBy the light...not again. Fitzsimmons is dead, lad. You've not the first to come to me like this, either." }
WordHunterWoW_QuestEN[25820] = { title = "A Mother's Worries", description = "My son Gimlok's the light of my life. It warms my heart to see him playin' with the other children.\n\nI can't help but worry, though. There's sharks not but a few feet away in the bay. If it's deep enough for one to swim its way here...\n\nI can't bear it! Please, you're clearly one {race} that's seen tougher situations than us townsfolk. Would you get rid of those nasty sharks for me? At least a few?", objectives = "Kill 10 Harbor Shredfins.", completion = "Oh, bless your heart, to do such a thing for a married woman like me. You're too kind." }
WordHunterWoW_QuestEN[25821] = { title = "A Special Kind of Job", description = "You've done an admirable job down here, {name}. Force Commander Valen has taken notice and requested that you see him immediately. He's got a special mission lined up for you - one that'll hopefully put a cold stop on the Horde's incursion into Stonetalon.", objectives = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "I knew that you'd be a special snowflake when I first set my eyes upon you, <name>. So special, in fact, that I'd trust no one else here with what I'm about to ask of you." }
WordHunterWoW_QuestEN[25822] = { title = "Armaments for War", description = "I am going to need to put you in harm's way once more, {name}. To the east you will find a mineral rich excavation site that was recently overrun by the Horde. At that site are crates of our weaponry, scattered about all over the place. The Horde has only recently taken over, so it is unlikely that they've found all of our supplies.\n\nGet in there and get our Grimtotem friends some weapons!", objectives = "Collect 10 Alliance Weapon Crates.", progress = "Have you gathered the armaments of war?", completion = "This should be enough to supply a hundred Grimtotem! Now to present the weaponry to their chieftain." }
WordHunterWoW_QuestEN[25823] = { title = "The Unrelenting Horde", description = "While it is of utmost importance that you secure weapon crates immediately, we need the Unearthed Grounds to the east clear of Horde. If we are to open a supply line for our Grimtotem allies, we're going to need full access to the dig site.\n\nKill all Horde that you come across at the Unearthed Grounds, {name}. For the glory of the Alliance!", objectives = "Slay 12 Horde enemies at the Unearthed Grounds.", completion = "I will call for the infantry to move in and clear up whatever might be left over. If only we had ten-thousand more like you, <name>!" }
WordHunterWoW_QuestEN[25824] = { title = "Debriefing", description = "This soldier was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", objectives = "Speak to Private Pollard and learn about his ordeal.", completion = "Well, it's not encouraging, but it's something..." }
WordHunterWoW_QuestEN[25825] = { title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Fizzle on the Speedbarge, and let him know the good news!", objectives = "Deliver the Barrel of Oil to Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "What's this? Is that oil?!", completion = "It is oil! You're really proving yourself to be invaluable, <name>!\n\nToo bad I'm going to have to send you off now." }
WordHunterWoW_QuestEN[25826] = { title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Pozzik on the Speedbarge, and let him know the good news!", objectives = "Deliver the Barrel of Oil to Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Hello again, friend. Is that oil?!", completion = "It is oil! You're the best, <name>!\n\nToo bad I'm going to have to send you off now." }
WordHunterWoW_QuestEN[25827] = { title = "Lo'Gosh is Ready for Battle", description = "Thanks to your efforts, the great wolf ancient once more walks among us.\n\n<class>, I need you to return to the World Tree and let Ysera know that Lo'Gosh is ready to take the fight to the front lines.\n\nYou may also speak with her about how to go about unleashing the other ancients.\n\nLok'tar Ogar, my friend. You have been an inspiration.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Ysera at the World Tree in Mount Hyjal.Thanks to your efforts, the great wolf ancient once more walks among us.\n\n<class>, I need you to return to the World Tree and let Ysera know that Lo'Gosh is ready to take the fight to the front lines.\n\nYou may also speak with her about how to go about unleashing the other ancients.\n\nLok'tar Ogar, my friend. You have been an inspiration.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25828] = { title = "Goldrinn's Message to Ysera", description = "Goldrinn has been unleashed, and marches by our side! What you've done is nothing short of a miracle.\n\nWe must notify Ysera, at the World Tree. The sleeper is coordinating our reclamation of Hyjal, and she'll be delighted to hear that Goldrinn's legendary tenacity is at her disposal.\n\nYou may also speak with Ysera about how to unleash the other ancients.\n\nFarewell, <name>. And thank you. You're an inspiration!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Ysera at the World Tree in Mount Hyjal.Goldrinn has been unleashed, and marches by our side! What you've done is nothing short of a miracle.\n\nWe must notify Ysera, at the World Tree. The sleeper is coordinating our reclamation of Hyjal, and she'll be delighted to hear that Goldrinn's legendary tenacity is at her disposal.\n\nYou may also speak with Ysera about how to unleash the other ancients.\n\nFarewell, <name>. And thank you. You're an inspiration!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25829] = { title = "Tracking Quest - Goldrinn Hub Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[25830] = { title = "The Last Living Lorekeeper", description = "You have awakened the ancients, {name}, but the wilderness spirit Aessina remains silent. With her help, we can turn the tide of this attack and undo the damage Twilight's Hammer has done.\n\nThere may be one who can help us. The oldest of the trees, Nordu, stood in the center of what is now the Flamewake for thousands of years. His wisdom is as old as this mountain. If that old tree still lives, perhaps he can awaken Aessina... seek him out.", objectives = "Seek out Nordu, an Ancient of Lore, at the Flamewake in Mount Hyjal.", completion = "I ... have not yet ... perished." }
WordHunterWoW_QuestEN[25831] = { title = "Hamuul's Message to Ysera", description = "<name>, we have prepared the soil and enlisted the help of the enigmatic turtle ancient.\n\nPlease travel to Nordrassil, the World Tree, and notify Ysera that I am prepared to take the next step.\n\nIt is important the we awaken all of the ancients we can; speak to Ysera and find out where else on Mount Hyjal you are needed.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Ysera at the World Tree in Mount Hyjal.<name>, we have prepared the soil and enlisted the help of the enigmatic turtle ancient.\n\nPlease travel to Nordrassil, the World Tree, and notify Ysera that I am prepared to take the next step.\n\nIt is important the we awaken all of the ancients we can; speak to Ysera and find out where else on Mount Hyjal you are needed.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25832] = { title = "Return to Aviana", description = "{name}, you've done all you can here. This whole cavern is about to collapse in on itself!\n\nI'll gather up the last of our feathered steeds and ensure that the flamegate is sealed behind me.\n\nYou should go on ahead and let Aviana know that this abominable hatchery is no more!", objectives = "Return to Aviana at the Shrine of Aviana in Mount Hyjal.", completion = "<Aviana's face is immobile as you tell her about what happened within the hatchery.>\n\nThey stole my eggs, <class>. They took them to that foul place. Corrupted them.\n\nMy children stolen, tormented, killed in a vat of flame... Yes, we will make Twilight's Hammer pay.\n\nBut I confess, part of me wants to fly up and simply watch this whole... world... burn." }
WordHunterWoW_QuestEN[25833] = { title = "Aviana's Message to Ysera", description = "For ten thousand years I drifted without form within the Emerald Dream. I awake to a nightmare.\n\n<race>, seek out the dreamer - the dragon aspect you call Ysera - and let her know that I have returned and will aid the Guardians of Hyjal as they crush the Twilight's Hammer.\n\nI will fill their skies with suffering.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Ysera at the World Tree in Mount Hyjal.For ten thousand years I drifted without form within the Emerald Dream. I awake to a nightmare.\n\n<race>, seek out the dreamer - the dragon aspect you call Ysera - and let her know that I have returned and will aid the Guardians of Hyjal as they crush the Twilight's Hammer.\n\nI will fill their skies with suffering.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[25834] = { title = "Death by Proxy", description = "Can you hear them fighting down below, {name}? It would appear that the Grimtotem tauren are no longer in the good graces of the Horde. I don't know what happened, but we can turn this to our advantage.\n\nI will arrange a meeting with an ambassador from the Grimtotem. What I need you to do is put together a peaceful offering.\n\n<Force Commander Valen points to Cookie.>\n\nTalk to \"Cookie,\" {name}. He's already been briefed on what we need to do.", objectives = "Speak with \"Cookie\" McWeaksauce at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "The name be \"Cookie,\" lad: greatest cook 'cross Azeroth. Now the Commander's told me what we be needin' to do. To gain audience with the Grimtotem chief we're gonna have to cook up the finest of tauren cuisine.\n\nYe get me the ingredients and I'll put together an offerin' no tauren could refuse. Not even a grim tauren or whatever them things be." }
WordHunterWoW_QuestEN[25835] = { title = "Free Freewind Post", description = "Alas, it's time for you to leave. How quickly the chicks fall from the nest. Or, something.\n\nAnyway, you've done solid work here, my friend, but Quentin and the night elves have been crying that they urgently need your help with the Grimtotem at Freewind Post to the northwest.\n\nIf you ask me, it's a lost cause, but who knows... maybe with your help they'll actually succeed?", objectives = "Speak with Quentin at Freewind Post in Thousand Needles.", completion = "I'm glad that Fizzle finally sent you here. We're helping the tauren to retake Freewind Post and push back the Grimtotem." }
WordHunterWoW_QuestEN[25836] = { title = "Free Freewind Post", description = "Well, it looks like it's time for us to part ways, at least for a while. To the northwest, the tauren of Freewind Post are in desperate need of your assistance in pushing back the Grimtotem clan!\n\nYou know, you've been such a great help around here, I bet you're going to be their hero in no-time!", objectives = "Speak with Thalia Amberhide at Freewind Post in Thousand Needles.", completion = "I am honored that you have come to help, <class>. It was kind of Pozzik to send you." }
WordHunterWoW_QuestEN[25837] = { title = "A Proper Peace Offerin'", description = "To make the perfect peace offerin', I be needing the following ingredients:\n\nKalimdor eagle eggs, obtained from Kalimdor eagle nests. They be scattered about the forest to the west.\n\nRam haunches! You'll find ram haunches on Stonetalon rams.\n\nThe last ingredient be a little tougher to come by, but we be needin' it to make the ramlette. Head southwest to Boulderslide Canyon and find the kobold caves. Kill the kobolds and take their special cheese.\n\nBring it all back and I'll cook up a masterpiece!", objectives = "Collect 6 Kalimdor Eagle Eggs, 8 Ram Haunches and 10 Boulderslide Cheese pieces.", progress = "This ramlette ain't gonna make itself!", completion = "Stand back, <name>, there's about to be a flavor explosion and I wouldn't want ya gettin' hurt." }
WordHunterWoW_QuestEN[25838] = { title = "Help from Steelgrill's Depot", description = "With your help, we've managed to push toward Frostmane Retreat. Our forces will soon be in position to dwindle down the Frostmane trolls' reserves, leaving their village open to attack.\n\nThat's where the Gnomeregan covert ops team comes in. Their technicians have figured out a way to deploy operatives behind enemy lines without alerting the Frostmanes to our presence. Head to Steelgrill's Depot, just northeast of town, and speak with Delber Cranktoggle. He'll tell you more about it.", objectives = "Speak to Delber Cranktoggle at Steelgrill's Depot.", completion = "Ah, you must be the <race> that Captain Tharran said he'd be sending. I've already used the deploy-a-tron to get most of the covert ops team into position at Frostmane Retreat. They're just waiting on your arrival." }
WordHunterWoW_QuestEN[25839] = { title = "The Ultrasafe Personnel Launcher", description = "The cataclysm has brought our enemies closer to home, so the chief of Gnomeregan covert operations asked me to build a device to dispatch personnel quickly and quietly to any corner of Dun Morogh.\n\nBehold, the ultrasafe personnel launcher!\n\nWith a jolt of electricity and the benefit of a VLD parachute system, uh, that's 'very late deployment' for you laymen, this baby'll get you to the front in no time. Just hop aboard and prepare for flight! Slamp Wobblecog will be waiting for you in the drop zone.", objectives = "Use the Ultrasafe Personnel Launcher to deploy to Frostmane Retreat.", completion = "Don't worry, the feeling of being zapped won't stay with you for more than a few minutes. All in all, it's not a bad way to get where you're going. That parachute system needs some work, though. Very late deployment, indeed. Sometimes, too late. Anyway, we have a mission to carry out." }
WordHunterWoW_QuestEN[25840] = { title = "Eliminate the Resistance", description = "The Frostmane chieftain died in the initial trogg onslaught, but they've been led by a well-respected warrior ever since. Battok the Berserker was the one who organized the Frostmane retreat, the construction of the new village, and the strikes against Kharanos and the mountaineers.\n\nIf we remove Battok, the Frostmanes' organization should crumble, leaving the mountaineers free to pick off the survivors. Battok will be in the village, just east of here.", objectives = "Slay Battok the Berserker and 5 Frostmane Warriors in Frostmane Retreat.", completion = "Excellent job, <name>. With Battok dead, I'll send the signal to Captain Tharran. This should be the end of the Frostmane threat." }
WordHunterWoW_QuestEN[25841] = { title = "Strike From Above", description = "Delber's technicians have been up day and night helping us prepare for this strike. Aside from building and tuning the personnel launcher, his men have prepared the covert operations air wing for a strike on Frostmane Retreat. They'll be waiting for a signal to begin their strikes.\n\nTake this flare with you, and set it off near the cluster of buildings at the northern end of the village, and the buildings at the southern end of the village. The flying machines will make a quick strike at each site.", objectives = "Use the Signal Flare to call in airstrikes at the northern and southern ends of Frostmane Retreat.", completion = "Both you and the air wing performed admirably. There's no way that the Frostmanes will remain here now. All that remains is to begin mopping up the survivors." }
WordHunterWoW_QuestEN[25842] = { title = "Firefight", description = "It is... too late for me. Burned to all but the core. I have lived eons ... yet still my end seems sudden.\n\nNew life can spring from old. I still have wisdom to pass on. Please... do not let them take me before my work is done.\n\nKeep the tormentors at bay... just a little longer, {class}.\n\nGive me minutes, and I will give you a thousand lifetimes.", objectives = "Kill 5 Fiery Tormentors to keep them from Nordu.", progress = "Are you there, <class>? My vision is failing... I hear fighting...", completion = "Thank you, <race>.\n\nI am ready now.\n\nAll that I am, and all that this forest once was... it is now yours." }
WordHunterWoW_QuestEN[25843] = { title = "Tortolla's Revenge", description = "The mountain blooms again! If we act quickly, we can press our advantage.\n\nOur old friend Tortolla, the turtle ancient, is already on the move. At his own pace, of course...\n\nFind Tortolla east of here, at the head of the path leading down into the scorched plains. Our strongholds there fell early in the campaign, but perhaps now we can reclaim them.", objectives = "Speak to Tortolla at the Scorched Plain in Mount Hyjal.", completion = "<race>.\n\nI remember you. Savior of my children.\n\nThe time has come. For vengeance." }
WordHunterWoW_QuestEN[25844] = { title = "Sating the Savage Beast", description = "You heard the commander, {name}. Deliver me perfect offerin' to the Grimtotem ambassador! Him and his crew be waitin' for you at the bottom of the southeastern path.\n\nThis is sure to put us in the good graces of their chieftain!", objectives = "Deliver the Meaty Offering to Ton Windbow at Grimtotem Post in Stonetalon Mountains.", progress = "<Ton Window sniffs at the air and raises his left hand.>\n\nYou have brought something for us?", completion = "<Ton and his bodyguards scarf down the meaty offering.>\n\nThis... this is the greatest thing I have ever tasted. You may prove to be a valuable ally, but before the Grimtotem agree to work with the Alliance, you must agree to our terms. I will now give to you those terms as told to me by my leader. Take them back to your commander and see if he accepts." }
WordHunterWoW_QuestEN[25845] = { title = "Terms of Service", description = "Grimtotem need weapons! The Horde, empowered by their Warchief and with the help of their new goblin allies, have amassed powerful weaponry. Our armaments are simply no match for their firepower. Supply the Grimtotem with strong weapons and we will work together to destroy the Horde!\n\nThese are our demands! Supply the Grimtotem and we will fight for the Alliance!", objectives = "Deliver the Grimtotem Terms of Service to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", progress = "Well???", completion = "Weapons, eh?\n\n<Force Commander Valen sighs.>\n\nI'm about to make an executive decision here, <name>. Let's hope this pays off, else King Wrynn will have my head!" }
WordHunterWoW_QuestEN[25846] = { title = "Grundig Darkcloud, Chieftain of the Grimtotem", description = "The Grimtotem chieftain awaits your arrival, {name}. Take the weapon crates with you and head to Grimtotem Post, south of here.\n\nGood luck, {name}. Should anything happen to you I will personally notify your next of kin and let King Wrynn know what you have done for the Alliance.", objectives = "Deliver the Alliance Weapon Crates to Grundig Darkcloud at Grimtotem Post in Stonetalon Mountains.", progress = "Do you have the weapons?", completion = "These are fine weapons! Powerful steel! My warriors will be unstoppable armed with such weaponry. Magatha smiles down upon you, <name>.\n\nThere is but one thing I ask of you, perhaps two." }
WordHunterWoW_QuestEN[25847] = { title = "Grimtotem Supremacy", description = "Throughout all of Greatwood Vale you will find Grimtotem under attack by the Horde. Hellscream's armies show no mercy and no compassion, killing anything that stands in their way.\n\nBut no more! Take the armaments you brought for us and find Grimtotem in battle with the Horde. Give them the weapons of the Alliance and watch as they destroy their Horde assailants! Go, there is much work to do, ally.", objectives = "Use the Alliance Weapon Crate to arm 12 Grimtotem.", progress = "Have you armed the Grimtotem?", completion = "The fight is far from over, <name>. The Horde generals still live..." }
WordHunterWoW_QuestEN[25848] = { title = "Downfall", description = "By the time that we received word that Hellscream had sent another mag'har orc to oversee the Horde troops in southern Stonetalon, it was too late. Camp Aparaje was burned to the ground and all Grimtotem in the area incinerated.\n\nNow the Horde have four of their most fearsome generals commanding the battle for Greatwood Vale, including the mag'har, General Glubgok.\n\nYou must travel to the ruins of Camp Aparaje, south of here, and kill the generals. We stop the Horde NOW! Return to me with their mark!", objectives = "Kill the Horde generals at Camp Aparaje and recover the Insignia of the Horde General.", progress = "Are the generals dead?", completion = "<Grundig crushes the insignia in his massive fist.>\n\nYes, ally, you have done it! It will take Hellscream weeks to recover from this blow. Southern Stonetalon belongs to the Grimtotem... and the Alliance, of course." }
WordHunterWoW_QuestEN[25849] = { title = "When Archaeology Attacks", description = "Listen, lad, any good archaeologists know the risks that come with the job. If you don't unearth an ancient evil or get cursed by wicked spirits at least once in your career, you're not digging up anything worthwhile!\n\nNo, the real archaeologists know that a little thing like fossilized bones reanimating into skeletal creatures is no reason to stop working.\n\nI still need those fossil bones. Collect 'em from the fossil monsters roaming around and bring them back to me, and I'll reward you.", objectives = "Collect 20 Fossilized Bones from Living Fossils.", progress = "Don't be coy about it, now! Bring back a good armful of 'em!", completion = "See? Not bad, eh? Why, I almost wish all my finds decided to dig themselves up for me. It'd make my job a lot easier!\n\nOf course, you made it easier too, <name>. Much obliged." }
WordHunterWoW_QuestEN[25850] = { title = "Strike the Earth!", description = "In case you didn't notice, the land here in the Wetlands is pretty messed up. Floods, earthquakes... and on top of it all, even the ground's got a wild hair now.\n\nI never thought we'd be attacked by our own dig site, but sure enough, big chunks of it are now rampaging around trying to flatten any dwarf they see.\n\nYou look like a strong, strapping young {race}... mind going down there and slapping some sense into the clods?", objectives = "Kill 7 Paleolithic Elementals.", completion = "That's showin' em what for! Good on you." }
WordHunterWoW_QuestEN[25851] = { title = "Dances with Grimtotem", description = "Return now to your leader and tell him all that you have done for the Grimtotem. Tell him that the Alliance may pass freely across our borders.", objectives = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "Outstanding work, <name>! Now our forces only need to worry about the Horde as they enter Stonetalon." }
WordHunterWoW_QuestEN[25852] = { title = "All's Clear", description = "Pack up your gear, {name}, it's time to join up with the rest of the Northwatch forces in Southern Barrens. Your first mission in Southern Barrens should be fairly straightforward.\n\nTwo days ago we received a distress signal from Commander Walpole. He and his battalion are pinned down in Stonetalon Pass, just outside of Honor's Stand. They've got Horde all over the place! Get there and help him out. I'll forward news of our alliance with the Grimtotem to Northwatch command.", objectives = "Report to Commander Thomas Walpole at Stonetalon Pass in Southern Barrens.", completion = "You say the Grimtotem are no longer a threat? That's great, but we've got Horde all up our keesters!" }
WordHunterWoW_QuestEN[25853] = { title = "Tooling Around", description = "I'm in charge of supplying this dig. It's not that bad, but having to pick up and move out so fast wasn't exactly ideal!\n\nArchaeologists need tools, you know. You can't run around pulling up priceless antiquities with your bare hands. If you're going back to the dig site, can you bring back the tools that got left behind?", objectives = "Collect 6 Archaeologist's Tools.", progress = "Are they all here? We left a lot back there.", completion = "That's a relief! Maybe we can dig our way out of the hole we're still in, eh?\n\nNo, nevermind, just a bad joke." }
WordHunterWoW_QuestEN[25854] = { title = "I'll Call Him Bitey", description = "Have you heard some raptors are intelligent enough to be domesticated? It's true! I've seen hunters tame them.\n\nIt gets quite lonely out here, you know, even with Wenna to keep me company... a pet's just what I need to brighten my spirits. A little baby raptor would be the best!\n\nIf you're out there slaughtering the adults, would you mind bringing me back some mature eggs? You can tell if they're ready to hatch by the wobbling.", objectives = "Collect 6 Wobbling Raptor Eggs.", progress = "Do you have enough eggs? I can't take my chances with only one. Statistics, you know.", completion = "Wonderful! These should be ready to hatch within the day...\n\nNow I just need to cobble up a raptor pen before they all hatch nigh-simultaneously. What could go wrong?" }
WordHunterWoW_QuestEN[25855] = { title = "Gizmos and Gadgets", description = "I've been coming up short on parts recently for my engineering projects, and the other day I finally saw why: the Mosshide gnolls have been making off with them!\n\nI don't have any idea what they could possibly want them for, but I need those gizmos back. They're probably strewn all over the marsh by now, but if you see any, could you gather them and bring them back?", objectives = "Find 7 Swiftgear Gizmos.", progress = "Did you find them?", completion = "Oh, wonderful! I'll be able to start reassembling these right away. Thank you so much!" }
WordHunterWoW_QuestEN[25856] = { title = "Crocolisk Hides", description = "I've skinned crocs in the wetlands for years, {class}. Things have changed though.\n\nYou see, not to bore you with a sob story, but when the cataclysm flooded Menethil Harbor, our house went with it. My wife and kids don't have a place to stay, and I need to make as much money as I can to get us under a roof again.\n\nI've been skinning crocs 'til I was too tired to move, but I still need more skins to sell. If you bring me some croc hides, I'll pay you a bit for them.", objectives = "Collect 10 Marshy Crocolisk Hides from Wetlands Crocolisks.", progress = "Got any croc hides for me?", completion = "I'm much obliged, <class>. This'll go a ways towards getting my family back on their feet." }
WordHunterWoW_QuestEN[25857] = { title = "Hunting Horrorjaw", description = "I've been tempted to go after the big kill... the largest crocolisk out there, Horrorjaw. His hide alone would be enough to get my family out of this hole.\n\nBut I'm no fool. One mistake and I could lose a leg, or my life, and then where would my wife and kids be? Still homeless and without a father to care for them.\n\nIt's not my proudest moment, but I'll pick my family's safety over pride any day. Please, {class}... hunt Horrorjaw for me. You'll find him in his shady pool to the north, lurking.", objectives = "Slay Horrorjaw and collect Horrorjaw's Hide.", progress = "Did you get it? Do you have Horrorjaw's hide?", completion = "Amazing! You're a true hero, <name>. I'll never forget what you've done for me and my family.\n\nI know it's not much, but please, take this with my blessing." }
WordHunterWoW_QuestEN[25858] = { title = "By Her Lady's Word", description = "Lady Sira'kess has begun preparations for the ritual of summoning, but the Crucible of Nazsharin has been stolen from us. The Kvaldir have surely taken it with them as they retreated to shallower waters.\n\nSpeak to the caste leaders to secure a war party, and then lead them in retrieving the artifact from Biel'aran Ridge to the east.\n\nI trust you my Battlemaiden, for you have never failed in any task that I have given you. As I am revered to the Queen, so are you revered to me. Go with my blessings.", objectives = "Speak to Fathom-Lord Zin'jatar, Lady Sira'kess, and Overseer Idra'kess.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Reinforcements have begun to circle the waters around the ledge, preparing for the attack. They await only your lead." }
WordHunterWoW_QuestEN[25859] = { title = "No Trespass Forgiven", description = "I know that you, like our revered lady, have unfortunate streaks of mercy that you succumb to at times. I would advise against such kindnesses this day. The Kvaldir are proud, and they will strike back if we do not cripple them completely. Kill all that you find.\n\nSadly, I have the inglorious task of making sure none return to the city, so you can go have all of the fun. I will cheer you on though, of course.", objectives = "Kill 20 Kvaldir on the Vrykul Ledge.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Not one slipped through to the bridge. Not one.\n\nIt was very boring. I'd appreciate it if you shared a little next time." }
WordHunterWoW_QuestEN[25860] = { title = "At All Costs", description = "We are to begin the ritual immediately, and you are to see to it that we are not interrupted.\n\nSlaughter any Kvaldir that enter the temple. See to it that my priestesses live to see their task complete, no matter the cost.", objectives = "Kill 20 Kvaldir attackers within Quel'Dormir Temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "I am trusting you to safeguard us, Battlemaiden.", completion = "Azjentus is to be taken at his word. Lady Naz'jar's Honor Guard should be sufficient to see the rest of the ritual through." }
WordHunterWoW_QuestEN[25861] = { title = "Setting An Example", description = "The High-Shaman are in the buildings nearby, chanting and taunting, but not daring to approach me. These Kvaldir find their courage and strength only in the mist. They are a pitiful nuisance beneath the waves.\n\nI came bearing a message. If your ladyship has the time, bring a high-shaman to my feet that I might deliver this message to him and his people.", objectives = "Bring a Kvaldir High-Shaman to the feet of Executioner Varathress.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "If your ladyship has the time, bring a high-shaman to my feet that I might deliver a message to him and his people.", completion = "My scythe is sated. Thank you, my lady." }
WordHunterWoW_QuestEN[25862] = { title = "Stolen Property", description = "Our revered lady has sent me to aid you in your task. She wants you to retrieve the stolen Crucible of Nazsharin and bring it back here as soon as you can.\n\nShe grows impatient to start the ritual of summoning so that we might fully begin our preparations for war.", objectives = "Retrieve the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "The crucible looks far too heavy to carry on your own, but more than enough naga forces remain to prepare it for transport." }
WordHunterWoW_QuestEN[25863] = { title = "Chosen Burden", description = "With the Crucible of Nazsharin, all that remains is to inform Lady Naz'jar of your success.", objectives = "Return to the western edge of the Biel'aran Ridge with news of the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Well done, my Battlemaiden.\n\nThis crucible will serve as a font of power for our summoning ritual. With it, Sira'kess will beckon our allies from the depths to bolster our already swelling forces." }
WordHunterWoW_QuestEN[25864] = { title = "Dinosaur Crisis", description = "We've been getting more and more reports of raptor attacks in the area. I'm seeing to it that this place is safe enough for more settlement to start occuring, so I've put a bounty on the buggers.\n\nA lot have been cleared out already, but the Highland raptors to the north have been growing in number. That won't be true for long, now will it?\n\nClear out a good deal of Highland raptors, and I'll have a nice reward for you.", objectives = "Kill 8 Highland Raptors of any kind.", progress = "Don't be shy with those now. They're dastardly things.", completion = "A job well done. Consider this reward not from me, but from Ironforge; the preservation of Khaz Modan is a matter that concerns every dwarf." }
WordHunterWoW_QuestEN[25865] = { title = "The Mosshide Job", description = "You seem trustworthy enough to help me out with my real problem, {name}. I was sent here by Ironforge to recover a shipment of gold ingots.\n\nThe ingots are part of the Ironforge Royal Treasury, stamped with the royal seal... only an idiot would steal them for profit, far too easy to trace. Oddly enough, this area is full of idiots: Mosshide gnolls.\n\nI don't know how many gnolls you've fought before, but they're foul and brutal beasts, and dangerous. I need you to slay them and recover the missing ingots.", objectives = "Recover 8 Ironforge Ingots from Mosshide Gnolls.", progress = "There should be about eight ingots stolen.", completion = "Well done! The Ironforge Guard appreciates this, <name>. You've done our city a fine favor.\n\nBut something new has come up..." }
WordHunterWoW_QuestEN[25866] = { title = "Dark Iron Trappers", description = "You may have seen them while you were out, but the Dark Iron clan has been spotted in this area. They're never up to any good, and it looks like they're kidnapping the Mosshide gnolls for some reason.\n\nI don't know what their game is, but we're putting a stop to this before more foul play occurs. Go and stop them.\n\nAnd if you're worried about fairness, try askin' them politely first and see how far that gets you.", objectives = "Kill 10 Dark Iron Trappers.", completion = "I don't suppose they agreed to come along quietly? Didn't think so." }
WordHunterWoW_QuestEN[25867] = { title = "Gnoll Escape", description = "I know we were just attacking the gnolls ourselves, but I'm not about to let the Dark Iron capture them as slaves. For one, we found the thieves and took back what was missing, so justice is served; for another, whatever work the Dark Iron will be putting them to isn't something I want to allow.\n\nEither way, the gnolls need to be freed. The trappers should have keys on them, so use those to open the cages.", objectives = "Obtain Trapper's Keys from Dark Iron Trappers and use them to free 6 Gnolls from the Gnoll Cages.", completion = "That should do it! The more gnolls those fools have to chase after, the easier it'll be to keep them in line." }
WordHunterWoW_QuestEN[25868] = { title = "Yorla Darksnare", description = "I've found out who's pulling the strings on this operation here. Yorla Darksnare is directing the Dark Iron dwarves from a camp to the east, and it might've been orders to have the gnolls steal Ironforge's gold in the first place.\n\nWhat's more, she's a wanted criminal... she's been inciting rebellion and attacks against Ironforge since Magni was still alive.\n\nShe can't slip through our fingers this time, {name}. Go and get her!", objectives = "Slay Yorla Darksnare.", completion = "A job well done! You've brought one of Ironforge's most wanted to justice today, <name>. I'd say you've earned a mighty fine reward." }
WordHunterWoW_QuestEN[25869] = { title = "Grimtotem in the Post", description = "The journey ahead must begin with you killing the Grimtotem invaders at Freewind Post. If you can't stop them here, we won't be able to move into their territory.", objectives = "Slay 10 Grimtotem Invaders.", completion = "Grim business, that.<Quentin coughs.>\n\nNo pun intended." }
WordHunterWoW_QuestEN[25870] = { title = "Grimtotem in the Post", description = "You must do away with the Grimtotem invaders at Freewind Post. They brought it on themselves, the cowards!\n\nWe can't take the fight to their territory with our back to them. Please help us take back our home, {class}.", objectives = "Slay 10 Grimtotem Invaders.", completion = "It's a good start. Normally, I wouldn't wish harm on any of the Earth Mother's creatures.\n\nBut attacking us at our most vulnerable moment?! They deserve to die!" }
WordHunterWoW_QuestEN[25871] = { title = "Save the Sentinel", description = "<Brienna waves a note around with Taur-ahe markings on it.>\n\nThose monsters have captured one of our sentinels! They're threatening to kill her if we don't pull back!\n\nWe don't negotiate with cowardly beasts! Please, if you can, rescue her before it's too late, {class}.", objectives = "Rescue the Feralas Sentinel.", completion = "Thank you for freeing her, <name>. Those Grimtotem monsters would have killed her in cold blood." }
WordHunterWoW_QuestEN[25872] = { title = "The Brave and the Bold", description = "<Rau dismissively waves a note around with Taur-ahe markings on it.>\n\nThose mongrels have captured one of our braves! They're threatening to kill him if we don't pull back!\n\nWe'll never allow those Grimtotem cowards to keep Freewind Post! Please, rescue him before it's too late, {class}.", objectives = "Rescue the Freewind Brave.", completion = "Thank you for freeing him, <name>. Those Grimtotem would have killed him in cold blood." }
WordHunterWoW_QuestEN[25873] = { title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", objectives = "Collect Longhorn's Horn.", progress = "What's this, <class>?", completion = "A traitor amongst the tauren?\n\nI've never heard of such a thing. Clan rivalries and warfare are one thing, but killing your own in cold blood.\n\n<Quentin shakes his head in disbelief.>" }
WordHunterWoW_QuestEN[25874] = { title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", objectives = "Collect Longhorn's Horn.", progress = "<name>? What news do you have?", completion = "The cliffwatcher was a Grimtotem spy?! No wonder we had no warning!\n\n<Thalia seethes with barely contained rage.>\n\nI don't want that damned thing. Throw it into the water and let the Longhorn name never be spoken again!" }
WordHunterWoW_QuestEN[25875] = { title = "Gnome on the Inside", description = "Mirkfallon Lake is crawling with Horde. The goblins have set up shop and they aren't going to leave until all the oil under Stonetalon is sucked dry.\n\nThankfully I have a gnome on the inside that's been collecting information for us. If anyone knows what's going on with that bomb, it's my inside gnome.\n\nMake your way to the Sludgewerks, north of here, and find Minx. She'll be disguised as a \"goblin\" pump controller.", objectives = "Seek out Minx who is disguised as a \"Goblin\" Pump Controller at the Sludgewerks in Stonetalon Mountains.", completion = "Get in here and hug a wall! I can't risk blowing my cover!" }
WordHunterWoW_QuestEN[25876] = { title = "It's Up There!", description = "Listen, I've been tracking this bomb since you rescued me in Ashenvale. Whatever they're doing with it is going to happen real soon.\n\nAt the top of the large oil rig is a control room. Inside that control room you'll find a Krom'gar log book. That log book is the key to where this bomb is heading. Get up there and get the log book! Bring it back here and I'll decipher it for you.", objectives = "Steal the Krom'gar Log Book.", progress = "Did you recover the log book?", completion = "OH NO! They plan to \"test\" the bomb at Thal'darah Grove! That's the school for young druids located in the heart of Battlescar Valley. You've got to return to Barus with this information! Master Thal'darah must be warned!" }
WordHunterWoW_QuestEN[25877] = { title = "No Time for Goodbyes!", description = "RUN! Get out of here, {name}. Get back to Barus and inform him of what you've discovered. He'll arrange for you to get safely across Battlescar Valley to Thal'darah Overlook.\n\nIt's not too late to save those young druids!", objectives = "Return to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", completion = "Blasted Horde! I've got friends at that grove. Hopefully you know how to ride a hippogryph. We've got to get you to Master Thal'darah at the overlook immediately!" }
WordHunterWoW_QuestEN[25878] = { title = "Schemin' That Sabotage", description = "Goblins... What would this world be without goblins? I'll tell you what: CLEAN!\n\nThose filthy little scum suckers have planted their oil pumps all over the lake with the hope of extracting every last drop of oil that exists in Stonetalon. At each oil pump they've stationed an oil pump controller whose sole job it is to watch the pump and make sure nothing goes wrong.\n\nSomething is about to go wrong.\n\nTake out the goblin pump controllers and take their pump controls. Use 'em to overload the pumps!", objectives = "Use the Goblin Pump Controller to destroy 4 Goblin Oil Pumps.", completion = "I could see the explosions from here, <name>! The Horde won't be refueling from Mirkfallon anymore, thanks to you!" }
WordHunterWoW_QuestEN[25879] = { title = "The Lumbering Oaf Problem", description = "Ever seen a hobgoblin? They're another vile goblin creation. Take a goblin, make it even uglier, fatter, bigger and stupider and you have a hobgoblin. Add to all of that a nasty mean streak and we've got a problem.\n\nThese lumbering oafs wander the Sludgewerks and Mirkfallon Lake, acting as muscle to the goblins.\n\nGet out there and thin 'em out. Permanently.", objectives = "Kill 10 Lumbering Oafs.", completion = "Slowly, but surely, we pick away at the Horde's numbers. They won't have a leg to stand on when this war really opens up." }
WordHunterWoW_QuestEN[25880] = { title = "Warn Master Thal'darah", description = "There are dozens of students at Thal'darah Grove. Most of them have no means of defending themselves, ripe for the slaughter.\n\nYou must get word to Master Thal'darah of the Horde's plans. He will direct you in what you must do next.\n\nFiora Moonsoar has granted you the use of her fastest hippogryph. Take it now to Thal'darah Overlook! Don't look back, {name}! The Horde must be stopped!", objectives = "Report to Master Thal'darah at Thal'darah Overlook in Stonetalon Mountains.", completion = "These are dire times, indeed, <name>. Our outpost in Stonetalon Peak has been overrun by fiendish creatures from the depths and the Horde seeks to destroy us. We need a hero, <name>; a soldier of the Alliance strong enough to guide us through these trying times." }
WordHunterWoW_QuestEN[25881] = { title = "Lost Wardens", description = "We held out as long as we could, {class}. But the flames... the heat... We lost the whole town.\n\nCaptain Irontree refused to pull back when the flames engulfed us. Our forces are scattered. Maybe some of the others survived? We can mount a counter-attack!\n\nGo into the Scorched Plain and rescue any lost wardens that got separated from the group. Then find Captain Irontree - he's probably taken up a fortified position in the middle of the fighting. ", objectives = "Locate and rescue 8 Lost Wardens.", progress = "What?", completion = "You've assembled the survivors? Good, good. And the rest of the mountain - healed?\n\nHaha, strike me down! We're on the front lines again!" }
WordHunterWoW_QuestEN[25882] = { title = "A Hand at the Ranch", description = "Captain Tharran asked me to pass along his thanks for your help and congratulations on a successful mission. He and his men are cleaning up the last of the trolls and tending to the wounded.\n\nHe also wanted me to ask you to check out reports about troll raids on the Amberstill Ranch to the north. Ask for Sergeant Flinthammer when you arrive.", objectives = "Speak with Sergeant Flinthammer at Amberstill Ranch.", completion = "So you're the one who's been helping Captain Tharran beat back the Frostmane trolls? I've seen your name in the reports. It's good to finally meet you. You might be just the <class> we need to help secure the ranch." }
WordHunterWoW_QuestEN[25883] = { title = "How Disarming", description = "Naga weapons...\n\nAs you cast your vision on the naga Holding Pens, you see dozens of similar stacks of tridents positioned strategically.\n\nDestroying their weapons could only hamper whatever wicked designs they are carrying out in this region...", objectives = "You must destroy 6 sets of Naga Tridents.", completion = "You're confident that your assault on the naga armaments has made an impact on their effectiveness." }
WordHunterWoW_QuestEN[25884] = { title = "Come Hell or High Water", description = "Oh fer the love of...\n\nI know our survivor friend here means well, but the lad's been severely traumatized.\n\nThere only be one way ta deal with these accursed beasts, an' that be a fine dwarven axe buried hilt-deep in the noggin.\n\nPile up enough o' their corpses an' they'll think twice before fiddlin' with yer tasty bits.\n\nMark me words laddie, them buggers don't like the sight o' their own blood any more than you or I.\n\nNow git out there an' give 'em what fer!", objectives = "Kill 12 Zin'jatar Naga at The Clutch in Kelp'thar Forest.", completion = "The waters surrounding the Holding Pens are red with the blood of the naga.\n\nRendel would be proud!" }
WordHunterWoW_QuestEN[25885] = { title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", objectives = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, <class>?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can gradually eat less of it and avoid that side-effect.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[25886] = { title = "Pressing the Advantage", description = "It looks like most of the Twilight's Hammer has fallen back to regroup for another assault. Their most dedicated are staying behind to hold the line. This is our chance to whittle away at their leadership.\n\nRange out along the Scorched Plain and crush the Twilight Field Captains. We'll remove them from the equation!", objectives = "Slay 4 Twilight Field Captains.", completion = "Terrific! Twilight's Hammer will no doubt try to re-take the mountain, but they'll have to do so without the leadership of those fat-for-brains thugs." }
WordHunterWoW_QuestEN[25887] = { title = "Wake of Destruction", description = "Our time here draws to a close. I must somehow follow the trail of these naga captives if we are to discover their purposes in this region.\n\nBut before I move on, I would see the destruction of this operation!\n\nNevermind their numbers, I have a plan that has the potential to even the odds.\n\nOutside this cave, famished great sharks, displaced by these naga, seek food.\n\nIn their weakened state, they will be susceptible to suggestion. Use this orb to subdue them, then direct them against our enemy.", objectives = "Use the Orb of Suggestion to subdue a Famished Great Shark, then use it to destroy 12 Zin'jatar at The Clutch.", completion = "It is as it should be.\n\nNow the way is clear to deal these naga a crippling blow." }
WordHunterWoW_QuestEN[25888] = { title = "Decompression", description = "I simply cannot bear the thought of so many others like this soldier imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", objectives = "Use Moanah's Breathstone on 10 Imprisoned Soldiers in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift." }
WordHunterWoW_QuestEN[25889] = { title = "Save the Children!", description = "My poor, defenseless young students are stranded at Thal'darah Grove. With the battle raging across Battlescar Valley, they have no means of escaping. We must save the children before the Horde drops their bomb!\n\nTake my hippogryph and use it to rescue the young druids of Thal'darah Grove. Drop them off at the hippogryph post here in town.\n\nSave them all, {name}! You truly are our only hope.", objectives = "Use Master Thal'darah's Hippogryph to rescue 5 Helpless Young Druids from Thal'darah Grove.", progress = "Use the whistle to call for my hippogryph, <name>.", completion = "Praise you, <name>. The hero we have been searching for has finally arrived, and not a moment too soon." }
WordHunterWoW_QuestEN[25890] = { title = "Nespirah", description = "It is clear to me at this point what must be done, {name}.\n\nThe naga can only be obtaining these pearls from one place: Nespirah, the ancient, shelled creature that rests outside of this cave.  Why Nespirah would submit to the naga, however, is beyond my understanding.\n\nWe can enter Nespirah's body cavity through a small tube near the exit to this cave.  I must first fetch my master, then we can meet you on the inside.  We will convene in Nespirah's northwestern entrance.", objectives = "Enter Nespirah's northwestern entrance, then find a way to communicate with it.", completion = "Erunak trusts this task to me?  Very well, let's see what we can learn from the ancient one." }
